#[derive(Clone, Default)]
struct RuntimeScopes {
    inner: Arc<Mutex<RuntimeScopeState>>,
}

#[derive(Default)]
struct RuntimeScopeState {
    sessions: HashMap<Id, SessionRuntimeScope>,
    closed_sessions: HashSet<Id>,
}

#[derive(Default)]
struct SessionRuntimeScope {
    turns: HashMap<Id, AgentRuntimeScope>,
    background_terminals: HashMap<Id, BackgroundTerminalHandle>,
}

struct AgentRuntimeScope {
    cancellation: CancellationToken,
    step_inputs: mpsc::UnboundedSender<RuntimeStepInput>,
}

#[derive(Clone, Debug)]
enum RuntimeStepInput {
    Persistent(Id),
    Notification(StepRequest),
}

#[derive(Serialize)]
struct RuntimeScopeSnapshot {
    session_scopes: usize,
    turn_scopes: usize,
    owned_resources: usize,
}

impl RuntimeScopes {
    async fn open_turn(
        &self,
        session_id: Id,
        turn_id: Id,
        token: CancellationToken,
    ) -> Result<mpsc::UnboundedReceiver<RuntimeStepInput>, ApiError> {
        let mut state = self.inner.lock().await;
        if state.closed_sessions.contains(&session_id) {
            return Err(ApiError::Conflict("Session runtime is closed".into()));
        }
        if state
            .sessions
            .values()
            .any(|session| session.turns.contains_key(&turn_id))
        {
            return Err(ApiError::Conflict(
                "turn already has an active Agent scope".into(),
            ));
        }
        let (step_inputs, receiver) = mpsc::unbounded_channel();
        state.sessions.entry(session_id).or_default().turns.insert(
            turn_id,
            AgentRuntimeScope {
                cancellation: token,
                step_inputs,
            },
        );
        Ok(receiver)
    }

    async fn close_turn(&self, turn_id: &Id) {
        let mut state = self.inner.lock().await;
        let mut empty_session = None;
        for (session_id, session) in &mut state.sessions {
            if session.turns.remove(turn_id).is_some() {
                if session.turns.is_empty() && session.background_terminals.is_empty() {
                    empty_session = Some(session_id.clone());
                }
                break;
            }
        }
        if let Some(session_id) = empty_session {
            state.sessions.remove(&session_id);
        }
    }

    async fn turn_token(&self, turn_id: &Id) -> Option<CancellationToken> {
        self.inner
            .lock()
            .await
            .sessions
            .values()
            .find_map(|session| {
                session
                    .turns
                    .get(turn_id)
                    .map(|scope| scope.cancellation.clone())
            })
    }

    async fn submit_step_input(&self, turn_id: &Id, input_id: Id) -> Result<(), ApiError> {
        let sender = self
            .inner
            .lock()
            .await
            .sessions
            .values()
            .find_map(|session| {
                session
                    .turns
                    .get(turn_id)
                    .map(|scope| scope.step_inputs.clone())
            })
            .ok_or_else(|| ApiError::Conflict("target Turn has no active Agent scope".into()))?;
        sender
            .send(RuntimeStepInput::Persistent(input_id))
            .map_err(|_| ApiError::Conflict("target Agent no longer accepts Step requests".into()))
    }

    /// Delivers a content-free background completion signal to every active
    /// Agent in the owning Session. The caller persists the same notification
    /// before delivery, so a racing or absent Agent observes it on its next
    /// context build instead of losing the completion.
    async fn submit_session_notification(&self, session_id: &Id, request: StepRequest) -> usize {
        let senders = self
            .inner
            .lock()
            .await
            .sessions
            .get(session_id)
            .map(|session| {
                session
                    .turns
                    .values()
                    .map(|scope| scope.step_inputs.clone())
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default();
        senders
            .into_iter()
            .filter(|sender| {
                sender
                    .send(RuntimeStepInput::Notification(request.clone()))
                    .is_ok()
            })
            .count()
    }

    async fn contains_turn(&self, turn_id: &Id) -> bool {
        self.turn_token(turn_id).await.is_some()
    }

    async fn wait_for_turn_closed(&self, turn_id: &Id, timeout: Duration) -> Result<(), ApiError> {
        tokio::time::timeout(timeout, async {
            while self.contains_turn(turn_id).await {
                tokio::time::sleep(Duration::from_millis(1)).await;
            }
        })
        .await
        .map_err(|_| ApiError::Conflict("previous Agent scope did not close before resume".into()))
    }

    async fn register_background_terminal(
        &self,
        session_id: Id,
        terminal_id: Id,
        handle: BackgroundTerminalHandle,
    ) -> Result<(), ApiError> {
        let mut state = self.inner.lock().await;
        if state.closed_sessions.contains(&session_id) {
            return Err(ApiError::Conflict("Session runtime is closed".into()));
        }
        if state
            .sessions
            .values()
            .any(|session| session.background_terminals.contains_key(&terminal_id))
        {
            return Err(ApiError::Conflict(
                "background terminal already belongs to a Session scope".into(),
            ));
        }
        state
            .sessions
            .entry(session_id)
            .or_default()
            .background_terminals
            .insert(terminal_id, handle);
        Ok(())
    }

    async fn background_terminal(&self, terminal_id: &Id) -> Option<BackgroundTerminalHandle> {
        self.inner
            .lock()
            .await
            .sessions
            .values()
            .find_map(|session| session.background_terminals.get(terminal_id).cloned())
    }

    async fn remove_background_terminal(
        &self,
        terminal_id: &Id,
    ) -> Option<BackgroundTerminalHandle> {
        let mut state = self.inner.lock().await;
        let mut removed = None;
        let mut empty_session = None;
        for (session_id, session) in &mut state.sessions {
            if let Some(handle) = session.background_terminals.remove(terminal_id) {
                removed = Some(handle);
                if session.turns.is_empty() && session.background_terminals.is_empty() {
                    empty_session = Some(session_id.clone());
                }
                break;
            }
        }
        if let Some(session_id) = empty_session {
            state.sessions.remove(&session_id);
        }
        removed
    }

    async fn close_session(&self, session_id: &Id) -> usize {
        let mut state = self.inner.lock().await;
        state.closed_sessions.insert(session_id.clone());
        let session = state.sessions.remove(session_id);
        if let Some(session) = session {
            let count = session.turns.len();
            for turn in session.turns.into_values() {
                turn.cancellation.cancel();
            }
            for terminal in session.background_terminals.into_values() {
                let _ = terminal.commands.send(BackgroundTerminalCommand::Stop);
            }
            count
        } else {
            0
        }
    }

    async fn reopen_session(&self, session_id: &Id) {
        self.inner.lock().await.closed_sessions.remove(session_id);
    }

    async fn shutdown_all(&self) -> usize {
        let state = self.inner.lock().await;
        let mut stopped = 0;
        for session in state.sessions.values() {
            for turn in session.turns.values() {
                turn.cancellation.cancel();
            }
            for terminal in session.background_terminals.values() {
                let _ = terminal.commands.send(BackgroundTerminalCommand::Stop);
                stopped += 1;
            }
        }
        stopped
    }

    async fn snapshot(&self) -> RuntimeScopeSnapshot {
        let state = self.inner.lock().await;
        RuntimeScopeSnapshot {
            session_scopes: state.sessions.len(),
            turn_scopes: state
                .sessions
                .values()
                .map(|session| session.turns.len())
                .sum(),
            owned_resources: state
                .sessions
                .values()
                .map(|session| session.background_terminals.len())
                .sum(),
        }
    }
}

