struct RunningTurnGuard {
    runtime_scopes: RuntimeScopes,
    turn_id: Id,
    armed: bool,
}

impl RunningTurnGuard {
    fn new(runtime_scopes: RuntimeScopes, turn_id: Id) -> Self {
        Self {
            runtime_scopes,
            turn_id,
            armed: true,
        }
    }

    async fn close(mut self) {
        self.runtime_scopes.close_turn(&self.turn_id).await;
        self.armed = false;
    }
}

impl Drop for RunningTurnGuard {
    fn drop(&mut self) {
        if !self.armed {
            return;
        }
        let runtime_scopes = self.runtime_scopes.clone();
        let turn_id = self.turn_id.clone();
        if let Ok(runtime) = tokio::runtime::Handle::try_current() {
            runtime.spawn(async move {
                runtime_scopes.close_turn(&turn_id).await;
            });
        }
    }
}

