#[derive(Clone)]
struct DaemonManagedAgentAdapter {
    state: AppState,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct ManagedAgentToolRequest {
    session_id: Id,
    tool: String,
    arguments: serde_json::Value,
    /// `None` returns an awaiting-approval result. A UI or higher-level adapter
    /// may resume later; the Reference E2E supplies an explicit local decision.
    approval_decision: Option<bool>,
}

#[async_trait::async_trait]
impl AgentAdapter for DaemonManagedAgentAdapter {
    fn descriptor(&self) -> AdapterDescriptor {
        AdapterDescriptor {
            schema_version: 1,
            adapter_id: "s-code-daemon-managed".into(),
            adapter_version: env!("CARGO_PKG_VERSION").into(),
            protocol_version: "1".into(),
            governance_level: GovernanceLevel::ManagedExecution,
            enforcement_points: EnforcementPoint::all(),
            fail_closed: true,
            managed_execution_plane: true,
            supported_event_kinds: BTreeSet::from([
                "approval.required".into(),
                "tool.completed".into(),
                "tool.denied".into(),
                "tool.failed".into(),
            ]),
        }
    }

    async fn invoke(
        &self,
        invocation: AgentInvocation,
    ) -> Result<AgentInvocationResult, AdapterError> {
        invocation.validate()?;
        if invocation.action != EnforcementPoint::Tool {
            return Err(AdapterError::EnforcementUnavailable);
        }
        let request: ManagedAgentToolRequest =
            serde_json::from_value(invocation.request.clone())
                .map_err(|error| AdapterError::Execution(error.to_string()))?;
        if request.tool.is_empty() || request.tool.len() > 128 || !request.arguments.is_object() {
            return Err(AdapterError::InvalidInvocation);
        }
        let mut outcome = self
            .state
            .execution
            .submit(
                &request.session_id,
                SubmitToolCall {
                    scope: invocation.scope.clone(),
                    tool: request.tool,
                    arguments: request.arguments,
                },
            )
            .await
            .map_err(|error| AdapterError::Execution(error.to_string()))?;
        if let ToolCallOutcome::AwaitingApproval { approval, .. } = &outcome {
            publish_tool_outcome(&self.state, &invocation.scope, &outcome)
                .await
                .map_err(|_| AdapterError::Execution("audit publication failed".into()))?;
            if let Some(approved) = request.approval_decision {
                outcome = self
                    .state
                    .execution
                    .resolve(
                        &approval.id,
                        ResolveApproval {
                            scope: invocation.scope.clone(),
                            approved,
                            approval_scope: s_code_protocol::ApprovalScope::Once,
                        },
                    )
                    .await
                    .map_err(|error| AdapterError::Execution(error.to_string()))?;
                publish_tool_outcome(&self.state, &invocation.scope, &outcome)
                    .await
                    .map_err(|_| AdapterError::Execution("audit publication failed".into()))?;
            }
        } else {
            publish_tool_outcome(&self.state, &invocation.scope, &outcome)
                .await
                .map_err(|_| AdapterError::Execution("audit publication failed".into()))?;
        }
        managed_agent_result(invocation, &outcome)
    }
}

fn managed_agent_result(
    invocation: AgentInvocation,
    outcome: &ToolCallOutcome,
) -> Result<AgentInvocationResult, AdapterError> {
    let (status, tool_call, outcome_name) = match outcome {
        ToolCallOutcome::AwaitingApproval { tool_call, .. } => (
            AgentInvocationStatus::AwaitingApproval,
            tool_call,
            "awaiting_approval",
        ),
        ToolCallOutcome::Denied { tool_call } => {
            (AgentInvocationStatus::Rejected, tool_call, "denied")
        }
        ToolCallOutcome::Completed { tool_call } => {
            (AgentInvocationStatus::Completed, tool_call, "completed")
        }
        ToolCallOutcome::Failed { tool_call } => {
            (AgentInvocationStatus::Failed, tool_call, "failed")
        }
    };
    let content_free = serde_json::json!({
        "outcome": outcome_name,
        "tool_call_id": tool_call.request.id,
        "tool": tool_call.request.tool,
        "policy_id": tool_call.policy.policy_id,
        "policy_version": tool_call.policy.policy_version,
        "central_policy_applied": tool_call.central_policy_applied,
    });
    Ok(AgentInvocationResult {
        schema_version: 1,
        run_id: invocation.run_id,
        node_id: invocation.node_id,
        idempotency_key: invocation.idempotency_key,
        status,
        usage_micros: 0,
        artifacts: vec![],
        result_sha256: payload_sha256(&content_free)?,
    })
}

