#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct BrowserBootstrapRequest {
    token: String,
}

async fn issue_browser_bootstrap(
    State(state): State<AppState>,
    headers: HeaderMap,
) -> Result<Json<serde_json::Value>, ApiError> {
    let supplied = headers
        .get(header::AUTHORIZATION)
        .and_then(|value| value.to_str().ok())
        .and_then(|value| value.strip_prefix("Bearer "));
    let InteractiveAuth::DevelopmentToken(expected) = &state.interactive_auth else {
        return Err(ApiError::Unauthorized);
    };
    if supplied != Some(expected.as_ref()) {
        return Err(ApiError::Unauthorized);
    }
    let token = state
        .browser_auth
        .lock()
        .expect("browser auth mutex poisoned")
        .issue_bootstrap();
    Ok(Json(serde_json::json!({"token": token})))
}

async fn browser_bootstrap(
    State(state): State<AppState>,
    Json(request): Json<BrowserBootstrapRequest>,
) -> Result<Response, ApiError> {
    if !matches!(
        &state.interactive_auth,
        InteractiveAuth::DevelopmentToken(_)
    ) {
        return Err(ApiError::Unauthorized);
    }
    let session = state
        .browser_auth
        .lock()
        .expect("browser auth mutex poisoned")
        .exchange(&request.token)
        .ok_or(ApiError::Unauthorized)?;
    let cookie =
        format!("s_code_session={session}; HttpOnly; SameSite=Strict; Path=/; Max-Age=28800");
    let mut response = StatusCode::NO_CONTENT.into_response();
    response.headers_mut().insert(
        header::SET_COOKIE,
        header::HeaderValue::from_str(&cookie)
            .map_err(|_| ApiError::Unavailable("browser session could not be created".into()))?,
    );
    Ok(response)
}

async fn browser_security(request: Request<Body>, next: Next) -> Response {
    if let Some(origin) = request.headers().get(header::ORIGIN) {
        let valid_origin = origin
            .to_str()
            .ok()
            .and_then(|value| url::Url::parse(value).ok())
            .zip(
                request
                    .headers()
                    .get(header::HOST)
                    .and_then(|value| value.to_str().ok()),
            )
            .is_some_and(|(origin, host)| {
                origin.scheme() == "http"
                    && origin.host_str().is_some_and(|hostname| {
                        hostname == "localhost"
                            || hostname
                                .parse::<std::net::IpAddr>()
                                .is_ok_and(|ip| ip.is_loopback())
                    })
                    && origin.port_or_known_default().is_some_and(|port| {
                        format!("{}:{port}", origin.host_str().unwrap()) == host
                    })
            });
        if !valid_origin {
            return ApiError::Forbidden.into_response();
        }
        if request.uri().path().starts_with("/v1/")
            && matches!(
                *request.method(),
                Method::POST | Method::PUT | Method::PATCH | Method::DELETE
            )
            && request.headers().get("x-s-code-csrf").is_none()
        {
            return ApiError::Forbidden.into_response();
        }
    }
    let mut response = next.run(request).await;
    response.headers_mut().insert(
        header::CONTENT_SECURITY_POLICY,
        header::HeaderValue::from_static(
            "default-src 'self'; connect-src 'self'; img-src 'self' data:; style-src 'self'; script-src 'self'; object-src 'none'; base-uri 'none'; frame-ancestors 'none'; form-action 'self'",
        ),
    );
    response.headers_mut().insert(
        header::X_CONTENT_TYPE_OPTIONS,
        header::HeaderValue::from_static("nosniff"),
    );
    response.headers_mut().insert(
        header::X_FRAME_OPTIONS,
        header::HeaderValue::from_static("DENY"),
    );
    response.headers_mut().insert(
        "permissions-policy",
        header::HeaderValue::from_static(
            "camera=(), microphone=(), geolocation=(), payment=(), usb=()",
        ),
    );
    response.headers_mut().insert(
        "cross-origin-opener-policy",
        header::HeaderValue::from_static("same-origin"),
    );
    response.headers_mut().insert(
        header::REFERRER_POLICY,
        header::HeaderValue::from_static("no-referrer"),
    );
    response.headers_mut().insert(
        header::CACHE_CONTROL,
        header::HeaderValue::from_static("no-store"),
    );
    response
}

