async fn development_inspector(
    State(state): State<AppState>,
    headers: HeaderMap,
) -> Result<Json<DevelopmentInspector>, ApiError> {
    authorize(&state, &headers)?;
    let instance_id = state
        .development_instance_id
        .as_deref()
        .ok_or(ApiError::NotFound)?
        .to_owned();
    let runtime_scopes = state.runtime_scopes.snapshot().await;
    let background_terminal_count = runtime_scopes.owned_resources;
    let client_presence_count = state
        .client_presence
        .lock()
        .map_err(|_| ApiError::Internal("client presence lock poisoned".into()))?
        .len();
    Ok(Json(DevelopmentInspector {
        schema_version: 1,
        instance_id,
        event_cursor: state.sequence.load(Ordering::SeqCst),
        runtime_scopes,
        model_provider_configured: state.model_provider.is_some(),
        mcp_tool_count: state.mcp_registry.definitions().len(),
        extension_count: state.extension_catalog.len(),
        background_terminal_count,
        client_presence_count,
        allowlisted_views: vec![
            "runtime_scope_counts",
            "event_cursor",
            "provider_availability",
            "extension_counts",
            "client_counts",
        ],
    }))
}

