async fn remove_mcp_http_server(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path(id): Path<String>,
    Json(input): Json<RemoveMcpHttpServer>,
) -> Result<Json<ExtensionDescriptor>, ApiError> {
    authorize(&state, &headers)?.ensure_scope_with(&input.scope, Permission::ManageExtensions)?;
    let server_id = id.strip_prefix("mcp:").unwrap_or(&id);
    let installation = state
        .store
        .get_mcp_http_installation(&input.scope, server_id)
        .await?;
    let mut preview = mcp_http_install_preview(&installation.server)?;
    if !input.confirmation.confirmed
        || input.confirmation.permissions_sha256 != installation.permissions_sha256
    {
        return Err(ApiError::Conflict(
            "MCP HTTP removal confirmation no longer matches the installation".into(),
        ));
    }
    state
        .store
        .remove_mcp_http_server(
            &input.scope,
            server_id,
            &input.confirmation.permissions_sha256,
        )
        .await?;
    state
        .store
        .remove_mcp_oauth_credential(&input.scope, server_id)
        .await?;
    preview.descriptor.status = ExtensionStatus::Disabled;
    publish_team_event(
        &state,
        &input.scope,
        "extension.mcp_http.removed",
        serde_json::json!({
            "extension_id": preview.descriptor.id,
            "permissions_sha256": preview.permissions_sha256,
            "requires_restart": true,
        }),
    )
    .await?;
    Ok(Json(preview.descriptor))
}

#[derive(Clone, Deserialize)]
struct OAuthProtectedResourceMetadata {
    #[serde(default)]
    authorization_servers: Vec<String>,
    #[serde(default)]
    scopes_supported: Vec<String>,
}

#[derive(Clone, Deserialize)]
struct OAuthAuthorizationServerMetadata {
    issuer: String,
    authorization_endpoint: String,
    token_endpoint: String,
    registration_endpoint: Option<String>,
    revocation_endpoint: Option<String>,
    #[serde(default)]
    scopes_supported: Vec<String>,
    #[serde(default)]
    code_challenge_methods_supported: Vec<String>,
}

#[derive(Deserialize)]
struct OAuthClientRegistration {
    client_id: String,
}

#[derive(Deserialize)]
struct OAuthTokenResponse {
    access_token: String,
    token_type: String,
    refresh_token: Option<String>,
    expires_in: Option<i64>,
    scope: Option<String>,
}

#[derive(Deserialize)]
struct OAuthCallbackQuery {
    state: String,
    code: Option<String>,
    error: Option<String>,
    error_description: Option<String>,
}

fn safe_oauth_url(value: &str, label: &str) -> Result<url::Url, ApiError> {
    let url = url::Url::parse(value)
        .map_err(|_| ApiError::BadRequest(format!("{label} is not a URL")))?;
    let loopback = url.host_str().is_some_and(|host| {
        host.eq_ignore_ascii_case("localhost")
            || host
                .parse::<std::net::IpAddr>()
                .is_ok_and(|address| address.is_loopback())
    });
    if url.username() != ""
        || url.password().is_some()
        || url.fragment().is_some()
        || url.host_str().is_none()
        || !(url.scheme() == "https" || (url.scheme() == "http" && loopback))
    {
        return Err(ApiError::BadRequest(format!(
            "{label} must use HTTPS (or loopback HTTP) without embedded credentials or fragments"
        )));
    }
    Ok(url)
}

fn oauth_http_client() -> Result<reqwest::Client, ApiError> {
    reqwest::Client::builder()
        .redirect(reqwest::redirect::Policy::none())
        .timeout(std::time::Duration::from_secs(15))
        .build()
        .map_err(|error| ApiError::Internal(error.to_string()))
}

async fn bounded_oauth_json<T: serde::de::DeserializeOwned>(
    response: reqwest::Response,
    label: &str,
) -> Result<T, ApiError> {
    const MAX_OAUTH_METADATA_BYTES: usize = 256 * 1024;
    if !response.status().is_success() {
        return Err(ApiError::Unavailable(format!(
            "{label} returned HTTP {}",
            response.status()
        )));
    }
    let mut stream = response.bytes_stream();
    let mut bytes = Vec::new();
    while let Some(chunk) = stream.next().await {
        let chunk = chunk.map_err(|_| ApiError::Unavailable(format!("{label} response failed")))?;
        if bytes.len().saturating_add(chunk.len()) > MAX_OAUTH_METADATA_BYTES {
            return Err(ApiError::BadRequest(format!("{label} exceeds 256 KiB")));
        }
        bytes.extend_from_slice(&chunk);
    }
    serde_json::from_slice(&bytes)
        .map_err(|error| ApiError::BadRequest(format!("Invalid {label}: {error}")))
}

fn bearer_parameter(header: &str, parameter: &str) -> Option<String> {
    if header.len() > 16 * 1024 || !header.to_ascii_lowercase().contains("bearer") {
        return None;
    }
    let needle = format!("{parameter}=\"");
    let start = header.find(&needle)? + needle.len();
    let remainder = &header[start..];
    let end = remainder.find('"')?;
    let value = &remainder[..end];
    (!value.is_empty()).then(|| value.to_owned())
}

fn protected_resource_well_known(endpoint: &url::Url) -> Result<url::Url, ApiError> {
    let mut url = endpoint.clone();
    let path = endpoint.path().trim_start_matches('/');
    url.set_path(
        if path.is_empty() {
            "/.well-known/oauth-protected-resource".into()
        } else {
            format!("/.well-known/oauth-protected-resource/{path}")
        }
        .as_str(),
    );
    url.set_query(None);
    Ok(url)
}

fn authorization_server_well_known(issuer: &url::Url) -> Result<url::Url, ApiError> {
    let mut url = issuer.clone();
    let path = issuer.path().trim_matches('/');
    url.set_path(
        if path.is_empty() {
            "/.well-known/oauth-authorization-server".into()
        } else {
            format!("/.well-known/oauth-authorization-server/{path}")
        }
        .as_str(),
    );
    url.set_query(None);
    Ok(url)
}

async fn discover_mcp_oauth(
    server: &McpHttpServerSpec,
) -> Result<(McpOAuthDiscovery, Option<String>), ApiError> {
    let oauth = server.oauth.as_ref().ok_or_else(|| {
        ApiError::BadRequest("This MCP HTTP server is not configured for OAuth".into())
    })?;
    let endpoint = safe_oauth_url(&server.endpoint, "MCP endpoint")?;
    let client = oauth_http_client()?;
    let challenge = client
        .get(endpoint.clone())
        .header("mcp-protocol-version", "2025-06-18")
        .send()
        .await
        .map_err(|_| ApiError::Unavailable("MCP OAuth challenge request failed".into()))?;
    let authenticate = challenge
        .headers()
        .get_all(reqwest::header::WWW_AUTHENTICATE)
        .iter()
        .filter_map(|header| header.to_str().ok())
        .collect::<Vec<_>>()
        .join(", ");
    let resource_metadata_url = bearer_parameter(&authenticate, "resource_metadata")
        .map(|value| safe_oauth_url(&value, "OAuth protected-resource metadata"))
        .transpose()?
        .unwrap_or(protected_resource_well_known(&endpoint)?);
    let challenge_scope = bearer_parameter(&authenticate, "scope");
    let resource_metadata: OAuthProtectedResourceMetadata = bounded_oauth_json(
        client
            .get(resource_metadata_url)
            .send()
            .await
            .map_err(|_| {
                ApiError::Unavailable("OAuth protected-resource discovery failed".into())
            })?,
        "OAuth protected-resource metadata",
    )
    .await?;
    let authorization_server = resource_metadata
        .authorization_servers
        .first()
        .ok_or_else(|| {
            ApiError::BadRequest(
                "OAuth protected-resource metadata has no authorization server".into(),
            )
        })
        .and_then(|value| safe_oauth_url(value, "OAuth authorization server"))?;
    let metadata_url = authorization_server_well_known(&authorization_server)?;
    let metadata: OAuthAuthorizationServerMetadata = bounded_oauth_json(
        client.get(metadata_url).send().await.map_err(|_| {
            ApiError::Unavailable("OAuth authorization-server discovery failed".into())
        })?,
        "OAuth authorization-server metadata",
    )
    .await?;
    let issuer = safe_oauth_url(&metadata.issuer, "OAuth issuer")?;
    if issuer.origin() != authorization_server.origin()
        || issuer.path().trim_end_matches('/') != authorization_server.path().trim_end_matches('/')
        || (!metadata.code_challenge_methods_supported.is_empty()
            && !metadata
                .code_challenge_methods_supported
                .iter()
                .any(|method| method == "S256"))
    {
        return Err(ApiError::BadRequest(
            "OAuth issuer mismatch or S256 PKCE is unsupported".into(),
        ));
    }
    let authorization_endpoint = safe_oauth_url(
        &metadata.authorization_endpoint,
        "OAuth authorization endpoint",
    )?;
    let token_endpoint = safe_oauth_url(&metadata.token_endpoint, "OAuth token endpoint")?;
    let registration_endpoint = metadata
        .registration_endpoint
        .as_deref()
        .map(|value| safe_oauth_url(value, "OAuth registration endpoint"))
        .transpose()?;
    let revocation_endpoint = metadata
        .revocation_endpoint
        .as_deref()
        .map(|value| safe_oauth_url(value, "OAuth revocation endpoint"))
        .transpose()?;
    let advertised_scopes = if !resource_metadata.scopes_supported.is_empty() {
        resource_metadata.scopes_supported
    } else if let Some(scopes) = challenge_scope {
        scopes.split_ascii_whitespace().map(str::to_owned).collect()
    } else {
        metadata.scopes_supported
    };
    let scopes = if oauth.scopes.is_empty() {
        advertised_scopes
    } else {
        if !advertised_scopes.is_empty()
            && oauth
                .scopes
                .iter()
                .any(|scope| !advertised_scopes.contains(scope))
        {
            return Err(ApiError::BadRequest(
                "Configured OAuth scopes are not advertised by the protected resource".into(),
            ));
        }
        oauth.scopes.clone()
    };
    if scopes.len() > 64
        || scopes.iter().any(|scope| {
            scope.is_empty() || scope.len() > 256 || scope.chars().any(char::is_whitespace)
        })
    {
        return Err(ApiError::BadRequest(
            "OAuth discovery returned invalid or excessive scopes".into(),
        ));
    }
    let permission_input = serde_json::to_vec(&(
        "s-code.mcp.oauth.discovery.v1",
        &server.id,
        endpoint.as_str(),
        authorization_server.as_str(),
        authorization_endpoint.as_str(),
        token_endpoint.as_str(),
        registration_endpoint.as_ref().map(url::Url::as_str),
        &scopes,
    ))
    .map_err(|error| ApiError::Internal(error.to_string()))?;
    let permissions_sha256 = format!("{:x}", Sha256::digest(permission_input));
    Ok((
        McpOAuthDiscovery {
            server_id: server.id.clone(),
            authorization_server: authorization_server.to_string(),
            authorization_endpoint: authorization_endpoint.to_string(),
            token_endpoint: token_endpoint.to_string(),
            registration_endpoint: registration_endpoint.map(|url| url.to_string()),
            scopes,
            permissions_sha256,
        },
        revocation_endpoint.map(|url| url.to_string()),
    ))
}

fn oauth_redirect_uri(headers: &HeaderMap) -> Result<String, ApiError> {
    let host = headers
        .get(header::HOST)
        .and_then(|value| value.to_str().ok())
        .ok_or_else(|| ApiError::BadRequest("OAuth request is missing its local Host".into()))?;
    let url = safe_oauth_url(
        &format!("http://{host}/v1/mcp/oauth/callback"),
        "OAuth redirect URI",
    )?;
    if !url.host_str().is_some_and(|host| {
        host.eq_ignore_ascii_case("localhost")
            || host
                .parse::<std::net::IpAddr>()
                .is_ok_and(|address| address.is_loopback())
    }) {
        return Err(ApiError::BadRequest(
            "MCP OAuth callback must remain on the loopback Local Web origin".into(),
        ));
    }
    Ok(url.to_string())
}

async fn preview_mcp_oauth(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path(id): Path<String>,
    Json(input): Json<PreviewMcpOAuth>,
) -> Result<Json<McpOAuthDiscovery>, ApiError> {
    authorize(&state, &headers)?.ensure_scope_with(&input.scope, Permission::ManageExtensions)?;
    let server_id = id.strip_prefix("mcp:").unwrap_or(&id);
    let installation = state
        .store
        .get_mcp_http_installation(&input.scope, server_id)
        .await?;
    Ok(Json(discover_mcp_oauth(&installation.server).await?.0))
}

async fn start_mcp_oauth(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path(id): Path<String>,
    Json(input): Json<StartMcpOAuth>,
) -> Result<Json<McpOAuthLaunch>, ApiError> {
    authorize(&state, &headers)?.ensure_scope_with(&input.scope, Permission::ManageExtensions)?;
    let server_id = id.strip_prefix("mcp:").unwrap_or(&id);
    let installation = state
        .store
        .get_mcp_http_installation(&input.scope, server_id)
        .await?;
    let oauth = installation.server.oauth.as_ref().ok_or_else(|| {
        ApiError::BadRequest("This MCP HTTP server is not configured for OAuth".into())
    })?;
    let (discovery, revocation_endpoint) = discover_mcp_oauth(&installation.server).await?;
    if !input.confirmation.confirmed
        || input.confirmation.permissions_sha256 != discovery.permissions_sha256
    {
        return Err(ApiError::Conflict(
            "OAuth endpoints or scopes changed, or were not explicitly confirmed".into(),
        ));
    }
    let redirect_uri = oauth_redirect_uri(&headers)?;
    let client = oauth_http_client()?;
    let client_id = if let Some(client_id) = &oauth.client_id {
        client_id.clone()
    } else {
        let registration_endpoint = discovery.registration_endpoint.as_ref().ok_or_else(|| {
            ApiError::BadRequest(
                "OAuth requires a configured client id or dynamic client registration".into(),
            )
        })?;
        let registration: OAuthClientRegistration = bounded_oauth_json(
            client
                .post(registration_endpoint)
                .json(&serde_json::json!({
                    "client_name": "S-Code",
                    "redirect_uris": [redirect_uri],
                    "grant_types": ["authorization_code", "refresh_token"],
                    "response_types": ["code"],
                    "token_endpoint_auth_method": "none"
                }))
                .send()
                .await
                .map_err(|_| ApiError::Unavailable("OAuth client registration failed".into()))?,
            "OAuth client registration",
        )
        .await?;
        if registration.client_id.is_empty() || registration.client_id.len() > 512 {
            return Err(ApiError::BadRequest(
                "OAuth registration returned an invalid client id".into(),
            ));
        }
        registration.client_id
    };
    let state_token = format!("{}{}", ulid::Ulid::new(), ulid::Ulid::new());
    let code_verifier = format!(
        "{}{}{}",
        ulid::Ulid::new(),
        ulid::Ulid::new(),
        ulid::Ulid::new()
    );
    let code_challenge = URL_SAFE_NO_PAD.encode(Sha256::digest(code_verifier.as_bytes()));
    let expires_at = Utc::now() + chrono::Duration::minutes(10);
    state
        .store
        .create_pending_mcp_oauth(&PendingMcpOAuth {
            scope: input.scope.clone(),
            state: state_token.clone(),
            server_id: server_id.to_owned(),
            code_verifier,
            redirect_uri: redirect_uri.clone(),
            token_endpoint: discovery.token_endpoint.clone(),
            revocation_endpoint,
            client_id: client_id.clone(),
            scopes: discovery.scopes.clone(),
            expires_at,
            created_at: Utc::now(),
        })
        .await?;
    let mut authorization_url = safe_oauth_url(
        &discovery.authorization_endpoint,
        "OAuth authorization endpoint",
    )?;
    authorization_url
        .query_pairs_mut()
        .append_pair("response_type", "code")
        .append_pair("client_id", &client_id)
        .append_pair("redirect_uri", &redirect_uri)
        .append_pair("state", &state_token)
        .append_pair("code_challenge", &code_challenge)
        .append_pair("code_challenge_method", "S256")
        .append_pair("resource", &installation.server.endpoint);
    if !discovery.scopes.is_empty() {
        authorization_url
            .query_pairs_mut()
            .append_pair("scope", &discovery.scopes.join(" "));
    }
    publish_team_event(
        &state,
        &input.scope,
        "extension.mcp_oauth.started",
        serde_json::json!({
            "server_id": server_id,
            "authorization_server": discovery.authorization_server,
            "scopes": discovery.scopes,
            "expires_at": expires_at,
        }),
    )
    .await?;
    Ok(Json(McpOAuthLaunch {
        server_id: server_id.to_owned(),
        authorization_url: authorization_url.to_string(),
        expires_at,
    }))
}

async fn mcp_oauth_status(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path(id): Path<String>,
    Query(query): Query<CatalogQuery>,
) -> Result<Json<McpOAuthStatus>, ApiError> {
    let scope = query.scope();
    authorize(&state, &headers)?.ensure_scope_with(&scope, Permission::ReadExtensions)?;
    let server_id = id.strip_prefix("mcp:").unwrap_or(&id);
    let installation = state
        .store
        .get_mcp_http_installation(&scope, server_id)
        .await?;
    let credential = state
        .store
        .get_mcp_oauth_credential(&scope, server_id)
        .await
        .ok();
    Ok(Json(McpOAuthStatus {
        server_id: server_id.to_owned(),
        supported: installation.server.oauth.is_some(),
        authenticated: credential.as_ref().is_some_and(|credential| {
            credential
                .expires_at
                .is_none_or(|expires_at| expires_at > Utc::now())
                || credential.refresh_token.is_some()
        }),
        scopes: credential
            .as_ref()
            .map(|credential| credential.scopes.clone())
            .unwrap_or_default(),
        expires_at: credential.and_then(|credential| credential.expires_at),
    }))
}

async fn complete_mcp_oauth(
    State(state): State<AppState>,
    Query(query): Query<OAuthCallbackQuery>,
) -> Response {
    let result = async {
        let pending = state.store.take_pending_mcp_oauth(&query.state).await?;
        if let Some(error) = query.error {
            let detail = query.error_description.unwrap_or_default();
            return Err(ApiError::BadRequest(format!(
                "OAuth authorization was rejected: {error} {detail}"
            )));
        }
        let code = query
            .code
            .filter(|code| !code.is_empty() && code.len() <= 8 * 1024)
            .ok_or_else(|| ApiError::BadRequest("OAuth callback has no code".into()))?;
        let token: OAuthTokenResponse = bounded_oauth_json(
            oauth_http_client()?
                .post(&pending.token_endpoint)
                .form(&[
                    ("grant_type", "authorization_code"),
                    ("code", code.as_str()),
                    ("redirect_uri", pending.redirect_uri.as_str()),
                    ("client_id", pending.client_id.as_str()),
                    ("code_verifier", pending.code_verifier.as_str()),
                ])
                .send()
                .await
                .map_err(|_| ApiError::Unavailable("OAuth token exchange failed".into()))?,
            "OAuth token response",
        )
        .await?;
        let credential = validated_oauth_credential(&pending, token, None)?;
        state
            .store
            .put_mcp_oauth_credential(&pending.scope, credential)
            .await?;
        publish_team_event(
            &state,
            &pending.scope,
            "extension.mcp_oauth.completed",
            serde_json::json!({
                "server_id": pending.server_id,
                "scopes": pending.scopes,
            }),
        )
        .await?;
        Ok::<_, ApiError>(())
    }
    .await;
    match result {
        Ok(()) => (
            StatusCode::OK,
            [(header::CONTENT_TYPE, "text/html; charset=utf-8")],
            Html("<!doctype html><meta charset=utf-8><title>OAuth complete</title><p>Authentication complete. You may close this window.</p>"),
        )
            .into_response(),
        Err(_error) => (
            StatusCode::BAD_REQUEST,
            [(header::CONTENT_TYPE, "text/html; charset=utf-8")],
            Html("<!doctype html><meta charset=utf-8><title>OAuth failed</title><p>Authentication failed. Close this window and retry from S-Code.</p>"),
        )
            .into_response(),
    }
}

fn validated_oauth_credential(
    pending: &PendingMcpOAuth,
    token: OAuthTokenResponse,
    previous: Option<&McpOAuthCredential>,
) -> Result<McpOAuthCredential, ApiError> {
    if token.access_token.is_empty()
        || token.access_token.len() > 16 * 1024
        || !token.token_type.eq_ignore_ascii_case("bearer")
        || token
            .expires_in
            .is_some_and(|seconds| !(1..=31_536_000).contains(&seconds))
    {
        return Err(ApiError::BadRequest(
            "OAuth token response is invalid or unsupported".into(),
        ));
    }
    let scopes = token
        .scope
        .as_deref()
        .map(|scope| scope.split_ascii_whitespace().map(str::to_owned).collect())
        .unwrap_or_else(|| pending.scopes.clone());
    if !pending.scopes.is_empty() && scopes.iter().any(|scope| !pending.scopes.contains(scope)) {
        return Err(ApiError::BadRequest(
            "OAuth token response granted an unrequested scope".into(),
        ));
    }
    let now = Utc::now();
    Ok(McpOAuthCredential {
        scope: pending.scope.clone(),
        server_id: pending.server_id.clone(),
        access_token: token.access_token,
        refresh_token: token
            .refresh_token
            .or_else(|| previous.and_then(|credential| credential.refresh_token.clone())),
        token_type: "Bearer".into(),
        scopes,
        expires_at: token
            .expires_in
            .map(|seconds| now + chrono::Duration::seconds(seconds)),
        token_endpoint: pending.token_endpoint.clone(),
        revocation_endpoint: pending.revocation_endpoint.clone(),
        client_id: pending.client_id.clone(),
        created_at: previous.map_or(now, |credential| credential.created_at),
        updated_at: now,
    })
}

async fn logout_mcp_oauth(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path(id): Path<String>,
    Json(input): Json<LogoutMcpOAuth>,
) -> Result<Json<McpOAuthStatus>, ApiError> {
    authorize(&state, &headers)?.ensure_scope_with(&input.scope, Permission::ManageExtensions)?;
    let server_id = id.strip_prefix("mcp:").unwrap_or(&id);
    let installation = state
        .store
        .get_mcp_http_installation(&input.scope, server_id)
        .await?;
    let credential = state
        .store
        .remove_mcp_oauth_credential(&input.scope, server_id)
        .await?;
    if let Some(credential) = credential
        && let Some(endpoint) = credential.revocation_endpoint
    {
        let _ = oauth_http_client()?
            .post(endpoint)
            .form(&[
                ("token", credential.access_token),
                ("client_id", credential.client_id),
            ])
            .send()
            .await;
    }
    publish_team_event(
        &state,
        &input.scope,
        "extension.mcp_oauth.logged_out",
        serde_json::json!({"server_id": server_id}),
    )
    .await?;
    Ok(Json(McpOAuthStatus {
        server_id: server_id.to_owned(),
        supported: installation.server.oauth.is_some(),
        authenticated: false,
        scopes: Vec::new(),
        expires_at: None,
    }))
}

#[derive(Clone)]
pub struct StoreMcpOAuthAuthorizationProvider {
    store: Store,
    scope: Scope,
}

impl StoreMcpOAuthAuthorizationProvider {
    pub fn new(store: Store, scope: Scope) -> Self {
        Self { store, scope }
    }
}

#[async_trait::async_trait]
impl McpHttpAuthorizationProvider for StoreMcpOAuthAuthorizationProvider {
    async fn bearer_token(&self, server_id: &str) -> Result<Option<String>, McpError> {
        refresh_mcp_oauth_credential(&self.store, &self.scope, server_id)
            .await
            .map(|credential| credential.map(|credential| credential.access_token))
            .map_err(|error| match error {
                ApiError::NotFound | ApiError::Unauthorized => McpError::AuthenticationRequired,
                _ => McpError::Protocol("MCP OAuth credential refresh failed".into()),
            })
    }
}

async fn refresh_mcp_oauth_credential(
    store: &Store,
    scope: &Scope,
    server_id: &str,
) -> Result<Option<McpOAuthCredential>, ApiError> {
    let credential = match store.get_mcp_oauth_credential(scope, server_id).await {
        Ok(credential) => credential,
        Err(StorageError::NotFound) => return Ok(None),
        Err(error) => return Err(error.into()),
    };
    if credential
        .expires_at
        .is_none_or(|expires_at| expires_at > Utc::now() + chrono::Duration::seconds(60))
    {
        return Ok(Some(credential));
    }
    let refresh_token = credential
        .refresh_token
        .clone()
        .ok_or(ApiError::Unauthorized)?;
    let token: OAuthTokenResponse = bounded_oauth_json(
        oauth_http_client()?
            .post(&credential.token_endpoint)
            .form(&[
                ("grant_type", "refresh_token"),
                ("refresh_token", refresh_token.as_str()),
                ("client_id", credential.client_id.as_str()),
            ])
            .send()
            .await
            .map_err(|_| ApiError::Unavailable("OAuth token refresh failed".into()))?,
        "OAuth token response",
    )
    .await?;
    let pending = PendingMcpOAuth {
        scope: scope.clone(),
        state: String::new(),
        server_id: server_id.to_owned(),
        code_verifier: String::new(),
        redirect_uri: String::new(),
        token_endpoint: credential.token_endpoint.clone(),
        revocation_endpoint: credential.revocation_endpoint.clone(),
        client_id: credential.client_id.clone(),
        scopes: credential.scopes.clone(),
        expires_at: Utc::now(),
        created_at: Utc::now(),
    };
    let refreshed = validated_oauth_credential(&pending, token, Some(&credential))?;
    Ok(Some(
        store.put_mcp_oauth_credential(scope, refreshed).await?,
    ))
}

