fn ensure_mcp_resource_server(
    state: &AppState,
    auth: &AuthContext,
    server_id: &str,
) -> Result<(), ApiError> {
    if matches!(auth, AuthContext::TeamGrant(_)) {
        return Err(ApiError::Forbidden);
    }
    if state.mcp_registry.contains_server(server_id) {
        Ok(())
    } else {
        Err(ApiError::NotFound)
    }
}

async fn list_mcp_resources(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path(server_id): Path<String>,
    Query(query): Query<McpResourceQuery>,
) -> Result<Json<McpResourcePage>, ApiError> {
    let scope = query.scope();
    let auth = authorize(&state, &headers)?;
    auth.ensure_scope(&scope)?;
    ensure_mcp_resource_server(&state, &auth, &server_id)?;
    let page = state
        .mcp_registry
        .list_resources(&server_id, query.cursor.as_deref())
        .await
        .map_err(|error| {
            tracing::warn!(%error, %server_id, "MCP resource listing failed");
            ApiError::Unavailable("MCP resource listing failed".into())
        })?;
    Ok(Json(McpResourcePage {
        resources: page
            .entries
            .into_iter()
            .map(|resource| ProtocolMcpResource {
                server_id: server_id.clone(),
                uri: resource.uri,
                name: resource.name,
                description: resource.description,
                mime_type: resource.mime_type,
            })
            .collect(),
        next_cursor: page.next_cursor,
    }))
}

