#[derive(Deserialize)]
struct BackgroundTerminalOutputQuery {
    organization_id: String,
    team_id: String,
    actor_id: String,
    #[serde(default)]
    offset: u64,
    #[serde(default = "default_terminal_output_limit")]
    limit: usize,
}

const fn default_terminal_output_limit() -> usize {
    64 * 1024
}

async fn get_background_terminal_output(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path(id): Path<String>,
    Query(query): Query<BackgroundTerminalOutputQuery>,
) -> Result<Json<BackgroundTerminalOutput>, ApiError> {
    let scope = Scope {
        organization_id: Id(query.organization_id),
        team_id: Id(query.team_id),
        actor_id: Id(query.actor_id),
        goal_id: None,
        task_id: None,
    };
    authorize(&state, &headers)?.ensure_scope(&scope)?;
    if query.limit == 0 || query.limit > 64 * 1024 {
        return Err(ApiError::BadRequest(
            "terminal output limit must be between 1 and 65536 bytes".into(),
        ));
    }
    let id = Id(id);
    let terminal = state.store.get_background_terminal(&scope, &id).await?;
    let output = state
        .store
        .get_background_terminal_output(&scope, &id)
        .await?;
    let offset = usize::try_from(query.offset)
        .map_err(|_| ApiError::BadRequest("terminal output offset is too large".into()))?;
    if offset > output.len() {
        return Err(ApiError::BadRequest(
            "terminal output offset exceeds retained output".into(),
        ));
    }
    let end = offset.saturating_add(query.limit).min(output.len());
    let terminal_state = matches!(
        terminal.status,
        BackgroundTerminalStatus::Exited
            | BackgroundTerminalStatus::Failed
            | BackgroundTerminalStatus::Stopped
            | BackgroundTerminalStatus::Orphaned
    );
    Ok(Json(BackgroundTerminalOutput {
        terminal_id: id,
        offset: query.offset,
        next_offset: end as u64,
        content_base64: STANDARD.encode(&output[offset..end]),
        eof: terminal_state && end == output.len(),
        output_truncated: terminal.output_truncated,
    }))
}

async fn write_background_terminal(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path(id): Path<String>,
    Json(input): Json<WriteBackgroundTerminal>,
) -> Result<Json<BackgroundTerminalSummary>, ApiError> {
    authorize(&state, &headers)?.ensure_scope(&input.scope)?;
    let id = Id(id);
    let terminal = state
        .store
        .get_background_terminal(&input.scope, &id)
        .await?;
    if terminal.status != BackgroundTerminalStatus::Running {
        return Err(ApiError::Conflict(
            "background terminal is not running".into(),
        ));
    }
    let content = STANDARD
        .decode(&input.content_base64)
        .map_err(|_| ApiError::BadRequest("terminal input is not valid base64".into()))?;
    if content.is_empty() || content.len() > 64 * 1024 {
        return Err(ApiError::BadRequest(
            "terminal input must contain between 1 and 65536 bytes".into(),
        ));
    }
    let handle = state
        .runtime_scopes
        .background_terminal(&id)
        .await
        .ok_or_else(|| ApiError::Conflict("background terminal runtime is unavailable".into()))?;
    handle
        .commands
        .send(BackgroundTerminalCommand::Write(content))
        .map_err(|_| ApiError::Conflict("background terminal runtime has exited".into()))?;
    Ok(Json(terminal))
}

async fn resize_background_terminal(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path(id): Path<String>,
    Json(input): Json<ResizeBackgroundTerminal>,
) -> Result<Json<BackgroundTerminalSummary>, ApiError> {
    authorize(&state, &headers)?.ensure_scope(&input.scope)?;
    if !(2..=500).contains(&input.rows) || !(2..=500).contains(&input.cols) {
        return Err(ApiError::BadRequest(
            "terminal rows and columns must be between 2 and 500".into(),
        ));
    }
    let id = Id(id);
    let handle = state
        .runtime_scopes
        .background_terminal(&id)
        .await
        .ok_or_else(|| ApiError::Conflict("background terminal runtime is unavailable".into()))?;
    handle
        .commands
        .send(BackgroundTerminalCommand::Resize(PtySize {
            rows: input.rows,
            cols: input.cols,
            pixel_width: 0,
            pixel_height: 0,
        }))
        .map_err(|_| ApiError::Conflict("background terminal runtime has exited".into()))?;
    Ok(Json(
        state
            .store
            .resize_background_terminal(&input.scope, &id, input.rows, input.cols)
            .await?,
    ))
}

async fn stop_background_terminal(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path(id): Path<String>,
    Json(input): Json<StopBackgroundTerminal>,
) -> Result<Json<BackgroundTerminalSummary>, ApiError> {
    authorize(&state, &headers)?.ensure_scope(&input.scope)?;
    let id = Id(id);
    let terminal = state
        .store
        .get_background_terminal(&input.scope, &id)
        .await?;
    if terminal.revision != input.expected_revision {
        return Err(ApiError::Conflict(
            "background terminal changed concurrently".into(),
        ));
    }
    if terminal.status != BackgroundTerminalStatus::Running {
        return Ok(Json(terminal));
    }
    let handle = state
        .runtime_scopes
        .background_terminal(&id)
        .await
        .ok_or_else(|| ApiError::Conflict("background terminal runtime is unavailable".into()))?;
    handle
        .commands
        .send(BackgroundTerminalCommand::Stop)
        .map_err(|_| ApiError::Conflict("background terminal runtime has exited".into()))?;
    Ok(Json(terminal))
}

