async fn search_workspace_paths(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path(id): Path<String>,
    Query(query): Query<FileSearchQuery>,
) -> Result<Json<Vec<WorkspacePathMatch>>, ApiError> {
    let scope = Scope {
        organization_id: Id(query.organization_id),
        team_id: Id(query.team_id),
        actor_id: Id(query.actor_id),
        goal_id: None,
        task_id: None,
    };
    authorize(&state, &headers)?.ensure_scope(&scope)?;
    let session = state.store.get_session(&Id(id)).await?;
    if session.scope.organization_id != scope.organization_id
        || session.scope.team_id != scope.team_id
        || session.scope.actor_id != scope.actor_id
    {
        return Err(ApiError::Forbidden);
    }
    let workspace_uri = session.workspace_uri;
    let search = query.query;
    let limit = query.limit;
    let paths =
        tokio::task::spawn_blocking(move || fuzzy_workspace_paths(&workspace_uri, &search, limit))
            .await
            .map_err(|error| ApiError::Internal(error.to_string()))?
            .map_err(|error| ApiError::BadRequest(error.to_string()))?;
    Ok(Json(paths))
}

async fn get_transcript_snapshot(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path(id): Path<String>,
    Query(query): Query<SnapshotQuery>,
) -> Result<Json<TranscriptSnapshot>, ApiError> {
    let scope = query.scope();
    authorize(&state, &headers)?.ensure_scope(&scope)?;
    if query.limit == 0 || query.limit > 1_000 {
        return Err(ApiError::BadRequest(
            "snapshot limit must be between 1 and 1000".into(),
        ));
    }
    let before = query
        .before
        .as_deref()
        .map(decode_transcript_cursor)
        .transpose()?;
    Ok(Json(
        build_transcript_snapshot_page(&state, &scope, &Id(id), before.as_ref(), query.limit)
            .await?,
    ))
}

#[derive(Deserialize)]
struct SnapshotQuery {
    organization_id: String,
    team_id: String,
    actor_id: String,
    #[serde(default)]
    before: Option<String>,
    #[serde(default = "default_snapshot_limit")]
    limit: usize,
}

impl SnapshotQuery {
    fn scope(&self) -> Scope {
        Scope {
            organization_id: Id(self.organization_id.clone()),
            team_id: Id(self.team_id.clone()),
            actor_id: Id(self.actor_id.clone()),
            goal_id: None,
            task_id: None,
        }
    }
}

fn default_snapshot_limit() -> usize {
    500
}

#[derive(Serialize, Deserialize)]
struct TranscriptCursor {
    created_at: DateTime<Utc>,
    id: Id,
}

fn encode_transcript_position(created_at: DateTime<Utc>, id: &Id) -> Result<String, ApiError> {
    let bytes = serde_json::to_vec(&TranscriptCursor {
        created_at,
        id: id.clone(),
    })
    .map_err(|error| ApiError::Internal(error.to_string()))?;
    Ok(URL_SAFE_NO_PAD.encode(bytes))
}

fn decode_transcript_cursor(value: &str) -> Result<TranscriptCursor, ApiError> {
    if value.is_empty() || value.len() > 1_024 {
        return Err(ApiError::BadRequest("transcript cursor is invalid".into()));
    }
    let bytes = URL_SAFE_NO_PAD
        .decode(value)
        .map_err(|_| ApiError::BadRequest("transcript cursor is invalid".into()))?;
    serde_json::from_slice(&bytes)
        .map_err(|_| ApiError::BadRequest("transcript cursor is invalid".into()))
}

async fn build_transcript_snapshot_page(
    state: &AppState,
    scope: &Scope,
    session_id: &Id,
    before: Option<&TranscriptCursor>,
    limit: usize,
) -> Result<TranscriptSnapshot, ApiError> {
    let session = state.store.get_session(session_id).await?;
    if session.scope.organization_id != scope.organization_id
        || session.scope.team_id != scope.team_id
        || session.scope.actor_id != scope.actor_id
    {
        return Err(ApiError::Forbidden);
    }

    // Capture the cursor before reading projections. A concurrent mutation can
    // therefore be present in both the snapshot and replay, but can never fall
    // into a gap between them. Clients upsert by Item ID and revision.
    let cursor = state.store.latest_team_event_sequence(scope).await?;
    let stored_turns = state.store.list_turns(scope, session_id).await?;
    let usage = state.store.session_usage(scope, session_id).await?;
    let turns = stored_turns
        .into_iter()
        .map(public_turn)
        .collect::<Vec<_>>();
    let reference_page = state
        .store
        .list_transcript_item_references(
            scope,
            session_id,
            before.map(|cursor| (&cursor.created_at, &cursor.id)),
            limit,
        )
        .await?;
    let sources = state
        .store
        .load_transcript_page_sources(scope, session_id, &reference_page.references)
        .await?;
    let direct_tool_item_ids = reference_page
        .references
        .iter()
        .filter(|reference| reference.source_kind == TranscriptItemSourceKind::ToolCall)
        .map(|reference| reference.source_id.0.clone())
        .collect::<HashSet<_>>();
    let message_turn_ids = reference_page
        .references
        .iter()
        .filter(|reference| reference.source_kind == TranscriptItemSourceKind::Message)
        .map(|reference| reference.turn_id.clone())
        .collect::<HashSet<_>>()
        .into_iter()
        .collect::<Vec<_>>();
    let pending_approval_calls = state
        .store
        .list_pending_session_approval_calls(scope, session_id)
        .await?;
    let pending_requests = pending_approval_calls
        .iter()
        .map(|(approval, call)| transcript_approval_request(approval, call))
        .collect();
    let pending_questions = state
        .store
        .list_pending_session_question_requests(scope, session_id)
        .await?;
    let pending_inputs = state
        .store
        .list_pending_turn_inputs(scope, session_id)
        .await?;
    let attachments = state
        .store
        .list_attachment_metadata_for_turns(scope, session_id, &message_turn_ids)
        .await?;
    let artifact_metadata = sources
        .artifacts
        .iter()
        .map(|artifact| artifact.metadata.clone())
        .collect();
    let items = project_transcript_items(
        sources.messages,
        &sources.tool_calls,
        Some(&direct_tool_item_ids),
        sources.approvals,
        sources.questions,
        &sources.artifacts,
        sources.events,
        &attachments,
    )?;
    let expected_ids = reference_page
        .references
        .iter()
        .map(|reference| reference.item_id.0.as_str())
        .collect::<BTreeSet<_>>();
    let actual_ids = items
        .iter()
        .map(|item| item.id.0.as_str())
        .collect::<BTreeSet<_>>();
    if expected_ids != actual_ids || items.len() != reference_page.references.len() {
        return Err(ApiError::Internal(
            "transcript projection index is inconsistent".into(),
        ));
    }
    let next_cursor = if reference_page.has_older {
        reference_page
            .references
            .first()
            .map(|reference| encode_transcript_position(reference.created_at, &reference.item_id))
            .transpose()?
    } else {
        None
    };

    Ok(TranscriptSnapshot {
        protocol_version: PROTOCOL_VERSION.into(),
        snapshot_revision: cursor,
        session,
        turns,
        items,
        item_count: reference_page.total_count,
        next_cursor,
        pending_requests,
        pending_questions,
        pending_inputs,
        attachments,
        artifacts: artifact_metadata,
        usage,
        cursor,
    })
}

async fn build_transcript_snapshot(
    state: &AppState,
    scope: &Scope,
    session_id: &Id,
) -> Result<TranscriptSnapshot, ApiError> {
    let session_id = session_id.clone();
    let session = state.store.get_session(&session_id).await?;
    if session.scope.organization_id != scope.organization_id
        || session.scope.team_id != scope.team_id
        || session.scope.actor_id != scope.actor_id
    {
        return Err(ApiError::Forbidden);
    }

    // Capture the cursor before reading projections. A concurrent mutation can
    // therefore be present in both the snapshot and replay, but can never fall
    // into a gap between them. Clients upsert by item ID and revision.
    let cursor = state.store.latest_team_event_sequence(scope).await?;
    let stored_turns = state.store.list_turns(scope, &session_id).await?;
    let usage = state.store.session_usage(scope, &session_id).await?;
    let turns = stored_turns
        .into_iter()
        .map(public_turn)
        .collect::<Vec<_>>();
    let messages = state.store.list_messages(scope, &session_id).await?;
    let tool_calls = state.store.list_tool_calls(scope, &session_id).await?;
    let approvals = state
        .store
        .list_session_approvals(scope, &session_id)
        .await?;
    let question_requests = state
        .store
        .list_session_question_requests(scope, &session_id)
        .await?;
    let pending_inputs = state
        .store
        .list_pending_turn_inputs(scope, &session_id)
        .await?;
    let attachments = state
        .store
        .list_session_attachments(scope, &session_id, false)
        .await?;
    let artifacts = state
        .store
        .list_session_artifacts(scope, &session_id)
        .await?;
    let session_events = state
        .store
        .list_session_events(scope, &session_id, 10_000)
        .await?;

    let calls_by_id = tool_calls
        .iter()
        .map(|call| (call.request.id.0.as_str(), call))
        .collect::<HashMap<_, _>>();
    let pending_requests = approvals
        .iter()
        .filter(|approval| approval.status == ApprovalStatus::Pending)
        .map(|approval| {
            calls_by_id
                .get(approval.tool_call_id.0.as_str())
                .map(|call| transcript_approval_request(approval, call))
                .ok_or_else(|| {
                    ApiError::Internal("approval references an unavailable tool call".into())
                })
        })
        .collect::<Result<Vec<_>, _>>()?;
    let pending_questions = question_requests
        .iter()
        .filter(|request| request.status == QuestionStatus::Pending)
        .cloned()
        .collect::<Vec<_>>();
    let items = project_transcript_items(
        messages,
        &tool_calls,
        None,
        approvals,
        question_requests,
        &artifacts,
        session_events,
        &attachments,
    )?;
    let item_count = u64::try_from(items.len()).unwrap_or(u64::MAX);

    Ok(TranscriptSnapshot {
        protocol_version: PROTOCOL_VERSION.into(),
        snapshot_revision: cursor,
        session,
        turns,
        items,
        item_count,
        next_cursor: None,
        pending_requests,
        pending_questions,
        pending_inputs,
        attachments,
        artifacts: artifacts
            .into_iter()
            .map(|artifact| artifact.metadata)
            .collect(),
        usage,
        cursor,
    })
}

#[allow(clippy::too_many_arguments)]
fn project_transcript_items(
    messages: Vec<Message>,
    tool_calls: &[ToolCall],
    direct_tool_item_ids: Option<&HashSet<String>>,
    approvals: Vec<Approval>,
    question_requests: Vec<QuestionRequest>,
    artifacts: &[Artifact],
    session_events: Vec<Event>,
    attachments: &[AttachmentMetadata],
) -> Result<Vec<TranscriptItem>, ApiError> {
    let rewound_plan_item_ids = durable_rewound_plan_item_ids(&messages)?;
    let calls_by_id = tool_calls
        .iter()
        .map(|call| (call.request.id.0.as_str(), call))
        .collect::<HashMap<_, _>>();
    let attachments_by_turn = attachments.iter().fold(
        HashMap::<String, Vec<AttachmentMetadata>>::new(),
        |mut grouped, attachment| {
            if let Some(turn_id) = &attachment.turn_id {
                grouped
                    .entry(turn_id.0.clone())
                    .or_default()
                    .push(attachment.clone());
            }
            grouped
        },
    );
    let mut items = messages
        .into_iter()
        .filter(|message| {
            matches!(
                message.role.as_str(),
                "user" | "assistant" | "tool" | "reasoning_summary_streaming" | "reasoning_summary"
            )
        })
        .map(|message| {
            let message_attachments = attachments_by_turn
                .get(&message.turn_id.0)
                .cloned()
                .unwrap_or_default();
            transcript_message(message, message_attachments)
        })
        .collect::<Vec<_>>();
    items.extend(
        tool_calls
            .iter()
            .filter(|call| direct_tool_item_ids.is_none_or(|ids| ids.contains(&call.request.id.0)))
            .map(transcript_tool_call),
    );
    apply_mcp_progress(&mut items, &session_events)?;
    for approval in approvals {
        let Some(call) = calls_by_id.get(approval.tool_call_id.0.as_str()) else {
            return Err(ApiError::Internal(
                "approval references an unavailable tool call".into(),
            ));
        };
        let request = transcript_approval_request(&approval, call);
        items.push(transcript_approval_item(&approval, request));
    }
    items.extend(question_requests.into_iter().map(transcript_question_item));
    items.extend(artifacts.iter().map(transcript_artifact_item));
    let mut plan_items = transcript_plan_items(session_events.clone())?;
    for item in &mut plan_items {
        if rewound_plan_item_ids.contains(&item.id.0) {
            item.status = TranscriptItemStatus::Cancelled;
            item.summary = format!("Undone · {}", item.summary);
            item.revision = item.revision.saturating_add(1);
        }
    }
    items.extend(plan_items);
    items.extend(transcript_metadata_items(&session_events)?);
    items.sort_by(|left, right| {
        left.created_at
            .cmp(&right.created_at)
            .then_with(|| left.id.0.cmp(&right.id.0))
    });
    Ok(items)
}

fn apply_mcp_progress(
    items: &mut [TranscriptItem],
    session_events: &[Event],
) -> Result<(), ApiError> {
    let mut latest = HashMap::<String, (u64, McpProgress)>::new();
    for event in session_events
        .iter()
        .filter(|event| event.kind == "mcp.progress")
    {
        let Some(tool_call_id) = event
            .payload
            .get("tool_call_id")
            .and_then(serde_json::Value::as_str)
        else {
            continue;
        };
        let progress = event
            .payload
            .get("progress")
            .and_then(serde_json::Value::as_f64)
            .filter(|value| value.is_finite() && *value >= 0.0)
            .ok_or_else(|| ApiError::Internal("stored MCP progress is invalid".into()))?;
        let total = event
            .payload
            .get("total")
            .and_then(serde_json::Value::as_f64);
        if total.is_some_and(|total| !total.is_finite() || total < progress) {
            return Err(ApiError::Internal(
                "stored MCP progress total is invalid".into(),
            ));
        }
        let message = event
            .payload
            .get("message")
            .and_then(serde_json::Value::as_str)
            .map(str::to_owned);
        let next = McpProgress {
            progress,
            total,
            message,
            updated_at: event.timestamp,
        };
        let slot = latest
            .entry(tool_call_id.to_owned())
            .or_insert_with(|| (event.sequence, next.clone()));
        if event.sequence >= slot.0 {
            *slot = (event.sequence, next);
        }
    }
    for item in items {
        if let TranscriptItemContent::McpCall {
            tool_call_id,
            progress,
            ..
        } = &mut item.content
            && let Some((_, latest)) = latest.get(&tool_call_id.0)
        {
            *progress = Some(latest.clone());
        }
    }
    Ok(())
}

async fn export_session(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path(id): Path<String>,
    Query(query): Query<SessionExportQuery>,
) -> Result<Json<SessionExport>, ApiError> {
    let scope = Scope {
        organization_id: Id(query.organization_id),
        team_id: Id(query.team_id),
        actor_id: Id(query.actor_id),
        goal_id: None,
        task_id: None,
    };
    authorize(&state, &headers)?.ensure_scope(&scope)?;
    let snapshot = build_transcript_snapshot(&state, &scope, &Id(id)).await?;
    let format = query.format.unwrap_or(SessionExportFormat::Markdown);
    let (extension, media_type, content) = match format {
        SessionExportFormat::Markdown => (
            "md",
            "text/markdown",
            render_session_export_markdown(&snapshot),
        ),
        SessionExportFormat::Json => (
            "json",
            "application/json",
            serde_json::to_string_pretty(&snapshot)
                .map_err(|error| ApiError::Internal(error.to_string()))?,
        ),
    };
    let title = export_file_stem(&snapshot.session.title);
    let sha256 = format!("{:x}", Sha256::digest(content.as_bytes()));
    Ok(Json(SessionExport {
        session_id: snapshot.session.id,
        format,
        file_name: format!("{title}.{extension}"),
        media_type: media_type.into(),
        content,
        sha256,
    }))
}

async fn get_session_impact(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path(id): Path<String>,
    Query(query): Query<MessageQuery>,
) -> Result<Json<SessionImpactPreview>, ApiError> {
    let scope = Scope {
        organization_id: Id(query.organization_id),
        team_id: Id(query.team_id),
        actor_id: Id(query.actor_id),
        goal_id: None,
        task_id: None,
    };
    authorize(&state, &headers)?.ensure_scope(&scope)?;
    let session_id = Id(id);
    let session = state.store.get_session(&session_id).await?;
    if session.scope.organization_id != scope.organization_id
        || session.scope.team_id != scope.team_id
        || session.scope.actor_id != scope.actor_id
    {
        return Err(ApiError::Forbidden);
    }
    let (turns, messages, attachments, artifacts, forks) = tokio::try_join!(
        state.store.list_turns(&scope, &session_id),
        state.store.list_messages(&scope, &session_id),
        state
            .store
            .list_session_attachments(&scope, &session_id, true),
        state.store.list_session_artifacts(&scope, &session_id),
        state.store.list_session_forks(&scope),
    )?;
    let active_turn_count = turns
        .iter()
        .filter(|turn| {
            !matches!(
                turn.status,
                TurnStatus::Completed | TurnStatus::Failed | TurnStatus::Cancelled
            )
        })
        .count();
    let branch_count = forks
        .iter()
        .filter(|fork| fork.session_id == session_id || fork.parent_session_id == session_id)
        .count();
    Ok(Json(SessionImpactPreview {
        session_id,
        title: session.title,
        status: session.status,
        turn_count: bounded_count(turns.len()),
        active_turn_count: bounded_count(active_turn_count),
        message_count: bounded_count(
            messages
                .iter()
                .filter(|message| matches!(message.role.as_str(), "user" | "assistant"))
                .count(),
        ),
        attachment_count: bounded_count(attachments.len()),
        artifact_count: bounded_count(artifacts.len()),
        branch_count: bounded_count(branch_count),
        stops_active_turns: active_turn_count > 0,
        hides_team_session: true,
        audit_evidence_preserved: true,
    }))
}

fn bounded_count(value: usize) -> u32 {
    u32::try_from(value).unwrap_or(u32::MAX)
}

fn export_file_stem(title: &str) -> String {
    let mut stem = title
        .chars()
        .take(80)
        .map(|character| {
            if character.is_alphanumeric() || matches!(character, '-' | '_') {
                character
            } else {
                '-'
            }
        })
        .collect::<String>();
    while stem.contains("--") {
        stem = stem.replace("--", "-");
    }
    let stem = stem.trim_matches('-');
    if stem.is_empty() {
        "s-code-session".into()
    } else {
        stem.into()
    }
}

fn export_value(value: &serde_json::Value) -> String {
    value.as_str().map(str::to_owned).unwrap_or_else(|| {
        serde_json::to_string_pretty(value).unwrap_or_else(|_| "[unavailable content]".into())
    })
}

fn render_session_export_markdown(snapshot: &TranscriptSnapshot) -> String {
    let mut output = format!(
        "# {}\n\n- Session: `{}`\n- Workspace: `{}`\n- Model: `{}`\n- Status: `{:?}`\n\n",
        snapshot.session.title,
        snapshot.session.id.0,
        snapshot.session.workspace_uri,
        snapshot.session.model,
        snapshot.session.status,
    );
    for item in &snapshot.items {
        match &item.content {
            TranscriptItemContent::Message {
                role,
                content,
                attachments,
            } => {
                let label = if role == "user" { "You" } else { "S-Code" };
                output.push_str(&format!("## {label}\n\n{}\n\n", export_value(content)));
                for attachment in attachments {
                    output.push_str(&format!(
                        "- Attached: `{}` ({}, {} bytes)\n",
                        attachment.file_name, attachment.media_type, attachment.byte_length
                    ));
                }
                if !attachments.is_empty() {
                    output.push('\n');
                }
            }
            TranscriptItemContent::ToolCall {
                display,
                result_summary,
                ..
            }
            | TranscriptItemContent::McpCall {
                display,
                result_summary,
                ..
            } => {
                output.push_str(&format!(
                    "### Tool · {display}\n\nStatus: `{:?}`{}\n\n",
                    item.status,
                    result_summary
                        .as_ref()
                        .map(|summary| format!(" · {summary}"))
                        .unwrap_or_default()
                ));
            }
            TranscriptItemContent::Approval { request } => {
                output.push_str(&format!(
                    "### Approval · {}\n\nStatus: `{:?}` · Risk: `{:?}` · {}\n\n",
                    request.summary, request.status, request.risk, request.policy_reason
                ));
            }
            TranscriptItemContent::ReasoningSummary { text } => {
                output.push_str(&format!("### Reasoning summary\n\n{text}\n\n"));
            }
            TranscriptItemContent::Plan { title, steps } => {
                output.push_str(&format!("### {}\n\n", title.as_deref().unwrap_or("Plan")));
                for step in steps {
                    let marker = if step.status == TranscriptPlanStepStatus::Completed {
                        "x"
                    } else {
                        " "
                    };
                    output.push_str(&format!("- [{marker}] {}\n", step.text));
                }
                output.push('\n');
            }
            TranscriptItemContent::Question { request } => {
                output.push_str("### Question\n\n");
                for question in &request.questions {
                    output.push_str(&format!(
                        "**{}:** {}\n\n",
                        question.header, question.question
                    ));
                    if let Some(answer) = request
                        .answers
                        .iter()
                        .find(|answer| answer.question_id == question.id)
                    {
                        output.push_str(&format!("Answer: {}\n\n", answer.answer));
                    }
                }
            }
            TranscriptItemContent::Warning { code, message } => {
                output.push_str(&format!("> Warning `{code}`: {message}\n\n"));
            }
            TranscriptItemContent::ContextCompaction {
                omitted_messages,
                truncated_messages,
                estimated_tokens,
            } => {
                output.push_str(&format!(
                    "_Context optimized: {omitted_messages} earlier messages summarized, \
                     {truncated_messages} shortened, about {estimated_tokens} summary tokens._\n\n"
                ));
            }
            TranscriptItemContent::ModelReroute {
                from_model,
                to_model,
                reason,
            } => {
                output.push_str(&format!(
                    "_Model switched: {} → {to_model} · {reason}._\n\n",
                    from_model.as_deref().unwrap_or("automatic")
                ));
            }
            TranscriptItemContent::Usage {
                model,
                input_tokens,
                output_tokens,
                total_tokens,
                model_calls,
                tool_calls,
                unknown_usage_calls,
            } => {
                let completeness = match unknown_usage_calls {
                    Some(0) => String::new(),
                    Some(count) => format!(" · incomplete usage for {count} requests"),
                    None => " · completeness unknown".into(),
                };
                output.push_str(&format!(
                    "_Recorded usage: {total_tokens} tokens ({input_tokens} input, {output_tokens} output) · \
                     {model_calls} model calls · {tool_calls} tool calls · `{model}`{completeness}._\n\n"
                ));
            }
            TranscriptItemContent::AgentStatus { label, .. } => {
                output.push_str(&format!("_Agent: {label}._\n\n"));
            }
            TranscriptItemContent::Artifact {
                artifact_id,
                media_type,
                title,
            } => {
                output.push_str(&format!(
                    "### Artifact · {title}\n\n- ID: `{}`\n- Type: `{media_type}`\n\n",
                    artifact_id.0
                ));
            }
            TranscriptItemContent::Hook {
                event,
                handler,
                source_uri,
                input_modified,
                result_summary,
                ..
            } => {
                output.push_str(&format!(
                    "### Hook · {event}\n\nHandler: `{handler}` · Source: `{source_uri}` · Input modified: `{input_modified}`{}\n\n",
                    result_summary
                        .as_ref()
                        .map(|summary| format!(" · {summary}"))
                        .unwrap_or_default()
                ));
            }
        }
    }
    output
}

async fn create_attachment(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path(session_id): Path<String>,
    Json(input): Json<CreateAttachment>,
) -> Result<(StatusCode, Json<AttachmentMetadata>), ApiError> {
    let auth = authorize(&state, &headers)?;
    auth.ensure_scope(&input.scope)?;
    let attachment = state
        .store
        .create_attachment(&Id(session_id), input)
        .await
        .map_err(|error| match error {
            StorageError::InvalidState(message) => ApiError::Conflict(message),
            error => error.into(),
        })?;
    Ok((StatusCode::CREATED, Json(attachment.metadata)))
}

