fn artifact_kind(metadata: &ArtifactMetadata) -> ArtifactKind {
    match metadata.media_type.as_str() {
        "application/vnd.s-code.review+json" => ArtifactKind::ReviewReport,
        "application/vnd.s-code.test+json"
        | "application/junit+xml"
        | "application/vnd.s-code.test-report+json" => ArtifactKind::TestReport,
        "text/x-diff" | "text/x-patch" => ArtifactKind::Diff,
        value if value.starts_with("image/") => ArtifactKind::Image,
        value if value.starts_with("text/") || value == "application/pdf" => ArtifactKind::Document,
        _ => ArtifactKind::Data,
    }
}

async fn list_artifacts(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<ArtifactListQuery>,
) -> Result<Json<ArtifactPage>, ApiError> {
    if !(1..=100).contains(&query.limit) {
        return Err(ApiError::BadRequest(
            "artifact limit must be between 1 and 100".into(),
        ));
    }
    let scope = Scope {
        organization_id: Id(query.organization_id),
        team_id: Id(query.team_id),
        actor_id: Id(query.actor_id),
        goal_id: None,
        task_id: None,
    };
    authorize(&state, &headers)?.ensure_scope(&scope)?;
    let cursor = query
        .cursor
        .as_deref()
        .map(decode_artifact_cursor)
        .transpose()?;
    let session_id = query.session_id.map(Id);
    let mut artifacts = state
        .store
        .list_artifacts(
            &scope,
            session_id.as_ref(),
            query.media_type.as_deref(),
            cursor
                .as_ref()
                .map(|cursor| (&cursor.created_at, &cursor.id)),
            query.limit + 1,
        )
        .await?;
    let has_more = artifacts.len() > query.limit;
    artifacts.truncate(query.limit);
    let next_cursor = if has_more {
        artifacts
            .last()
            .map(|artifact| encode_artifact_cursor(&artifact.metadata))
            .transpose()?
    } else {
        None
    };
    let mut entries = Vec::with_capacity(artifacts.len());
    for artifact in artifacts {
        let session = state
            .store
            .get_session(&artifact.metadata.session_id)
            .await?;
        if session.scope.organization_id != scope.organization_id
            || session.scope.team_id != scope.team_id
            || session.scope.actor_id != scope.actor_id
        {
            return Err(ApiError::Forbidden);
        }
        entries.push(ArtifactIndexEntry {
            kind: artifact_kind(&artifact.metadata),
            session_title: session.title,
            workspace_uri: session.workspace_uri,
            metadata: artifact.metadata,
        });
    }
    Ok(Json(ArtifactPage {
        artifacts: entries,
        next_cursor,
    }))
}

