    ensure_path_team(&team_id, &input.scope)?;
    ensure_base_team_scope(&input.scope)?;
    let goal = state.store.create_team_goal(input).await?;
    publish_team_event(
        &state,
        &goal.scope,
        "team.goal.created",
        serde_json::json!({"goal_id":goal.id,"title":goal.title}),
    )
    .await?;
