#[derive(Clone, Deserialize)]
struct TeamAuditQuery {
    organization_id: String,
    actor_id: String,
    #[serde(default)]
    after: u64,
    #[serde(default = "default_team_page_limit")]
    limit: u32,
    #[serde(default)]
    filter_actor_id: Option<String>,
    #[serde(default)]
    session_id: Option<String>,
    #[serde(default)]
    turn_id: Option<String>,
    #[serde(default)]
    goal_id: Option<String>,
    #[serde(default)]
    task_id: Option<String>,
    #[serde(default)]
    kind: Option<String>,
    #[serde(default)]
    since: Option<DateTime<Utc>>,
    #[serde(default)]
    until: Option<DateTime<Utc>>,
}

fn audit_filter_id(value: &Option<String>, label: &str) -> Result<Option<Id>, ApiError> {
    value
        .as_ref()
        .map(|value| {
            if value.is_empty() || value.len() > 256 || value.chars().any(char::is_control) {
                Err(ApiError::BadRequest(format!(
                    "audit {label} filter is invalid"
                )))
            } else {
                Ok(Id(value.clone()))
            }
        })
        .transpose()
}

fn audit_query_scope(team_id: String, query: &TeamAuditQuery) -> Result<Scope, ApiError> {
    if query.kind.as_ref().is_some_and(|kind| {
        kind.is_empty()
            || kind.len() > 128
            || !kind
                .bytes()
                .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'.' | b'_' | b'-'))
    }) || query
        .since
        .zip(query.until)
        .is_some_and(|(since, until)| since > until)
    {
        return Err(ApiError::BadRequest(
            "audit action or time filter is invalid".into(),
        ));
    }
    Ok(Scope {
        organization_id: Id(query.organization_id.clone()),
        team_id: Id(team_id),
        actor_id: Id(query.actor_id.clone()),
        goal_id: None,
        task_id: None,
    })
}

fn audit_payload_id(event: &Event, name: &str) -> Option<Id> {
    event
        .payload
        .get(name)
        .and_then(serde_json::Value::as_str)
        .filter(|value| !value.is_empty() && value.len() <= 256)
        .map(|value| Id(value.to_owned()))
}

fn audit_summary(event: Event) -> AuditEventSummary {
    let item_id = audit_payload_id(&event, "item_id");
    let request_id = audit_payload_id(&event, "request_id");
    AuditEventSummary {
        id: event.id,
        sequence: event.sequence,
        timestamp: event.timestamp,
        kind: event.kind,
        actor_id: event.scope.actor_id,
        goal_id: event.scope.goal_id,
        task_id: event.scope.task_id,
        session_id: event.session_id,
        turn_id: event.turn_id,
        item_id,
        request_id,
    }
}

async fn filtered_team_audit_events(
    state: &AppState,
    scope: &Scope,
    query: &TeamAuditQuery,
    limit: u32,
) -> Result<Vec<Event>, ApiError> {
    let filter_actor_id = audit_filter_id(&query.filter_actor_id, "actor")?;
    let session_id = audit_filter_id(&query.session_id, "Session")?;
    let turn_id = audit_filter_id(&query.turn_id, "Turn")?;
    let goal_id = audit_filter_id(&query.goal_id, "Goal")?;
    let task_id = audit_filter_id(&query.task_id, "Task")?;
    Ok(state
        .store
        .list_team_events_filtered(
            scope,
            query.after,
            None,
            limit,
            filter_actor_id.as_ref(),
            session_id.as_ref(),
            turn_id.as_ref(),
            goal_id.as_ref(),
            task_id.as_ref(),
            query.kind.as_deref(),
            query.since,
            query.until,
        )
        .await?)
}

async fn list_team_audit(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path(team_id): Path<String>,
    Query(query): Query<TeamAuditQuery>,
) -> Result<Json<AuditEventPage>, ApiError> {
    let scope = audit_query_scope(team_id, &query)?;
    let auth = authorize(&state, &headers)?;
    auth.ensure_scope_with(&scope, Permission::ReadAudit)?;
    auth.ensure_audit_reader()?;
    let limit = query.limit.clamp(1, 200);
    let mut events =
        filtered_team_audit_events(&state, &scope, &query, limit.saturating_add(1)).await?;
    let has_more = events.len() > limit as usize;
    if has_more {
        events.truncate(limit as usize);
    }
    let next_cursor = has_more
        .then(|| events.last().map(|event| event.sequence))
        .flatten();
    Ok(Json(AuditEventPage {
        events: events.into_iter().map(audit_summary).collect(),
        next_cursor,
    }))
}

fn csv_cell(value: &str) -> String {
    let mut value = value.replace(['\r', '\n'], " ");
    let formula_candidate = value.trim_start_matches(|character: char| {
        character.is_ascii_whitespace() || character == '\u{feff}'
    });
    if value
        .chars()
        .next()
        .is_some_and(|character| character.is_control())
        || formula_candidate.starts_with(['=', '+', '-', '@'])
    {
        value.insert(0, '\'');
    }
    format!("\"{}\"", value.replace('"', "\"\""))
}

async fn export_team_audit(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path(team_id): Path<String>,
    Query(mut query): Query<TeamAuditQuery>,
) -> Result<Response, ApiError> {
    let scope = audit_query_scope(team_id, &query)?;
    let auth = authorize(&state, &headers)?;
    auth.ensure_scope_with(&scope, Permission::ReadAudit)?;
    auth.ensure_audit_reader()?;
    query.after = 0;
    let events =
        filtered_team_audit_events(&state, &scope, &query, query.limit.clamp(1, 1000)).await?;
    let mut csv = String::from(
        "event_id,sequence,timestamp,organization_id,team_id,actor_id,goal_id,task_id,session_id,turn_id,item_id,request_id,action\n",
    );
    for event in events {
        let summary = audit_summary(event);
        let values = [
            summary.id.0,
            summary.sequence.to_string(),
            summary.timestamp.to_rfc3339(),
            scope.organization_id.0.clone(),
            scope.team_id.0.clone(),
            summary.actor_id.0,
            summary.goal_id.map(|id| id.0).unwrap_or_default(),
            summary.task_id.map(|id| id.0).unwrap_or_default(),
            summary.session_id.map(|id| id.0).unwrap_or_default(),
            summary.turn_id.map(|id| id.0).unwrap_or_default(),
            summary.item_id.map(|id| id.0).unwrap_or_default(),
            summary.request_id.map(|id| id.0).unwrap_or_default(),
            summary.kind,
        ];
        csv.push_str(
            &values
                .iter()
                .map(|value| csv_cell(value))
                .collect::<Vec<_>>()
                .join(","),
        );
        csv.push('\n');
    }
    Ok((
        [
            (header::CONTENT_TYPE, "text/csv; charset=utf-8"),
            (
                header::CONTENT_DISPOSITION,
                "attachment; filename=s-code-team-audit.csv",
            ),
            (header::CACHE_CONTROL, "no-store"),
        ],
        csv,
    )
        .into_response())
}

