async fn apply_team_configuration(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path(team_id): Path<String>,
    Json(envelope): Json<SignedTeamConfiguration>,
) -> Result<Json<TeamCapacity>, ApiError> {
    authorize(&state, &headers)?.ensure_team_with(
        &envelope.payload.organization_id,
        &envelope.payload.team_id,
        Permission::ManagePolicies,
    )?;
    if envelope.payload.team_id.0 != team_id {
        return Err(ApiError::Forbidden);
    }
    let installed_sequence = state
        .store
        .installed_team_configuration_sequence(
            &envelope.payload.organization_id,
            &envelope.payload.team_id,
        )
        .await?;
    state
        .team_configuration_trust
        .verify_team_configuration(
            &envelope,
            &envelope.payload.organization_id,
            &envelope.payload.team_id,
            installed_sequence,
            Utc::now(),
        )
        .map_err(|error| ApiError::BadRequest(error.to_string()))?;
    let capacity = state
        .store
        .apply_verified_team_configuration(&envelope)
        .await?;
    publish_team_event(
        &state,
        &capacity.scope,
        "team.configuration.applied",
        serde_json::json!({"sequence":envelope.payload.sequence,"key_id":envelope.key_id,"expires_at":envelope.payload.expires_at,"policy_sequence":envelope.payload.configuration.policy_sequence,"knowledge_version":envelope.payload.configuration.knowledge_version}),
    )
    .await?;
    Ok(Json(capacity))
}

