async fn apply_policy_exception(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path(team_id): Path<String>,
    Json(envelope): Json<SignedPolicyExceptionGrant>,
) -> Result<Json<SignedPolicyExceptionGrant>, ApiError> {
    authorize(&state, &headers)?.ensure_team_with(
        &envelope.payload.organization_id,
        &envelope.payload.team_id,
        Permission::ManagePolicies,
    )?;
    if envelope.payload.team_id.0 != team_id {
        return Err(ApiError::Forbidden);
    }
    let installed_sequence = state
        .store
        .installed_policy_exception_sequence(&envelope.payload.exception_id)
        .await?;
    state
        .team_configuration_trust
        .verify_policy_exception(
            &envelope,
            &envelope.payload.organization_id,
            &envelope.payload.team_id,
            installed_sequence,
            Utc::now(),
        )
        .map_err(|error| ApiError::BadRequest(error.to_string()))?;
    let payload = state
        .store
        .apply_verified_policy_exception(&envelope)
        .await?;
    let scope = Scope {
        organization_id: payload.organization_id,
        team_id: payload.team_id,
        actor_id: payload.approved_by,
        goal_id: None,
        task_id: None,
    };
    publish_team_event(
        &state,
        &scope,
        if payload.active {
            "policy.exception.applied"
        } else {
            "policy.exception.revoked"
        },
        serde_json::json!({
            "exception_id": payload.exception_id,
            "sequence": payload.sequence,
            "tool": payload.tool,
            "actor_id": payload.actor_id,
            "workspace_uri": payload.workspace_uri,
            "expires_at": payload.expires_at,
            "approved_by": scope.actor_id,
        }),
    )
    .await?;
    Ok(Json(envelope))
}

