async fn team_governance_summary(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path(team_id): Path<String>,
    Query(query): Query<TeamQuery>,
) -> Result<Json<TeamGovernanceSummary>, ApiError> {
    let scope = team_scope(team_id, query);
    authorize(&state, &headers)?.ensure_scope_with(&scope, Permission::ReadDashboard)?;
    let configuration = state
        .store
        .latest_team_configuration(&scope.organization_id, &scope.team_id)
        .await?;
    let summary = if let Some(envelope) = configuration {
        let policy = envelope.payload.configuration.audit_content_policy.as_ref();
        TeamGovernanceSummary {
            source: "enterprise_signed".into(),
            configuration_sequence: Some(envelope.payload.sequence),
            policy_sequence: Some(envelope.payload.configuration.policy_sequence),
            issued_at: Some(envelope.payload.issued_at),
            expires_at: Some(envelope.payload.expires_at),
            audit_content_enabled: policy.is_some(),
            audit_retention_days: policy.map(|value| value.retention_days),
            data_residency_region: policy.map(|value| value.residency_region.clone()),
            audit_content_categories: policy
                .map(|value| value.content_categories.clone())
                .unwrap_or_default(),
        }
    } else {
        TeamGovernanceSummary {
            source: "community_local".into(),
            configuration_sequence: None,
            policy_sequence: None,
            issued_at: None,
            expires_at: None,
            audit_content_enabled: false,
            audit_retention_days: None,
            data_residency_region: None,
            audit_content_categories: Vec::new(),
        }
    };
    Ok(Json(summary))
}

