async fn create_turn_input(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path(session_id): Path<String>,
    Json(input): Json<CreateTurnInput>,
) -> Result<(StatusCode, Json<TurnInput>), ApiError> {
    let auth = authorize(&state, &headers)?;
    auth.ensure_scope(&input.scope)?;
    let has_active_turn = state
        .runtime_scopes
        .contains_turn(&input.target_turn_id)
        .await;
    let admission = match input.mode {
        TurnInputMode::Steer => StepAdmission::ActiveTurnOnly,
        TurnInputMode::Queue => StepAdmission::ActiveOrNextTurn,
    };
    let admission_target = admission
        .target(has_active_turn)
        .map_err(|error| ApiError::Conflict(error.to_string()))?;
    if input.mode == TurnInputMode::Steer {
        let target = state
            .store
            .get_turn(&input.scope, &input.target_turn_id)
            .await?;
        if target.session_id.0 != session_id {
            return Err(ApiError::BadRequest(
                "target turn belongs to a different session".into(),
            ));
        }
        if admission_target != AdmissionTarget::ActiveTurn {
            return Err(ApiError::Conflict(
                "only a currently executing turn can be steered".into(),
            ));
        }
    }
    let turn_input = state
        .store
        .create_turn_input(&Id(session_id), input)
        .await
        .map_err(|error| match error {
            StorageError::InvalidState(message) => ApiError::Conflict(message),
            error => error.into(),
        })?;
    publish_turn_input_changed_with_admission(&state, &turn_input, admission, admission_target)
        .await?;
    if turn_input.status == TurnInputStatus::Pending
        && admission_target == AdmissionTarget::ActiveTurn
        && let Err(error) = state
            .runtime_scopes
            .submit_step_input(&turn_input.target_turn_id, turn_input.id.clone())
            .await
    {
        tracing::debug!(
            input_id = %turn_input.id.0,
            ?error,
            "active Agent closed admission; persistent input will run on the next Turn"
        );
    }
    Ok((StatusCode::ACCEPTED, Json(turn_input)))
}

