async fn publish_turn_input_changed(state: &AppState, input: &TurnInput) -> Result<(), ApiError> {
    let has_active_turn = state
        .runtime_scopes
        .contains_turn(&input.target_turn_id)
        .await;
    let admission = match (input.mode.clone(), has_active_turn) {
        (TurnInputMode::Steer, true) => StepAdmission::ActiveTurnOnly,
        _ => StepAdmission::ActiveOrNextTurn,
    };
    let target = admission
        .target(has_active_turn)
        .unwrap_or(AdmissionTarget::NextTurn);
    publish_turn_input_changed_with_admission(state, input, admission, target).await
}

async fn publish_turn_input_changed_with_admission(
    state: &AppState,
    input: &TurnInput,
    admission: StepAdmission,
    admission_target: AdmissionTarget,
) -> Result<(), ApiError> {
    let kind = match (&input.mode, &input.status) {
        (TurnInputMode::Steer, TurnInputStatus::Pending) => "turn.input.steering",
        (_, TurnInputStatus::Pending) => "turn.input.queued",
        (_, TurnInputStatus::Processing) => "turn.input.processing",
        (_, TurnInputStatus::Consumed) => "turn.input.consumed",
        (_, TurnInputStatus::Cancelled) => "turn.input.cancelled",
    };
    state
        .publish(Event {
            id: Id::new("evt"),
            sequence: 0,
            timestamp: Utc::now(),
            scope: input.scope.clone(),
            session_id: Some(input.session_id.clone()),
            turn_id: Some(input.target_turn_id.clone()),
            kind: kind.into(),
            payload: serde_json::json!({
                "input_id": input.id,
                "target_turn_id": input.target_turn_id,
                "resulting_turn_id": input.resulting_turn_id,
                "mode": input.mode,
                "status": input.status,
                "revision": input.revision,
                "step_admission": admission,
                "admission_target": match admission_target {
                    AdmissionTarget::ActiveTurn => "active_turn",
                    AdmissionTarget::NewTurn => "new_turn",
                    AdmissionTarget::NextTurn => "next_turn",
                },
            }),
        })
        .await?;
    Ok(())
}

async fn create_review(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path(session_id): Path<String>,
    Json(input): Json<CreateReview>,
) -> Result<(StatusCode, Json<Turn>), ApiError> {
    let auth = authorize(&state, &headers)?;
    auth.ensure_scope(&input.scope)?;
    let target = review_target_instruction(&input.target)?;
    let content = serde_json::Value::String(format!(
        "Review {target}. Report only actionable correctness, security, performance, and test-coverage findings. Use read-only tools, then call report_review_findings exactly once with every finding ordered by severity and an exact workspace-relative file and line range. Use an empty findings array when no actionable issue exists. Do not modify files, run arbitrary commands, access the network, or perform external writes.{}",
        input
            .instructions
            .filter(|value| !value.trim().is_empty())
            .map(|value| format!("\n\nAdditional review instructions: {value}"))
            .unwrap_or_default()
    ));
    let turn = start_agent_turn(
        state,
        Id(session_id),
        input.scope,
        content,
        vec![],
        ToolProfile::Review,
        true,
    )
    .await?;
    Ok((StatusCode::ACCEPTED, Json(turn)))
}

fn review_target_instruction(target: &str) -> Result<String, ApiError> {
    if target == "uncommitted" {
        return Ok("all uncommitted Git changes".into());
    }
    let (kind, value) = target
        .split_once(':')
        .ok_or_else(|| ApiError::BadRequest("invalid review target".into()))?;
    if !matches!(kind, "base" | "commit")
        || value.is_empty()
        || value.len() > 128
        || value.starts_with('-')
        || !value
            .chars()
            .all(|character| character.is_ascii_alphanumeric() || "/._-".contains(character))
    {
        return Err(ApiError::BadRequest("invalid review target".into()));
    }
    Ok(if kind == "base" {
        format!("changes against Git base {value}; pass revision {value}...HEAD to git_diff")
    } else {
        format!("Git commit {value}; pass revision {value}^! to git_diff")
    })
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum ToolProfile {
    Default,
    Plan,
    Review,
}

async fn start_agent_turn(
    state: AppState,
    session_id: Id,
    scope: Scope,
    content: serde_json::Value,
    attachment_ids: Vec<Id>,
    profile: ToolProfile,
    generate_title: bool,
) -> Result<Turn, ApiError> {
    let provider = state.model_provider.clone().ok_or(ApiError::Unavailable(
        "model provider is not configured".into(),
    ))?;
    let session = state.store.get_session(&session_id).await?;
    ensure_model_allowed(&state, &scope, &session.model).await?;
    validate_workspace(&session.workspace_uri)?;
    let (turn, user_message) = state
        .store
        .create_turn_with_user_message_and_attachments_if_idle(
            &scope,
            &session_id,
            content,
            &attachment_ids,
        )
        .await
        .map_err(|error| match error {
            StorageError::InvalidState(message) => ApiError::Conflict(message),
            error => error.into(),
        })?;
    launch_prepared_agent_turn(
        state,
        provider,
        turn.clone(),
        user_message,
        profile,
        None,
        generate_title,
    )
    .await?;
    Ok(turn)
}

async fn start_claimed_turn_input(
    state: AppState,
    provider: Arc<dyn ModelProvider>,
    input: TurnInput,
) -> Result<(), ApiError> {
    let session = state.store.get_session(&input.session_id).await?;
    ensure_model_allowed(&state, &input.scope, &session.model).await?;
    validate_workspace(&session.workspace_uri)?;
    let (consumed, turn, user_message) =
        state.store.consume_turn_input_into_turn(&input.id).await?;
    publish_turn_input_changed(&state, &consumed).await?;
    launch_prepared_agent_turn(
        state,
        provider,
        turn,
        user_message,
        ToolProfile::Default,
        Some(input.id),
        true,
    )
    .await
}

async fn launch_prepared_agent_turn(
    state: AppState,
    provider: Arc<dyn ModelProvider>,
    turn: Turn,
    user_message: Message,
    profile: ToolProfile,
    source_input_id: Option<Id>,
    generate_title: bool,
) -> Result<(), ApiError> {
    let cancellation = CancellationToken::new();
    let step_inputs = state
        .runtime_scopes
        .open_turn(
            turn.session_id.clone(),
            turn.id.clone(),
            cancellation.clone(),
        )
        .await?;
    if let Err(error) = state
        .publish(Event {
            id: Id::new("evt"),
            sequence: 0,
            timestamp: Utc::now(),
            scope: turn.scope.clone(),
            session_id: Some(turn.session_id.clone()),
            turn_id: Some(turn.id.clone()),
            kind: "turn.created".into(),
            payload: serde_json::json!({
                "status": turn.status,
                "item_id": user_message.id,
                "source_input_id": source_input_id,
            }),
        })
        .await
    {
        state.runtime_scopes.close_turn(&turn.id).await;
        return Err(error);
    }
    let task_state = state.clone();
    let task_turn = turn.clone();
    tokio::spawn(async move {
        let running_turn =
            RunningTurnGuard::new(task_state.runtime_scopes.clone(), task_turn.id.clone());
        let execution = run_turn_with_step_inputs(
            task_state.clone(),
            provider,
            task_turn.clone(),
            cancellation,
            profile,
            Some(step_inputs),
            generate_title,
        )
        .await;
        match execution {
            Err(error) => {
                tracing::error!(turn_id = %task_turn.id.0, ?error, "turn execution failed");
                let updated = task_state
                    .store
                    .update_turn(
                        &task_turn.scope,
                        &task_turn.id,
                        TurnStatus::Failed,
                        None,
                        Some("agent_error"),
                    )
                    .await;
                if updated.is_ok() {
                    let _ = task_state
                        .publish(Event {
                            id: Id::new("evt"),
                            sequence: 0,
                            timestamp: Utc::now(),
                            scope: task_turn.scope.clone(),
                            session_id: Some(task_turn.session_id.clone()),
                            turn_id: Some(task_turn.id.clone()),
                            kind: "turn.failed".into(),
                            payload: serde_json::json!({
                                "status": "failed",
                                "error_code": "agent_error",
                            }),
                        })
                        .await;
                }
            }
            Ok(()) => {
                let completed = task_state
                    .store
                    .get_turn(&task_turn.scope, &task_turn.id)
                    .await
                    .is_ok_and(|turn| turn.status == TurnStatus::Completed);
                if completed
                    && let Err(error) = queue_session_goal_continuation(
                        &task_state,
                        &task_turn.scope,
                        &task_turn.session_id,
                    )
                    .await
                {
                    tracing::warn!(
                        turn_id = %task_turn.id.0,
                        ?error,
                        "Session Goal auto-continuation could not be queued"
                    );
                }
            }
        }
        running_turn.close().await;
    });
    Ok(())
}

