#[derive(Clone, Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct ToolSearchArgs {
    query: String,
    #[serde(default = "default_tool_search_limit")]
    limit: usize,
}

fn default_tool_search_limit() -> usize {
    8
}

#[derive(Clone)]
struct DeferredToolMatch {
    score: u32,
    name: String,
    description: String,
    source: String,
}

fn search_tool_catalog(
    registry: &McpRegistry,
    input: &ToolSearchArgs,
) -> Result<Vec<DeferredToolMatch>, String> {
    let query = input.query.trim().to_ascii_lowercase();
    if query.is_empty() || query.chars().count() > 200 || input.limit == 0 || input.limit > 20 {
        return Err(
            "Tool Search requires a 1..200 character query and a limit from 1 to 20".into(),
        );
    }
    let terms = query.split_whitespace().collect::<Vec<_>>();
    let mut candidates = registry
        .definitions()
        .into_iter()
        .map(|definition| DeferredToolMatch {
            score: 0,
            source: definition
                .name
                .strip_prefix("mcp.")
                .and_then(|value| value.split_once('.'))
                .map(|(server, _)| format!("mcp:{server}"))
                .unwrap_or_else(|| "extension".into()),
            name: definition.name,
            description: definition.description,
        })
        .chain(
            builtin_tools()
                .into_iter()
                .filter(|definition| !is_initial_default_tool(&definition.name))
                .map(|definition| DeferredToolMatch {
                    score: 0,
                    name: definition.name,
                    description: definition.description,
                    source: "built_in".into(),
                }),
        )
        .filter_map(|mut candidate| {
            let name = candidate.name.to_ascii_lowercase();
            let description = candidate.description.to_ascii_lowercase();
            let mut score = 0_u32;
            for term in &terms {
                if name == *term {
                    score += 100;
                } else if name.starts_with(term) {
                    score += 40;
                } else if name.contains(term) {
                    score += 20;
                }
                if description.contains(term) {
                    score += 5;
                }
            }
            candidate.score = score;
            (score > 0).then_some(candidate)
        })
        .collect::<Vec<_>>();
    candidates.sort_by(|left, right| {
        right
            .score
            .cmp(&left.score)
            .then_with(|| left.name.cmp(&right.name))
    });
    candidates.truncate(input.limit);
    Ok(candidates)
}

