#[async_trait::async_trait]
impl McpElicitationHandler for DaemonMcpElicitationHandler {
    async fn elicit(
        &self,
        elicitation: McpElicitationRequest,
    ) -> Result<McpElicitationResponse, McpError> {
        validate_mcp_elicitation_schema(&elicitation.requested_schema)?;
        let request_id = Id::new("qst");
        let requested_at = Utc::now();
        let schema_fields = elicitation.requested_schema["properties"]
            .as_object()
            .map(|properties| properties.keys().cloned().collect::<Vec<_>>().join(", "))
            .unwrap_or_default();
        let request = QuestionRequest {
            id: request_id.clone(),
            item_id: Id(format!("mcp_elicitation_{}", request_id.0)),
            session_id: self.session_id.clone(),
            turn_id: self.turn_id.clone(),
            questions: vec![
                QuestionPrompt {
                    id: "mcp_content".into(),
                    header: "MCP data".into(),
                    question: format!(
                        "{} Enter a JSON object for fields: {}. Never enter passwords, API keys, access tokens, or payment credentials.",
                        elicitation.message,
                        schema_fields
                    )
                    .chars()
                    .take(500)
                    .collect(),
                    options: vec![s_code_protocol::QuestionOption {
                        label: "No data".into(),
                        description: "Use this together with Decline or Cancel.".into(),
                    }],
                },
                QuestionPrompt {
                    id: "mcp_action".into(),
                    header: "Consent".into(),
                    question: format!(
                        "Share the reviewed form response with MCP server {}?",
                        elicitation.server_id
                    ),
                    options: vec![
                        s_code_protocol::QuestionOption {
                            label: "Cancel".into(),
                            description: "Safely cancel if no decision is made.".into(),
                        },
                        s_code_protocol::QuestionOption {
                            label: "Decline".into(),
                            description: "Decline this request without sending form data.".into(),
                        },
                        s_code_protocol::QuestionOption {
                            label: "Accept".into(),
                            description: "Send the reviewed JSON object to this MCP server.".into(),
                        },
                    ],
                },
            ],
            allow_other: true,
            requested_by: self.scope.actor_id.clone(),
            requested_at,
            expires_at: Some(requested_at + chrono::Duration::seconds(120)),
            status: QuestionStatus::Pending,
            answers: Vec::new(),
            answered_by: None,
            answered_at: None,
            revision: 1,
        };
        let request = self
            .events
            .store
            .create_question_request(&self.scope, &request)
            .await
            .map_err(|error| McpError::Protocol(error.to_string()))?;
        self.events
            .publish(Event {
                id: Id::new("evt"),
                sequence: 0,
                timestamp: Utc::now(),
                scope: self.scope.clone(),
                session_id: Some(self.session_id.clone()),
                turn_id: Some(self.turn_id.clone()),
                kind: "question.required".into(),
                payload: serde_json::json!({
                    "request_id": request.id,
                    "item_id": request.item_id,
                    "questions": request.questions,
                    "allow_other": request.allow_other,
                    "expires_at": request.expires_at,
                    "status": "awaiting_input",
                    "source": "mcp_elicitation",
                    "server_id": elicitation.server_id,
                    "tool_call_id": self.tool_call_id,
                }),
            })
            .await
            .map_err(|error| McpError::Protocol(format!("{error:?}")))?;
        let answered = tokio::time::timeout(std::time::Duration::from_secs(125), async {
            loop {
                let current = self
                    .events
                    .store
                    .get_question_request(&self.scope, &request_id)
                    .await
                    .map_err(|error| McpError::Protocol(error.to_string()))?;
                match current.status {
                    QuestionStatus::Answered
                    | QuestionStatus::Expired
                    | QuestionStatus::Cancelled => {
                        return Ok::<QuestionRequest, McpError>(current);
                    }
                    QuestionStatus::Pending => {
                        tokio::time::sleep(std::time::Duration::from_millis(100)).await;
                    }
                }
            }
        })
        .await
        .map_err(|_| McpError::Timeout)??;
        let action = answered
            .answers
            .iter()
            .find(|answer| answer.question_id == "mcp_action")
            .map(|answer| answer.answer.as_str());
        match action {
            Some("Accept") if answered.status == QuestionStatus::Answered => {
                let raw = answered
                    .answers
                    .iter()
                    .find(|answer| answer.question_id == "mcp_content")
                    .map(|answer| answer.answer.as_str())
                    .unwrap_or_default();
                let content: serde_json::Value = serde_json::from_str(raw).map_err(|_| {
                    McpError::Protocol(
                        "accepted MCP elicitation content must be a JSON object".into(),
                    )
                })?;
                validate_mcp_elicitation_content(&elicitation.requested_schema, &content)?;
                Ok(McpElicitationResponse::Accept { content })
            }
            Some("Decline") if answered.status == QuestionStatus::Answered => {
                Ok(McpElicitationResponse::Decline)
            }
            _ => Ok(McpElicitationResponse::Cancel),
        }
    }
}

fn validate_mcp_elicitation_schema(schema: &serde_json::Value) -> Result<(), McpError> {
    let object = schema
        .as_object()
        .filter(|schema| schema.get("type").and_then(serde_json::Value::as_str) == Some("object"))
        .ok_or_else(|| {
            McpError::Protocol("MCP elicitation requires an object form schema".into())
        })?;
    let properties = object
        .get("properties")
        .and_then(serde_json::Value::as_object)
        .filter(|properties| !properties.is_empty() && properties.len() <= 32)
        .ok_or_else(|| {
            McpError::Protocol("MCP elicitation requires 1 to 32 form properties".into())
        })?;
    for (name, property) in properties {
        let normalized = name.to_ascii_lowercase();
        if name.is_empty()
            || name.len() > 128
            || [
                "password",
                "secret",
                "token",
                "credential",
                "api_key",
                "apikey",
                "payment",
                "card_number",
            ]
            .iter()
            .any(|sensitive| normalized.contains(sensitive))
        {
            return Err(McpError::Protocol(
                "MCP form elicitation may not request secrets or payment credentials".into(),
            ));
        }
        let property = property
            .as_object()
            .ok_or_else(|| McpError::Protocol("MCP form property is invalid".into()))?;
        if !matches!(
            property.get("type").and_then(serde_json::Value::as_str),
            Some("string" | "number" | "integer" | "boolean")
        ) {
            return Err(McpError::Protocol(
                "MCP form properties must use primitive types".into(),
            ));
        }
    }
    Ok(())
}

fn validate_mcp_elicitation_content(
    schema: &serde_json::Value,
    content: &serde_json::Value,
) -> Result<(), McpError> {
    validate_mcp_elicitation_schema(schema)?;
    let content = content
        .as_object()
        .ok_or_else(|| McpError::Protocol("MCP elicitation content must be an object".into()))?;
    let properties = schema["properties"]
        .as_object()
        .expect("schema was validated");
    if content.keys().any(|key| !properties.contains_key(key)) {
        return Err(McpError::Protocol(
            "MCP elicitation content contains an undeclared property".into(),
        ));
    }
    let required = schema
        .get("required")
        .and_then(serde_json::Value::as_array)
        .into_iter()
        .flatten()
        .filter_map(serde_json::Value::as_str)
        .collect::<BTreeSet<_>>();
    if required.iter().any(|name| !content.contains_key(*name)) {
        return Err(McpError::Protocol(
            "MCP elicitation content is missing a required property".into(),
        ));
    }
    for (name, value) in content {
        let property = &properties[name];
        let valid_type = match property["type"].as_str() {
            Some("string") => value.is_string(),
            Some("number") => value.is_number(),
            Some("integer") => value.as_i64().is_some() || value.as_u64().is_some(),
            Some("boolean") => value.is_boolean(),
            _ => false,
        };
        if !valid_type
            || property
                .get("enum")
                .and_then(serde_json::Value::as_array)
                .is_some_and(|allowed| !allowed.contains(value))
        {
            return Err(McpError::Protocol(format!(
                "MCP elicitation property {name} does not match its schema"
            )));
        }
    }
    Ok(())
}

#[async_trait::async_trait]
impl ExternalToolExecutor for ConnectorToolExecutor {
    async fn execute(
        &self,
        call: &s_code_protocol::ToolCall,
    ) -> Result<Option<serde_json::Value>, String> {
        if call.request.tool == "tool_search" {
            let input: ToolSearchArgs = serde_json::from_value(call.request.arguments.clone())
                .map_err(|error| format!("invalid Tool Search request: {error}"))?;
            let definitions = search_tool_catalog(&self.mcp, &input)?;
            return Ok(Some(serde_json::json!({
                "query": input.query,
                "matched": definitions.len(),
                "tools": definitions
                    .iter()
                    .map(|definition| serde_json::json!({
                        "name": definition.name,
                        "description": definition.description,
                        "source": definition.source,
                    }))
                    .collect::<Vec<_>>(),
                "schemas_loaded_for_this_turn": definitions.len(),
            })));
        }
        if self.mcp.contains(&call.request.tool) {
            let (progress_tx, mut progress_rx) = mpsc::channel(64);
            let elicitation = Arc::new(DaemonMcpElicitationHandler {
                events: self.events.clone(),
                scope: call.request.scope.clone(),
                session_id: call.request.session_id.clone(),
                turn_id: call.request.turn_id.clone(),
                tool_call_id: call.request.id.clone(),
            });
            let request = self.mcp.call_with_progress_and_elicitation(
                &call.request.tool,
                call.request.arguments.clone(),
                Some(progress_tx),
                Some(elicitation),
            );
            tokio::pin!(request);
            loop {
                tokio::select! {
                    result = &mut request => {
                        while let Ok(progress) = progress_rx.try_recv() {
                            self.publish_mcp_progress(call, progress).await;
                        }
                        return result.map(Some).map_err(|error| error.to_string());
                    }
                    progress = progress_rx.recv() => {
                        if let Some(progress) = progress {
                            self.publish_mcp_progress(call, progress).await;
                        } else {
                            return request.await.map(Some).map_err(|error| error.to_string());
                        }
                    }
                }
            }
        }
        let task_id = call
            .request
            .scope
            .task_id
            .clone()
            .ok_or_else(|| "connector writes require a Team task scope".to_owned())?;
        let context = |actor_reason, idempotency_key| ActionContext {
            scope: call.request.scope.clone(),
            session_id: call.request.session_id.clone(),
            task_id: task_id.clone(),
            actor_reason,
            idempotency_key,
        };
        match call.request.tool.as_str() {
            "scm_create_draft_pr" => {
                let args: DraftPrToolArgs = serde_json::from_value(call.request.arguments.clone())
                    .map_err(|error| error.to_string())?;
                let connector = self
                    .scm
                    .as_ref()
                    .ok_or_else(|| "no source-control connector is configured".to_owned())?;
                let pull_request = connector
                    .create_draft_pr(CreateDraftPullRequest {
                        context: context(args.actor_reason, args.idempotency_key),
                        title: args.title,
                        base: args.base,
                        head: args.head,
                        expected_head_oid: args.expected_head_oid,
                        evidence: args.evidence,
                    })
                    .await
                    .map_err(|error| error.to_string())?;
                serde_json::to_value(pull_request)
                    .map(Some)
                    .map_err(|error| error.to_string())
            }
            "ticket_write_back" => {
                let args: TicketWriteBackToolArgs =
                    serde_json::from_value(call.request.arguments.clone())
                        .map_err(|error| error.to_string())?;
                let connector = self
                    .work
                    .as_ref()
                    .ok_or_else(|| "no work-management connector is configured".to_owned())?;
                connector
                    .write_back(WriteBack {
                        context: context(args.actor_reason, args.idempotency_key),
                        issue_number: args.issue_number,
                        expected_issue_version: args.expected_issue_version,
                        message: args.message,
                        evidence_urls: args.evidence_urls,
                    })
                    .await
                    .map_err(|error| error.to_string())?;
                Ok(Some(serde_json::json!({"written":true})))
            }
            "servicenow_read_record" => {
                let args: ServiceNowReadToolArgs =
                    serde_json::from_value(call.request.arguments.clone())
                        .map_err(|error| error.to_string())?;
                let connector = self
                    .service_management
                    .as_ref()
                    .ok_or_else(|| "no service-management connector is configured".to_owned())?;
                let record = connector
                    .read_record(ServiceNowReadRequest {
                        context: context(args.actor_reason, args.idempotency_key),
                        record_sys_id: args.record_sys_id,
                    })
                    .await
                    .map_err(|error| error.to_string())?;
                serde_json::to_value(record)
                    .map(Some)
                    .map_err(|error| error.to_string())
            }
            "servicenow_append_work_note" => {
                let args: ServiceNowWorkNoteToolArgs =
                    serde_json::from_value(call.request.arguments.clone())
                        .map_err(|error| error.to_string())?;
                let connector = self
                    .service_management
                    .as_ref()
                    .ok_or_else(|| "no service-management connector is configured".to_owned())?;
                let result = connector
                    .append_work_note(ServiceNowWorkNote {
                        context: context(args.actor_reason, args.idempotency_key),
                        record_sys_id: args.record_sys_id,
                        expected_mod_count: args.expected_mod_count,
                        work_note: args.work_note,
                        evidence_urls: args.evidence_urls,
                        approval_grant: args.approval_grant,
                    })
                    .await
                    .map_err(|error| error.to_string())?;
                serde_json::to_value(result)
                    .map(Some)
                    .map_err(|error| error.to_string())
            }
            "chat_notify" => {
                let args: ChatNotifyToolArgs =
                    serde_json::from_value(call.request.arguments.clone())
                        .map_err(|error| error.to_string())?;
                let connector = self
                    .chat
                    .as_ref()
                    .ok_or_else(|| "no chat connector is configured".to_owned())?;
                connector
                    .send_notification(TeamNotification {
                        context: context(args.actor_reason, args.idempotency_key),
                        channel: args.channel,
                        message: args.message,
                        evidence_urls: args.evidence_urls,
                    })
                    .await
                    .map_err(|error| error.to_string())?;
                Ok(Some(serde_json::json!({"notified":true})))
            }
            "ci_read_checks" => {
                let args: CiChecksToolArgs = serde_json::from_value(call.request.arguments.clone())
                    .map_err(|error| error.to_string())?;
                let connector = self
                    .ci
                    .as_ref()
                    .ok_or_else(|| "no CI connector is configured".to_owned())?;
                let checks = connector
                    .read_commit_checks(CommitChecksRequest {
                        context: context(args.actor_reason, args.idempotency_key),
                        commit_oid: args.commit_oid,
                    })
                    .await
                    .map_err(|error| error.to_string())?;
                serde_json::to_value(checks)
                    .map(Some)
                    .map_err(|error| error.to_string())
            }
            "siem_export" => {
                let args: SiemExportToolArgs =
                    serde_json::from_value(call.request.arguments.clone())
                        .map_err(|error| error.to_string())?;
                let connector = self
                    .security_events
                    .as_ref()
                    .ok_or_else(|| "no SIEM connector is configured".to_owned())?;
                connector
                    .export_event(SecurityEvent {
                        context: context(args.actor_reason, args.idempotency_key),
                        event_type: args.event_type,
                        severity: args.severity,
                        resource_type: args.resource_type,
                        resource_id: args.resource_id,
                        evidence_ids: args.evidence_ids,
                        occurred_at: args.occurred_at,
                    })
                    .await
                    .map_err(|error| error.to_string())?;
                Ok(Some(serde_json::json!({"exported":true})))
            }
            _ => Ok(None),
        }
    }
}

impl ConnectorToolExecutor {
    async fn publish_mcp_progress(
        &self,
        call: &s_code_protocol::ToolCall,
        progress: s_code_mcp_client::McpProgressUpdate,
    ) {
        let namespaced = call.request.tool.strip_prefix("mcp.").unwrap_or_default();
        let (server, tool) = namespaced.split_once('.').unwrap_or((namespaced, ""));
        if let Err(error) = self
            .events
            .publish(Event {
                id: Id::new("evt"),
                sequence: 0,
                timestamp: Utc::now(),
                scope: call.request.scope.clone(),
                session_id: Some(call.request.session_id.clone()),
                turn_id: Some(call.request.turn_id.clone()),
                kind: "mcp.progress".into(),
                payload: serde_json::json!({
                    "item_id": call.request.id,
                    "tool_call_id": call.request.id,
                    "server": server,
                    "tool": tool,
                    "progress": progress.progress,
                    "total": progress.total,
                    "message": progress.message,
                }),
            })
            .await
        {
            // Progress is observational. A persistence or subscriber failure must not
            // cancel an external tool that may already have performed side effects.
            tracing::warn!(
                tool_call_id = %call.request.id.0,
                ?error,
                "MCP progress could not be published"
            );
        }
    }
}

