    #[tokio::test]
    async fn ticket_write_back_requires_approval_and_is_audited_through_daemon() {
        let store = Store::in_memory().await.unwrap();
        let workspace = tempfile::tempdir().unwrap();
        let workspace_uri = url::Url::from_directory_path(workspace.path())
            .unwrap()
            .to_string();
        let scope = Scope {
            organization_id: Id("org".into()),
            team_id: Id("team".into()),
            actor_id: Id("user".into()),
            goal_id: None,
            task_id: Some(Id("task-7".into())),
        };
        let session = store
            .create_session(CreateSession {
                scope: scope.clone(),
                workspace_uri,
                title: "Ticket closure".into(),
                model: "fixture".into(),
            })
            .await
            .unwrap();
        let writes = Arc::new(StdMutex::new(Vec::new()));
        let service = app(
            AppState::new("secret", store.clone(), 0).with_work_connector(Arc::new(
                CapturingWorkConnector {
                    writes: writes.clone(),
                },
            )),
        );
        let submit = service
            .clone()
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri(format!("/v1/sessions/{}/tools", session.id.0))
                    .header(header::AUTHORIZATION, "Bearer secret")
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(
                        serde_json::to_vec(&SubmitToolCall {
                            scope: scope.clone(),
                            tool: "ticket_write_back".into(),
                            arguments: serde_json::json!({
                                "issue_number":7,
                                "expected_issue_version":"v3",
                                "message":"Draft PR verified",
                                "evidence_urls":["https://scm.example/pr/9"],
                                "actor_reason":"acceptance criteria passed",
                                "idempotency_key":"ticket-task-7-pr-9"
                            }),
                        })
                        .unwrap(),
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(submit.status(), StatusCode::CREATED);
        let pending: ToolCallOutcome =
            serde_json::from_slice(&to_bytes(submit.into_body(), 64 * 1024).await.unwrap())
                .unwrap();
        assert!(writes.lock().unwrap().is_empty());
        let approval_id = match pending {
            ToolCallOutcome::AwaitingApproval { approval, .. } => approval.id,
            _ => panic!("ticket write must await approval"),
        };
        let approved = service
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri(format!("/v1/approvals/{}", approval_id.0))
                    .header(header::AUTHORIZATION, "Bearer secret")
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(
                        serde_json::to_vec(&ResolveApproval {
                            scope: scope.clone(),
                            approved: true,
                            approval_scope: s_code_protocol::ApprovalScope::Once,
                        })
                        .unwrap(),
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(approved.status(), StatusCode::OK);
        let approved: ToolCallOutcome =
            serde_json::from_slice(&to_bytes(approved.into_body(), 64 * 1024).await.unwrap())
                .unwrap();
        assert!(
            matches!(approved, ToolCallOutcome::Completed { .. }),
            "unexpected approved outcome: {approved:?}"
        );
        {
            let writes = writes.lock().unwrap();
            assert_eq!(writes.len(), 1);
            assert_eq!(writes[0].context.scope.team_id, Id("team".into()));
            assert_eq!(writes[0].expected_issue_version, "v3");
        }
        let events = store.list_events(&scope.team_id, 0, 10).await.unwrap();
        assert!(events.iter().any(|event| event.kind == "approval.required"));
        assert!(events.iter().any(|event| event.kind == "tool.completed"));
        assert!(
            events
                .iter()
                .all(|event| !event.payload.to_string().contains("Draft PR verified"))
        );
    }

