    #[tokio::test]
    async fn team_grant_authentication_enforces_scope_role_and_local_settings_boundary() {
        let signer = s_code_identity::TeamGrantSigner::from_base64(
            "key-1",
            &URL_SAFE_NO_PAD.encode([3_u8; 32]),
        )
        .unwrap();
        let verifier = TeamGrantVerifier::from_base64(
            "key-1",
            &signer.public_key_base64(),
            "s-code-control-plane",
            "s-code-daemon",
        )
        .unwrap();
        let now = Utc::now();
        let claims = s_code_identity::TeamGrantClaims {
            grant_id: "grant-1".into(),
            issuer: "s-code-control-plane".into(),
            audience: "s-code-daemon".into(),
            subject: "oidc:alice".into(),
            organization_id: Id("org-a".into()),
            team_id: Id("team-a".into()),
            actor_id: Id("alice".into()),
            device_id: "device-a".into(),
            roles: std::collections::BTreeSet::from(["developer".into()]),
            issued_at: now,
            not_before: now,
            expires_at: now + chrono::Duration::minutes(5),
        };
        let token = signer.sign(&claims).unwrap();
        let state = AppState::new(
            "disabled-development-token",
            Store::in_memory().await.unwrap(),
            0,
        )
        .with_team_grant_auth(verifier);
        let mut headers = HeaderMap::new();
        headers.insert(
            header::AUTHORIZATION,
            format!("Bearer {token}").parse().unwrap(),
        );
        let auth = authorize(&state, &headers).unwrap();
        let allowed_scope = Scope {
            organization_id: Id("org-a".into()),
            team_id: Id("team-a".into()),
            actor_id: Id("alice".into()),
            goal_id: None,
            task_id: None,
        };
        assert!(
            auth.ensure_scope_with(&allowed_scope, Permission::ExecuteAgent)
                .is_ok()
        );
        assert!(
            auth.ensure_scope_with(&allowed_scope, Permission::ManageExtensions)
                .is_err()
        );
        assert!(auth.ensure_development().is_err());
        assert!(
            auth.ensure_scope(&Scope {
                organization_id: Id("org-a".into()),
                team_id: Id("team-b".into()),
                actor_id: Id("alice".into()),
                goal_id: None,
                task_id: None,
            })
            .is_err()
        );
        assert!(
            auth.ensure_scope(&Scope {
                organization_id: Id("org-a".into()),
                team_id: Id("team-a".into()),
                actor_id: Id("mallory".into()),
                goal_id: None,
                task_id: None,
            })
            .is_err()
        );

        let lead = AuthContext::TeamGrant(Box::new(s_code_identity::TeamGrantClaims {
            roles: BTreeSet::from(["team_lead".into()]),
            ..claims
        }));
        assert!(
            lead.ensure_scope_with(&allowed_scope, Permission::ManageExtensions)
                .is_ok()
        );

        let settings = app(state)
            .oneshot(
                Request::builder()
                    .uri("/v1/settings")
                    .header(header::AUTHORIZATION, format!("Bearer {token}"))
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(settings.status(), StatusCode::FORBIDDEN);
    }

    #[tokio::test]
    async fn team_memory_requires_manage_knowledge_and_private_memory_stays_actor_owned() {
        let signer = s_code_identity::TeamGrantSigner::from_base64(
            "memory-key",
            &URL_SAFE_NO_PAD.encode([61_u8; 32]),
        )
        .unwrap();
        let verifier = TeamGrantVerifier::from_base64(
            "memory-key",
            &signer.public_key_base64(),
            "s-code-control-plane",
            "s-code-daemon",
        )
        .unwrap();
        let now = Utc::now();
        let base_scope = Scope {
            organization_id: Id("org-memory-rbac".into()),
            team_id: Id("team-memory-rbac".into()),
            actor_id: Id("alice".into()),
            goal_id: None,
            task_id: None,
        };
        let token_for = |grant_id: &str, actor: &str, role: &str| {
            signer
                .sign(&TeamGrantClaims {
                    grant_id: grant_id.into(),
                    issuer: "s-code-control-plane".into(),
                    audience: "s-code-daemon".into(),
                    subject: format!("oidc:{actor}"),
                    organization_id: base_scope.organization_id.clone(),
                    team_id: base_scope.team_id.clone(),
                    actor_id: Id(actor.into()),
                    device_id: format!("device-{actor}"),
                    roles: BTreeSet::from([role.into()]),
                    issued_at: now,
                    not_before: now,
                    expires_at: now + chrono::Duration::minutes(5),
                })
                .unwrap()
        };
        let developer_token = token_for("memory-developer", "alice", "developer");
        let lead_token = token_for("memory-lead", "lead", "team_lead");
        let lead_scope = Scope {
            actor_id: Id("lead".into()),
            ..base_scope.clone()
        };
        let store = Store::in_memory().await.unwrap();
        let developer_session = store
            .create_session(CreateSession {
                scope: base_scope.clone(),
                workspace_uri: "file:///repo".into(),
                title: "Developer memory".into(),
                model: "model".into(),
            })
            .await
            .unwrap();
        let lead_session = store
            .create_session(CreateSession {
                scope: lead_scope.clone(),
                workspace_uri: "file:///repo".into(),
                title: "Lead memory".into(),
                model: "model".into(),
            })
            .await
            .unwrap();
        let service = app(AppState::new("disabled", store, 0).with_team_grant_auth(verifier));
        let create =
            |session_id: &Id, scope: &Scope, token: &str, memory_scope: &str, content: &str| {
                Request::builder()
                    .method("POST")
                    .uri(format!("/v1/sessions/{}/memories", session_id.0))
                    .header(header::AUTHORIZATION, format!("Bearer {token}"))
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(
                        serde_json::json!({
                            "scope": scope,
                            "memory_scope": memory_scope,
                            "content": content,
                            "citation": "Reviewed convention",
                            "expires_at": now + chrono::Duration::days(1),
                        })
                        .to_string(),
                    ))
                    .unwrap()
            };

        let denied = service
            .clone()
            .oneshot(create(
                &developer_session.id,
                &base_scope,
                &developer_token,
                "team",
                "Developer cannot publish this team memory.",
            ))
            .await
            .unwrap();
        assert_eq!(denied.status(), StatusCode::FORBIDDEN);

        let created = service
            .clone()
            .oneshot(create(
                &lead_session.id,
                &lead_scope,
                &lead_token,
                "team",
                "Lead-published team memory.",
            ))
            .await
            .unwrap();
        assert_eq!(created.status(), StatusCode::CREATED);
        let team_memory: MemoryItem =
            serde_json::from_slice(&to_bytes(created.into_body(), 64 * 1024).await.unwrap())
                .unwrap();
        let delete = |memory_id: &Id, scope: &Scope, token: &str| {
            Request::builder()
                .method("DELETE")
                .uri(format!(
                    "/v1/memories/{}?organization_id={}&team_id={}&actor_id={}",
                    memory_id.0, scope.organization_id.0, scope.team_id.0, scope.actor_id.0
                ))
                .header(header::AUTHORIZATION, format!("Bearer {token}"))
                .body(Body::empty())
                .unwrap()
        };
        let denied_delete = service
            .clone()
            .oneshot(delete(&team_memory.id, &base_scope, &developer_token))
            .await
            .unwrap();
        assert_eq!(denied_delete.status(), StatusCode::FORBIDDEN);
        let deleted = service
            .clone()
            .oneshot(delete(&team_memory.id, &lead_scope, &lead_token))
            .await
            .unwrap();
        assert_eq!(deleted.status(), StatusCode::NO_CONTENT);

        let private = service
            .clone()
            .oneshot(create(
                &developer_session.id,
                &base_scope,
                &developer_token,
                "project",
                "Alice-owned project memory.",
            ))
            .await
            .unwrap();
        assert_eq!(private.status(), StatusCode::CREATED);
        let private: MemoryItem =
            serde_json::from_slice(&to_bytes(private.into_body(), 64 * 1024).await.unwrap())
                .unwrap();
        let cross_actor_delete = service
            .oneshot(delete(&private.id, &lead_scope, &lead_token))
            .await
            .unwrap();
        assert_eq!(cross_actor_delete.status(), StatusCode::NOT_FOUND);
    }

    #[tokio::test]
    async fn team_grant_blocks_high_risk_approval_and_durable_queue_escalation() {
        let signer = s_code_identity::TeamGrantSigner::from_base64(
            "rbac-key",
            &URL_SAFE_NO_PAD.encode([53_u8; 32]),
        )
        .unwrap();
        let verifier = TeamGrantVerifier::from_base64(
            "rbac-key",
            &signer.public_key_base64(),
            "s-code-control-plane",
            "s-code-daemon",
        )
        .unwrap();
        let now = Utc::now();
        let scope = Scope {
            organization_id: Id("org-rbac".into()),
            team_id: Id("team-rbac".into()),
            actor_id: Id("alice".into()),
            goal_id: None,
            task_id: None,
        };
        let claims_for =
            |grant_id: &str, actor: &str, role: &str| s_code_identity::TeamGrantClaims {
                grant_id: grant_id.into(),
                issuer: "s-code-control-plane".into(),
                audience: "s-code-daemon".into(),
                subject: format!("oidc:{actor}"),
                organization_id: scope.organization_id.clone(),
                team_id: scope.team_id.clone(),
                actor_id: Id(actor.into()),
                device_id: format!("device-{actor}"),
                roles: BTreeSet::from([role.into()]),
                issued_at: now,
                not_before: now,
                expires_at: now + chrono::Duration::minutes(5),
            };
        let developer_token = signer
            .sign(&claims_for("grant-developer", "alice", "developer"))
            .unwrap();
        let lead_token = signer
            .sign(&claims_for("grant-lead", "lead", "team_lead"))
            .unwrap();
        let store = Store::in_memory().await.unwrap();

        let bob_scope = Scope {
            actor_id: Id("bob".into()),
            ..scope.clone()
        };
        let other_task = store
            .create_durable_task(CreateDurableTask {
                scope: bob_scope.clone(),
                kind: s_code_protocol::LINUX_RUNNER_TASK_KIND.into(),
                payload: serde_json::json!({"secret":"runner-secret-payload"}),
                idempotency_key: "other-runner-task".into(),
                max_attempts: 1,
                max_runtime_seconds: 60,
                max_cost_micros: 1_000,
                max_runner_cost_micros: 1_000,
            })
            .await
            .unwrap();

        let session = store
            .create_session(CreateSession {
                scope: scope.clone(),
                workspace_uri: "file:///repo".into(),
                title: "RBAC".into(),
                model: "model".into(),
            })
            .await
            .unwrap();
        let turn = store.create_turn(&scope, &session.id).await.unwrap();
        let high_call = store
            .create_tool_call(
                s_code_protocol::ToolRequest {
                    id: Id("tool-high-risk".into()),
                    scope: scope.clone(),
                    session_id: session.id.clone(),
                    turn_id: turn.id.clone(),
                    tool: "git_push".into(),
                    arguments: serde_json::json!({}),
                    created_at: now,
                },
                s_code_protocol::PolicyResult {
                    decision: s_code_protocol::PolicyDecision::Ask,
                    policy_id: "test".into(),
                    policy_version: "1".into(),
                    reason: "test".into(),
                    requires_approval: true,
                },
                s_code_storage::ToolPolicyMetadata::default(),
                ToolCallStatus::AwaitingApproval,
            )
            .await
            .unwrap();
        let high_approval = store.create_approval(&high_call).await.unwrap();
        let medium_call = store
            .create_tool_call(
                s_code_protocol::ToolRequest {
                    id: Id("tool-medium-risk".into()),
                    tool: "apply_patch".into(),
                    ..high_call.request.clone()
                },
                high_call.policy.clone(),
                s_code_storage::ToolPolicyMetadata::default(),
                ToolCallStatus::AwaitingApproval,
            )
            .await
            .unwrap();
        let medium_approval = store.create_approval(&medium_call).await.unwrap();
        let bob_session = store
            .create_session(CreateSession {
                scope: bob_scope.clone(),
                workspace_uri: "file:///bob-private-repository".into(),
                title: "Bob private session".into(),
                model: "model".into(),
            })
            .await
            .unwrap();
        let bob_turn = store
            .create_turn(&bob_scope, &bob_session.id)
            .await
            .unwrap();
        let bob_call = store
            .create_tool_call(
                s_code_protocol::ToolRequest {
                    id: Id("tool-bob-private".into()),
                    scope: bob_scope.clone(),
                    session_id: bob_session.id,
                    turn_id: bob_turn.id,
                    tool: "run_command".into(),
                    arguments: serde_json::json!({"command":"inspect /bob/private/path"}),
                    created_at: now,
                },
                high_call.policy.clone(),
                s_code_storage::ToolPolicyMetadata::default(),
                ToolCallStatus::AwaitingApproval,
            )
            .await
            .unwrap();
        store.create_approval(&bob_call).await.unwrap();

        let service =
            app(AppState::new("disabled-development-token", store, 0)
                .with_team_grant_auth(verifier));
        let request = |method: &str, uri: String, token: &str, body: serde_json::Value| {
            Request::builder()
                .method(method)
                .uri(uri)
                .header(header::AUTHORIZATION, format!("Bearer {token}"))
                .header(header::CONTENT_TYPE, "application/json")
                .body(Body::from(body.to_string()))
                .unwrap()
        };
        let query = "organization_id=org-rbac&team_id=team-rbac&actor_id=alice";
        let raw = service
            .clone()
            .oneshot(request(
                "GET",
                format!("/v1/durable-tasks?{query}"),
                &developer_token,
                serde_json::Value::Null,
            ))
            .await
            .unwrap();
        assert_eq!(raw.status(), StatusCode::FORBIDDEN);
        let forged = service
            .clone()
            .oneshot(request(
                "POST",
                "/v1/durable-tasks".into(),
                &developer_token,
                serde_json::json!({
                    "scope":scope.clone(),
                    "kind":s_code_protocol::LINUX_RUNNER_TASK_KIND,
                    "payload":{"command":"unreviewed"},
                    "idempotency_key":"forged-runner-task",
                    "max_attempts":1,
                    "max_runtime_seconds":60,
                    "max_cost_micros":1000,
                    "max_runner_cost_micros":1000
                }),
            ))
            .await
            .unwrap();
        assert_eq!(forged.status(), StatusCode::FORBIDDEN);
        let cancelled_other = service
            .clone()
            .oneshot(request(
                "POST",
                format!("/v1/durable-tasks/{}/cancel", other_task.id.0),
                &developer_token,
                serde_json::to_value(&scope).unwrap(),
            ))
            .await
            .unwrap();
        assert_eq!(cancelled_other.status(), StatusCode::FORBIDDEN);
        let summaries = service
            .clone()
            .oneshot(request(
                "GET",
                format!("/v1/durable-task-summaries?{query}"),
                &developer_token,
                serde_json::Value::Null,
            ))
            .await
            .unwrap();
        assert_eq!(summaries.status(), StatusCode::OK);
        let summary_body = to_bytes(summaries.into_body(), 64 * 1024).await.unwrap();
        assert!(
            !summary_body
                .windows("runner-secret-payload".len())
                .any(|window| window == b"runner-secret-payload")
        );

        let developer_approvals = service
            .clone()
            .oneshot(request(
                "GET",
                "/v1/teams/team-rbac/approvals?organization_id=org-rbac&actor_id=alice&limit=20"
                    .into(),
                &developer_token,
                serde_json::Value::Null,
            ))
            .await
            .unwrap();
        assert_eq!(developer_approvals.status(), StatusCode::OK);
        let developer_approvals = to_bytes(developer_approvals.into_body(), 64 * 1024)
            .await
            .unwrap();
        assert!(
            developer_approvals
                .windows("git_push".len())
                .any(|value| value == b"git_push")
        );
        assert!(
            !developer_approvals
                .windows("\"requested_by\":\"bob\"".len())
                .any(|value| value == b"\"requested_by\":\"bob\"")
        );
        assert!(
            !developer_approvals
                .windows("/bob/private/path".len())
                .any(|value| value == b"/bob/private/path")
        );

        let lead_approvals = service
            .clone()
            .oneshot(request(
                "GET",
                "/v1/teams/team-rbac/approvals?organization_id=org-rbac&actor_id=lead&limit=20"
                    .into(),
                &lead_token,
                serde_json::Value::Null,
            ))
            .await
            .unwrap();
        assert_eq!(lead_approvals.status(), StatusCode::OK);
        let lead_approvals = to_bytes(lead_approvals.into_body(), 64 * 1024)
            .await
            .unwrap();
        assert!(
            lead_approvals
                .windows("\"requested_by\":\"bob\"".len())
                .any(|value| value == b"\"requested_by\":\"bob\"")
        );

        let cross_organization = service
            .clone()
            .oneshot(request(
                "GET",
                "/v1/teams/team-rbac/approvals?organization_id=org-foreign&actor_id=lead&limit=20"
                    .into(),
                &lead_token,
                serde_json::Value::Null,
            ))
            .await
            .unwrap();
        assert_eq!(cross_organization.status(), StatusCode::FORBIDDEN);

        let high_denied = service
            .clone()
            .oneshot(request(
                "POST",
                format!("/v1/approvals/{}", high_approval.id.0),
                &developer_token,
                serde_json::json!({"scope":scope.clone(),"approved":false,"approval_scope":"once"}),
            ))
            .await
            .unwrap();
        assert_eq!(high_denied.status(), StatusCode::FORBIDDEN);
        let medium_allowed = service
            .clone()
            .oneshot(request(
                "POST",
                format!("/v1/approvals/{}", medium_approval.id.0),
                &developer_token,
                serde_json::json!({"scope":scope.clone(),"approved":false,"approval_scope":"once"}),
            ))
            .await
            .unwrap();
        assert_eq!(medium_allowed.status(), StatusCode::OK);
        let lead_scope = Scope {
            actor_id: Id("lead".into()),
            ..scope
        };
        let high_allowed = service
            .oneshot(request(
                "POST",
                format!("/v1/approvals/{}", high_approval.id.0),
                &lead_token,
                serde_json::json!({"scope":lead_scope,"approved":false,"approval_scope":"once"}),
            ))
            .await
            .unwrap();
        assert_eq!(high_allowed.status(), StatusCode::OK);
    }

    #[tokio::test]
    async fn remote_presence_is_content_free_realtime_and_grant_revocation_survives_restart() {
        let signer = s_code_identity::TeamGrantSigner::from_base64(
            "presence-key",
            &URL_SAFE_NO_PAD.encode([41_u8; 32]),
        )
        .unwrap();
        let verifier = TeamGrantVerifier::from_base64(
            "presence-key",
            &signer.public_key_base64(),
            "s-code-control-plane",
            "s-code-daemon",
        )
        .unwrap();
        let now = Utc::now();
        let scope = Scope {
            organization_id: Id("org-presence".into()),
            team_id: Id("team-presence".into()),
            actor_id: Id("alice".into()),
            goal_id: None,
            task_id: None,
        };
        let claims = s_code_identity::TeamGrantClaims {
            grant_id: "grant-presence".into(),
            issuer: "s-code-control-plane".into(),
            audience: "s-code-daemon".into(),
            subject: "oidc:alice".into(),
            organization_id: scope.organization_id.clone(),
            team_id: scope.team_id.clone(),
            actor_id: scope.actor_id.clone(),
            device_id: "device-presence".into(),
            roles: BTreeSet::from(["developer".into()]),
            issued_at: now,
            not_before: now,
            expires_at: now + chrono::Duration::minutes(5),
        };
        let token = signer.sign(&claims).unwrap();
        let token_for = |grant_id: &str, actor: &str, role: &str| {
            let mut scoped = claims.clone();
            scoped.grant_id = grant_id.into();
            scoped.subject = format!("oidc:{actor}");
            scoped.actor_id = Id(actor.into());
            scoped.device_id = format!("device-{actor}-{role}");
            scoped.roles = BTreeSet::from([role.into()]);
            signer.sign(&scoped).unwrap()
        };
        let bob_token = token_for("grant-presence-bob", "bob", "developer");
        let agent_token = token_for("grant-presence-agent", "alice", "agent");
        let auditor_token = token_for("grant-presence-auditor", "alice", "auditor");
        let store = Store::in_memory().await.unwrap();
        let service =
            app(AppState::new("disabled", store.clone(), 0).with_team_grant_auth(verifier.clone()));
        let presence = UpdateClientPresence {
            scope: scope.clone(),
            client_id: "web:presence-test".into(),
            client_kind: ClientKind::Web,
            session_id: None,
            focused: true,
        };
        let heartbeat = service
            .clone()
            .oneshot(
                Request::builder()
                    .method("PUT")
                    .uri("/v1/client-presence")
                    .header(header::AUTHORIZATION, format!("Bearer {token}"))
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(serde_json::to_vec(&presence).unwrap()))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(heartbeat.status(), StatusCode::OK);
        let clients: Vec<ClientPresence> =
            serde_json::from_slice(&to_bytes(heartbeat.into_body(), 64 * 1024).await.unwrap())
                .unwrap();
        assert_eq!(clients.len(), 1);
        assert_eq!(clients[0].device_id.as_deref(), Some("device-presence"));
        assert!(clients[0].remote && clients[0].revocable);

        let bob_scope = Scope {
            actor_id: Id("bob".into()),
            ..scope.clone()
        };
        let bob_presence = UpdateClientPresence {
            scope: bob_scope,
            client_id: "web:presence-bob".into(),
            client_kind: ClientKind::Web,
            session_id: None,
            focused: true,
        };
        let bob_heartbeat = service
            .clone()
            .oneshot(
                Request::builder()
                    .method("PUT")
                    .uri("/v1/client-presence")
                    .header(header::AUTHORIZATION, format!("Bearer {bob_token}"))
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(serde_json::to_vec(&bob_presence).unwrap()))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(bob_heartbeat.status(), StatusCode::OK);

        let agent_presence = UpdateClientPresence {
            scope: scope.clone(),
            client_id: "cli:presence-agent".into(),
            client_kind: ClientKind::Cli,
            session_id: None,
            focused: true,
        };
        let agent_heartbeat = service
            .clone()
            .oneshot(
                Request::builder()
                    .method("PUT")
                    .uri("/v1/client-presence")
                    .header(header::AUTHORIZATION, format!("Bearer {agent_token}"))
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(serde_json::to_vec(&agent_presence).unwrap()))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(agent_heartbeat.status(), StatusCode::OK);
        let agent_visible: Vec<ClientPresence> = serde_json::from_slice(
            &to_bytes(agent_heartbeat.into_body(), 64 * 1024)
                .await
                .unwrap(),
        )
        .unwrap();
        assert!(
            agent_visible
                .iter()
                .all(|presence| presence.actor_id == scope.actor_id)
        );
        assert!(
            agent_visible
                .iter()
                .all(|presence| presence.actor_id.0 != "bob")
        );

        let agent_list = service
            .clone()
            .oneshot(
                Request::builder()
                    .uri("/v1/client-presence?organization_id=org-presence&team_id=team-presence&actor_id=alice")
                    .header(header::AUTHORIZATION, format!("Bearer {agent_token}"))
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(agent_list.status(), StatusCode::FORBIDDEN);

        let auditor_list = service
            .clone()
            .oneshot(
                Request::builder()
                    .uri("/v1/client-presence?organization_id=org-presence&team_id=team-presence&actor_id=alice")
                    .header(header::AUTHORIZATION, format!("Bearer {auditor_token}"))
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(auditor_list.status(), StatusCode::OK);
        let auditor_visible: Vec<ClientPresence> =
            serde_json::from_slice(&to_bytes(auditor_list.into_body(), 64 * 1024).await.unwrap())
                .unwrap();
        assert!(
            auditor_visible
                .iter()
                .any(|presence| presence.actor_id.0 == "bob")
        );
        let event = store
            .list_team_events(&scope, 0, 10)
            .await
            .unwrap()
            .into_iter()
            .find(|event| event.kind == "client.presence.updated")
            .unwrap();
        let serialized = serde_json::to_string(&event).unwrap();
        assert!(!serialized.contains("Bearer"));
        assert!(!serialized.contains(&token));
        let audit_denied = service
            .clone()
            .oneshot(
                Request::builder()
                    .uri(
                        "/v1/teams/team-presence/audit?organization_id=org-presence&actor_id=alice",
                    )
                    .header(header::AUTHORIZATION, format!("Bearer {token}"))
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(audit_denied.status(), StatusCode::FORBIDDEN);

        let revoked = service
            .clone()
            .oneshot(
                Request::builder()
                    .method("DELETE")
                    .uri("/v1/client-presence/web:presence-test")
                    .header(header::AUTHORIZATION, format!("Bearer {token}"))
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(
                        serde_json::to_vec(&RemoveClientPresence {
                            scope: scope.clone(),
                            revoke_remote_grant: true,
                        })
                        .unwrap(),
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(revoked.status(), StatusCode::OK);
        let rejected = service
            .oneshot(
                Request::builder()
                    .uri("/v1/client-presence?organization_id=org-presence&team_id=team-presence&actor_id=alice")
                    .header(header::AUTHORIZATION, format!("Bearer {token}"))
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(rejected.status(), StatusCode::UNAUTHORIZED);

        let persisted = store
            .active_remote_grant_revocations(Utc::now())
            .await
            .unwrap();
        assert_eq!(persisted, ["grant-presence"]);
        let restarted = app(AppState::new("disabled", store, 0)
            .with_team_grant_auth(verifier)
            .with_revoked_team_grants(persisted));
        let rejected_after_restart = restarted
            .oneshot(
                Request::builder()
                    .uri("/v1/client-presence?organization_id=org-presence&team_id=team-presence&actor_id=alice")
                    .header(header::AUTHORIZATION, format!("Bearer {token}"))
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(rejected_after_restart.status(), StatusCode::UNAUTHORIZED);
    }

    #[tokio::test]
    async fn runner_credential_is_restricted_to_worker_endpoints() {
        let store = Store::in_memory().await.unwrap();
        let service =
            app(AppState::new("user-secret", store, 0).with_runner_token("runner-secret"));
        let request = |method: &str, uri: &str, token: &str, body: &str| {
            Request::builder()
                .method(method)
                .uri(uri)
                .header(header::AUTHORIZATION, format!("Bearer {token}"))
                .header(header::CONTENT_TYPE, "application/json")
                .body(Body::from(body.to_owned()))
                .unwrap()
        };
        let user_on_runner = service
            .clone()
            .oneshot(request(
                "POST",
                "/v1/durable-tasks/lease",
                "user-secret",
                r#"{"worker":"runner-1","lease_seconds":30,"kind":"runner.process.v1"}"#,
            ))
            .await
            .unwrap();
        assert_eq!(user_on_runner.status(), StatusCode::UNAUTHORIZED);

        let runner_on_user = service
            .clone()
            .oneshot(request(
                "GET",
                "/v1/sessions?organization_id=org&team_id=team&actor_id=user",
                "runner-secret",
                "",
            ))
            .await
            .unwrap();
        assert_eq!(runner_on_user.status(), StatusCode::UNAUTHORIZED);

        let runner_on_runner = service
            .oneshot(request(
                "POST",
                "/v1/durable-tasks/lease",
                "runner-secret",
                r#"{"worker":"runner-1","lease_seconds":30,"kind":"runner.process.v1"}"#,
            ))
            .await
            .unwrap();
        assert_eq!(runner_on_runner.status(), StatusCode::NO_CONTENT);
    }

    #[tokio::test]
    async fn undo_api_is_team_scoped_restores_file_and_emits_content_free_audit() {
        let workspace = tempfile::tempdir().unwrap();
        let file = workspace.path().join("changed.txt");
        std::fs::write(&file, "before").unwrap();
        let scope = Scope {
            organization_id: Id("org".into()),
            team_id: Id("team".into()),
            actor_id: Id("user".into()),
            goal_id: None,
            task_id: None,
        };
        let store = Store::in_memory().await.unwrap();
        let session = store
            .create_session(CreateSession {
                scope: scope.clone(),
                workspace_uri: url::Url::from_directory_path(workspace.path())
                    .unwrap()
                    .to_string(),
                title: "Undo".into(),
                model: "mock".into(),
            })
            .await
            .unwrap();
        let turn = store.create_turn(&scope, &session.id).await.unwrap();
        let before_hash = s_code_tool_runtime::content_sha256(b"before");
        let after_hash = s_code_tool_runtime::content_sha256(b"after");
        let plan = store
            .plan_turn_file_change(
                &scope,
                &turn.id,
                "changed.txt",
                Some(b"before"),
                Some(&before_hash),
                &after_hash,
            )
            .await
            .unwrap();
        std::fs::write(&file, "after").unwrap();
        store.complete_turn_file_change(&plan).await.unwrap();
        store
            .append_turn_message(
                &scope,
                &session.id,
                &turn.id,
                "user",
                serde_json::json!("change the file"),
            )
            .await
            .unwrap();
        store
            .append_turn_message(
                &scope,
                &session.id,
                &turn.id,
                "assistant",
                serde_json::json!("done"),
            )
            .await
            .unwrap();
        store
            .update_turn(&scope, &turn.id, TurnStatus::PreparingContext, None, None)
            .await
            .unwrap();
        store
            .update_turn(&scope, &turn.id, TurnStatus::CallingModel, None, None)
            .await
            .unwrap();
        store
            .update_turn(&scope, &turn.id, TurnStatus::Completed, None, None)
            .await
            .unwrap();
        let service = app(AppState::new("secret", store.clone(), 0));
        let preview = service
            .clone()
            .oneshot(
                Request::builder()
                    .uri(format!(
                        "/v1/turns/{}/undo-impact?organization_id=org&team_id=team&actor_id=user",
                        turn.id.0
                    ))
                    .header(header::AUTHORIZATION, "Bearer secret")
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(preview.status(), StatusCode::OK);
        let preview: TurnUndoImpactPreview =
            serde_json::from_slice(&to_bytes(preview.into_body(), 64 * 1024).await.unwrap())
                .unwrap();
        assert_eq!(preview.turn_id, turn.id);
        assert_eq!(
            preview.paths,
            vec![UndoPathImpact {
                path: "changed.txt".into(),
                action: UndoPathAction::Restore,
            }]
        );
        assert_eq!(preview.conversation_messages, 2);
        assert!(preview.latest_conversation_turn);
        assert!(preview.protects_later_human_edits);
        let request = Request::builder()
            .method("POST")
            .uri(format!("/v1/turns/{}/undo", turn.id.0))
            .header(header::AUTHORIZATION, "Bearer secret")
            .header(header::CONTENT_TYPE, "application/json")
            .body(Body::from(
                serde_json::to_vec(&serde_json::json!({"scope":scope})).unwrap(),
            ))
            .unwrap();
        let response = service.oneshot(request).await.unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        assert_eq!(std::fs::read_to_string(file).unwrap(), "before");
        let events = store.list_events(&Id("team".into()), 0, 10).await.unwrap();
        let event = events
            .iter()
            .find(|event| event.kind == "turn.files.undone")
            .unwrap();
        assert_eq!(event.session_id, Some(session.id.clone()));
        assert!(event.payload.to_string().contains("changed.txt"));
        assert_eq!(event.payload["conversation_omitted_messages"], 2);
        assert!(!event.payload.to_string().contains("before"));
        assert!(!event.payload.to_string().contains("after"));
        let history = store.list_messages(&scope, &session.id).await.unwrap();
        assert!(
            history
                .iter()
                .any(|message| message.role == "conversation_undo_state")
        );
        assert!(durable_conversation(&history).unwrap().is_empty());
    }

    #[tokio::test]
    async fn daemon_compacts_full_history_before_model_request() {
        let workspace = tempfile::tempdir().unwrap();
        let scope = Scope {
            organization_id: Id("org".into()),
            team_id: Id("team".into()),
            actor_id: Id("user".into()),
            goal_id: None,
            task_id: None,
        };
        let store = Store::in_memory().await.unwrap();
        let session = store
            .create_session(CreateSession {
                scope: scope.clone(),
                workspace_uri: url::Url::from_directory_path(workspace.path())
                    .unwrap()
                    .to_string(),
                title: "Long history".into(),
                model: "mock".into(),
            })
            .await
            .unwrap();
        for index in 0..70 {
            store
                .append_message(
                    &scope,
                    &session.id,
                    if index % 2 == 0 { "user" } else { "assistant" },
                    serde_json::json!(format!("history-marker-{index} {}", "x".repeat(4_000))),
                )
                .await
                .unwrap();
        }
        let turn = store.create_turn(&scope, &session.id).await.unwrap();
        let captured = Arc::new(StdMutex::new(None));
        let provider = Arc::new(CapturingProvider {
            request: captured.clone(),
        });
        run_turn(
            AppState::new("secret", store.clone(), 0),
            provider,
            turn.clone(),
            CancellationToken::new(),
            ToolProfile::Default,
        )
        .await
        .unwrap();

        let request = captured.lock().unwrap().clone().unwrap();
        assert!(request.messages.len() < 70);
        let encoded = serde_json::to_string(&request.messages).unwrap();
        assert!(encoded.contains("internal://conversation-compaction"));
        assert!(encoded.contains("history-marker-0"));
        assert!(encoded.contains("history-marker-69"));
        let estimated_tokens: usize = request
            .messages
            .iter()
            .map(|message| {
                s_code_context_engine::estimate_tokens(&message.role)
                    + s_code_context_engine::estimate_tokens(&message.content.to_string())
                    + 4
            })
            .sum();
        assert!(estimated_tokens <= 58_000, "estimated {estimated_tokens}");
        let events = store.list_events(&scope.team_id, 0, 500).await.unwrap();
        let compacted = events
            .iter()
            .find(|event| event.kind == "context.compacted")
            .expect("compaction is a durable transcript event");
        assert_eq!(compacted.session_id.as_ref(), Some(&session.id));
        assert_eq!(compacted.turn_id.as_ref(), Some(&turn.id));
        assert!(compacted.payload["omitted_messages"].as_u64().unwrap() > 0);
        assert!(matches!(
            project_client_event(compacted).notification,
            Some(ClientNotification::ContextCompacted { .. })
        ));
        let items = transcript_metadata_items(&events).unwrap();
        assert!(items.iter().any(|item| {
            item.kind == TranscriptItemKind::ContextCompaction
                && matches!(
                    &item.content,
                    TranscriptItemContent::ContextCompaction { .. }
                )
        }));
    }

    #[tokio::test]
    async fn scoped_memory_and_explicit_compaction_are_bounded_and_content_safe() {
        let workspace = tempfile::tempdir().unwrap();
        let other_workspace = tempfile::tempdir().unwrap();
        let scope = Scope {
            organization_id: Id("org".into()),
            team_id: Id("team".into()),
            actor_id: Id("user".into()),
            goal_id: None,
            task_id: None,
        };
        let store = Store::in_memory().await.unwrap();
        let session = store
            .create_session(CreateSession {
                scope: scope.clone(),
                workspace_uri: url::Url::from_directory_path(workspace.path())
                    .unwrap()
                    .to_string(),
                title: "Memory".into(),
                model: "mock".into(),
            })
            .await
            .unwrap();
        let other = store
            .create_session(CreateSession {
                scope: scope.clone(),
                workspace_uri: url::Url::from_directory_path(other_workspace.path())
                    .unwrap()
                    .to_string(),
                title: "Other".into(),
                model: "mock".into(),
            })
            .await
            .unwrap();
        let turn = store.create_turn(&scope, &session.id).await.unwrap();
        for index in 0..40 {
            store
                .append_turn_message(
                    &scope,
                    &session.id,
                    &turn.id,
                    if index % 2 == 0 { "user" } else { "assistant" },
                    serde_json::json!(format!("history-{index} {}", "x".repeat(2_000))),
                )
                .await
                .unwrap();
        }
        for status in [
            TurnStatus::PreparingContext,
            TurnStatus::CallingModel,
            TurnStatus::Completed,
        ] {
            store
                .update_turn(&scope, &turn.id, status, None, None)
                .await
                .unwrap();
        }
        let service = app(AppState::new("secret", store.clone(), 0));
        let create_memory = |content: &str| {
            Request::builder()
                .method("POST")
                .uri(format!("/v1/sessions/{}/memories", session.id.0))
                .header("authorization", "Bearer secret")
                .header("content-type", "application/json")
                .body(Body::from(
                    serde_json::json!({
                        "scope": scope.clone(),
                        "memory_scope": "project",
                        "content": content,
                        "citation": "Project test convention",
                        "expires_at": "2027-07-27T00:00:00Z"
                    })
                    .to_string(),
                ))
                .unwrap()
        };
        let created = service
            .clone()
            .oneshot(create_memory("Use the repository test scripts."))
            .await
            .unwrap();
        assert_eq!(created.status(), StatusCode::CREATED);
        let memory: MemoryItem =
            serde_json::from_slice(&to_bytes(created.into_body(), 64 * 1024).await.unwrap())
                .unwrap();
        assert_eq!(memory.memory_scope, MemoryScope::Project);
        assert!(memory.source_uri.starts_with("memory://project/"));

        let rejected = service
            .clone()
            .oneshot(create_memory("OPENROUTER_API_KEY=sk-secret-value"))
            .await
            .unwrap();
        assert_eq!(rejected.status(), StatusCode::BAD_REQUEST);

        let list = |session_id: &Id| {
            Request::builder()
                .uri(format!(
                    "/v1/sessions/{}/memories?organization_id=org&team_id=team&actor_id=user",
                    session_id.0
                ))
                .header("authorization", "Bearer secret")
                .body(Body::empty())
                .unwrap()
        };
        let visible = service.clone().oneshot(list(&session.id)).await.unwrap();
        let visible: Vec<MemoryItem> =
            serde_json::from_slice(&to_bytes(visible.into_body(), 64 * 1024).await.unwrap())
                .unwrap();
        assert_eq!(visible.len(), 1);
        let hidden = service.clone().oneshot(list(&other.id)).await.unwrap();
        let hidden: Vec<MemoryItem> =
            serde_json::from_slice(&to_bytes(hidden.into_body(), 64 * 1024).await.unwrap())
                .unwrap();
        assert!(hidden.is_empty());

        let context = service
            .clone()
            .oneshot(
                Request::builder()
                    .uri(format!(
                        "/v1/sessions/{}/context?organization_id=org&team_id=team&actor_id=user",
                        session.id.0
                    ))
                    .header("authorization", "Bearer secret")
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        let context: ContextSummary =
            serde_json::from_slice(&to_bytes(context.into_body(), 64 * 1024).await.unwrap())
                .unwrap();
        assert!(
            context
                .items
                .iter()
                .any(|item| item.source_uri == memory.source_uri)
        );
        assert!(
            !serde_json::to_string(&context)
                .unwrap()
                .contains("test scripts")
        );

        let rejected_compaction = service
            .clone()
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri(format!("/v1/sessions/{}/compact", session.id.0))
                    .header("authorization", "Bearer secret")
                    .header("content-type", "application/json")
                    .body(Body::from(
                        serde_json::json!({
                            "scope": scope.clone(),
                            "focus": "OPENROUTER_API_KEY=sk-secret-value"
                        })
                        .to_string(),
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(rejected_compaction.status(), StatusCode::BAD_REQUEST);
        assert!(
            store
                .list_messages(&scope, &session.id)
                .await
                .unwrap()
                .iter()
                .all(|message| message.role != "context_compaction_state")
        );

        let compacted = service
            .clone()
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri(format!("/v1/sessions/{}/compact", session.id.0))
                    .header("authorization", "Bearer secret")
                    .header("content-type", "application/json")
                    .body(Body::from(
                        serde_json::json!({
                            "scope": scope.clone(),
                            "focus": "Keep the test evidence and final decisions."
                        })
                        .to_string(),
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(compacted.status(), StatusCode::OK);
        let compacted: CompactSessionResult =
            serde_json::from_slice(&to_bytes(compacted.into_body(), 64 * 1024).await.unwrap())
                .unwrap();
        assert!(compacted.before_tokens > compacted.after_tokens);
        assert!(compacted.omitted_messages > 0);
        assert!(compacted.focus_applied);
        let durable_history = store.list_messages(&scope, &session.id).await.unwrap();
        let marker = durable_history
            .iter()
            .find(|message| message.role == "context_compaction_state")
            .expect("successful compaction should persist its checkpoint");
        let checkpoint: DurableContextCompaction =
            serde_json::from_value(marker.content.clone()).unwrap();
        assert_eq!(checkpoint.schema_version, CONTEXT_COMPACTION_SCHEMA_VERSION);
        assert!(!checkpoint.omitted_message_ids.is_empty());
        let resumed_context = durable_conversation(&durable_history).unwrap();
        assert!(resumed_context[0].id.starts_with("compaction:"));
        assert_eq!(resumed_context[0].content["trust"], "derived-untrusted");
        assert!(
            resumed_context.len()
                < durable_history
                    .iter()
                    .filter(|message| is_model_message_role(&message.role))
                    .count()
        );
        let events = store.list_events(&scope.team_id, 0, 100).await.unwrap();
        let event = events
            .iter()
            .find(|event| event.kind == "context.compacted")
            .unwrap();
        assert!(!event.payload.to_string().contains("test evidence"));
        assert_eq!(event.payload["focus_applied"], true);

        let deleted = service
            .clone()
            .oneshot(
                Request::builder()
                    .method("DELETE")
                    .uri(format!(
                        "/v1/memories/{}?organization_id=org&team_id=team&actor_id=user",
                        memory.id.0
                    ))
                    .header("authorization", "Bearer secret")
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(deleted.status(), StatusCode::NO_CONTENT);
        let remaining = service.oneshot(list(&session.id)).await.unwrap();
        let remaining: Vec<MemoryItem> =
            serde_json::from_slice(&to_bytes(remaining.into_body(), 64 * 1024).await.unwrap())
                .unwrap();
        assert_eq!(remaining.len(), 1);
        assert!(remaining[0].citation.starts_with("Compaction focus"));
    }

    #[tokio::test]
    async fn capability_contracts_are_advertised_independent_of_availability() {
        let store = Store::in_memory().await.unwrap();
        let response = app(AppState::new("secret", store, 0))
            .oneshot(
                Request::builder()
                    .uri("/v1/capabilities")
                    .header(header::AUTHORIZATION, "Bearer secret")
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        let manifest: CapabilityManifest =
            serde_json::from_slice(&to_bytes(response.into_body(), usize::MAX).await.unwrap())
                .unwrap();
        for contract in &manifest.contracts {
            let capability = manifest
                .capabilities
                .iter()
                .find(|item| item.id == contract.capability_id)
                .unwrap();
            assert_eq!(
                capability.enabled,
                matches!(
                    contract.capability_id.as_str(),
                    "session.realtime_multiuser" | "task.durable"
                )
            );
            assert_eq!(capability.version, contract.version);
        }
        assert_eq!(manifest.contracts.len(), 8);
    }

    #[tokio::test]
    async fn durable_task_api_supports_lease_checkpoint_and_completion() {
        let store = Store::in_memory().await.unwrap();
        let service = app(AppState::new("secret", store, 0));
        let authorized = |method: &str, uri: &str, body: serde_json::Value| {
            Request::builder()
                .method(method)
                .uri(uri)
                .header(header::AUTHORIZATION, "Bearer secret")
                .header(header::CONTENT_TYPE, "application/json")
                .body(Body::from(body.to_string()))
                .unwrap()
        };
        let scope = serde_json::json!({
            "organization_id":"org","team_id":"team","actor_id":"user",
            "goal_id":null,"task_id":null
        });
        let created = service
            .clone()
            .oneshot(authorized(
                "POST",
                "/v1/durable-tasks",
                serde_json::json!({"scope":scope,"kind":"agent.turn","payload":{"prompt":"work"},"idempotency_key":"api-1","max_attempts":2,"max_runtime_seconds":60,"max_cost_micros":1000,"max_runner_cost_micros":500}),
            ))
            .await
            .unwrap();
        assert_eq!(created.status(), StatusCode::ACCEPTED);
        let created: DurableTask =
            serde_json::from_slice(&to_bytes(created.into_body(), usize::MAX).await.unwrap())
                .unwrap();
        let leased = service
            .clone()
            .oneshot(authorized(
                "POST",
                "/v1/durable-tasks/lease",
                serde_json::json!({"worker":"runner-1","lease_seconds":30}),
            ))
            .await
            .unwrap();
        let leased: DurableTask =
            serde_json::from_slice(&to_bytes(leased.into_body(), usize::MAX).await.unwrap())
                .unwrap();
        assert_eq!(leased.id, created.id);
        let token = leased.lease_token.unwrap();
        let renewed = service
            .clone()
            .oneshot(authorized(
                "POST",
                &format!("/v1/durable-tasks/{}/renew", created.id.0),
                serde_json::json!({"lease_token":token.clone(),"lease_seconds":60}),
            ))
            .await
            .unwrap();
        assert_eq!(renewed.status(), StatusCode::OK);
        let checkpointed = service
            .clone()
            .oneshot(authorized(
                "POST",
                &format!("/v1/durable-tasks/{}/checkpoint", created.id.0),
                serde_json::json!({"lease_token":token.clone(),"checkpoint":{"step":1},"consumed_cost_micros":100,"consumed_runner_cost_micros":50}),
            ))
            .await
            .unwrap();
        assert_eq!(checkpointed.status(), StatusCode::OK);
        let completed = service
            .oneshot(authorized(
                "POST",
                &format!("/v1/durable-tasks/{}/complete", created.id.0),
                serde_json::json!({"lease_token":token,"result":{"ok":true},"consumed_cost_micros":200,"consumed_runner_cost_micros":80}),
            ))
            .await
            .unwrap();
        let completed: DurableTask =
            serde_json::from_slice(&to_bytes(completed.into_body(), usize::MAX).await.unwrap())
                .unwrap();
        assert_eq!(completed.status, DurableTaskStatus::Succeeded);
        assert_eq!(completed.consumed_runner_cost_micros, 80);
    }

