    #[tokio::test]
    async fn browser_requests_enforce_origin_csrf_and_csp() {
        let store = Store::in_memory().await.unwrap();
        let service = app(AppState::new("secret", store, 0));
        let index = service
            .clone()
            .oneshot(Request::builder().uri("/").body(Body::empty()).unwrap())
            .await
            .unwrap();
        assert_eq!(index.status(), StatusCode::OK);
        assert!(
            index
                .headers()
                .contains_key(header::CONTENT_SECURITY_POLICY)
        );
        assert_eq!(index.headers()[header::CACHE_CONTROL], "no-store");
        assert_eq!(index.headers()[header::REFERRER_POLICY], "no-referrer");
        assert_eq!(index.headers()[header::X_FRAME_OPTIONS], "DENY");
        assert_eq!(index.headers()["cross-origin-opener-policy"], "same-origin");
        assert!(index.headers().contains_key("permissions-policy"));
        let html = String::from_utf8(
            to_bytes(index.into_body(), 1024 * 1024)
                .await
                .unwrap()
                .to_vec(),
        )
        .unwrap();
        let marker = r#"<meta name="s-code-bootstrap" content=""#;
        let bootstrap_start = html.find(marker).unwrap() + marker.len();
        let bootstrap_end = html[bootstrap_start..].find('"').unwrap() + bootstrap_start;
        assert!(html[bootstrap_start..bootstrap_end].is_empty());
        assert!(!html.contains("Bearer secret"));

        let unauthenticated_issue = service
            .clone()
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri("/v1/auth/browser-bootstrap")
                    .header("x-s-code-csrf", "1")
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(unauthenticated_issue.status(), StatusCode::UNAUTHORIZED);

        let issued = service
            .clone()
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri("/v1/auth/browser-bootstrap")
                    .header(header::AUTHORIZATION, "Bearer secret")
                    .header("x-s-code-csrf", "1")
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(issued.status(), StatusCode::OK);
        let issued: serde_json::Value =
            serde_json::from_slice(&to_bytes(issued.into_body(), 1024).await.unwrap()).unwrap();
        let bootstrap = issued["token"].as_str().unwrap();
        assert!(!bootstrap.is_empty());

        let exchanged = service
            .clone()
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri("/v1/auth/bootstrap")
                    .header(header::HOST, "127.0.0.1:3000")
                    .header(header::ORIGIN, "http://127.0.0.1:3000")
                    .header("x-s-code-csrf", "1")
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(
                        serde_json::json!({"token":bootstrap}).to_string(),
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(exchanged.status(), StatusCode::NO_CONTENT);
        let cookie = exchanged.headers()[header::SET_COOKIE]
            .to_str()
            .unwrap()
            .to_owned();
        assert!(cookie.contains("HttpOnly"));
        assert!(cookie.contains("SameSite=Strict"));
        assert!(!cookie.contains("secret"));
        let cookie_value = cookie.split(';').next().unwrap();
        let cookie_authorized = service
            .clone()
            .oneshot(
                Request::builder()
                    .uri("/v1/capabilities")
                    .header(header::COOKIE, cookie_value)
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(cookie_authorized.status(), StatusCode::OK);
        let replayed = service
            .clone()
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri("/v1/auth/bootstrap")
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(
                        serde_json::json!({"token":bootstrap}).to_string(),
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(replayed.status(), StatusCode::UNAUTHORIZED);
        let bad_origin = service
            .clone()
            .oneshot(
                Request::builder()
                    .uri("/v1/capabilities")
                    .header(header::HOST, "127.0.0.1:3000")
                    .header(header::ORIGIN, "http://evil.example")
                    .header(header::AUTHORIZATION, "Bearer secret")
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(bad_origin.status(), StatusCode::FORBIDDEN);
        let missing_csrf = service
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri("/v1/sessions")
                    .header(header::HOST, "127.0.0.1:3000")
                    .header(header::ORIGIN, "http://127.0.0.1:3000")
                    .header(header::AUTHORIZATION, "Bearer secret")
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from("{}"))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(missing_csrf.status(), StatusCode::FORBIDDEN);
    }

    #[tokio::test]
    async fn sse_reconnect_replays_only_events_after_the_acknowledged_sequence() {
        let store = Store::in_memory().await.unwrap();
        let state = AppState::new("secret", store, 0);
        let scope = Scope {
            organization_id: Id("org".into()),
            team_id: Id("team".into()),
            actor_id: Id("user".into()),
            goal_id: None,
            task_id: None,
        };
        for kind in ["turn.first", "turn.second"] {
            state
                .publish(Event {
                    id: Id::new("evt"),
                    sequence: 0,
                    timestamp: Utc::now(),
                    scope: scope.clone(),
                    session_id: Some(Id("session".into())),
                    turn_id: Some(Id("turn".into())),
                    kind: kind.into(),
                    payload: serde_json::json!({"status":"persisted"}),
                })
                .await
                .unwrap();
        }
        let response = app(state)
            .oneshot(
                Request::builder()
                    .uri("/v1/events?organization_id=org&team_id=team&actor_id=user&after=1")
                    .header(header::AUTHORIZATION, "Bearer secret")
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        let mut stream = response.into_body().into_data_stream();
        let frame = tokio::time::timeout(std::time::Duration::from_secs(1), stream.next())
            .await
            .unwrap()
            .unwrap()
            .unwrap();
        let encoded = String::from_utf8(frame.to_vec()).unwrap();
        assert!(encoded.contains("id: 2"));
        assert!(encoded.contains("event: turn.second"));
        assert!(!encoded.contains("turn.first"));
    }

    #[tokio::test]
    async fn event_replay_stream_crosses_large_private_gaps_in_fixed_pages() {
        let store = Store::in_memory().await.unwrap();
        let state = AppState::new("secret", store, 0);
        let alice = Scope {
            organization_id: Id("org".into()),
            team_id: Id("team".into()),
            actor_id: Id("alice".into()),
            goal_id: None,
            task_id: None,
        };
        let bob = Scope {
            actor_id: Id("bob".into()),
            ..alice.clone()
        };
        for index in 0..305 {
            let visible = index == 99 || index == 304;
            state
                .publish(Event {
                    id: Id::new("evt"),
                    sequence: 0,
                    timestamp: Utc::now(),
                    scope: if visible { alice.clone() } else { bob.clone() },
                    session_id: None,
                    turn_id: None,
                    kind: if visible {
                        format!("alice.visible.{index}")
                    } else {
                        format!("bob.private.{index}")
                    },
                    payload: serde_json::json!({"index":index}),
                })
                .await
                .unwrap();
        }
        let watermark = state
            .store
            .latest_team_event_sequence(&alice)
            .await
            .unwrap();
        let mut replay = Box::pin(replay_event_stream(
            state,
            alice,
            0,
            watermark,
            EventVisibility {
                private_execution: true,
                team_dashboard: false,
                team_approver: false,
            },
        ));
        let first = replay.next().await.unwrap().unwrap();
        let second = replay.next().await.unwrap().unwrap();
        assert_eq!(first.kind, "alice.visible.99");
        assert_eq!(second.kind, "alice.visible.304");
        assert!(replay.next().await.is_none());
    }

    #[tokio::test]
    async fn event_replay_stops_at_the_actor_filtered_watermark() {
        let store = Store::in_memory().await.unwrap();
        let state = AppState::new("secret", store, 0);
        let alice = Scope {
            organization_id: Id("org".into()),
            team_id: Id("team".into()),
            actor_id: Id("alice".into()),
            goal_id: None,
            task_id: None,
        };
        let mut bob = alice.clone();
        bob.actor_id = Id("bob".into());
        for (scope, kind) in [(&alice, "alice.before"), (&bob, "bob.at-watermark")] {
            state
                .publish(Event {
                    id: Id::new("evt"),
                    sequence: 0,
                    timestamp: Utc::now(),
                    scope: scope.clone(),
                    session_id: None,
                    turn_id: None,
                    kind: kind.into(),
                    payload: serde_json::json!({}),
                })
                .await
                .unwrap();
        }
        let watermark = state
            .store
            .latest_team_event_sequence(&alice)
            .await
            .unwrap();
        state
            .publish(Event {
                id: Id::new("evt"),
                sequence: 0,
                timestamp: Utc::now(),
                scope: alice.clone(),
                session_id: None,
                turn_id: None,
                kind: "alice.after".into(),
                payload: serde_json::json!({}),
            })
            .await
            .unwrap();

        let events = tokio::time::timeout(
            std::time::Duration::from_secs(1),
            replay_events_through(
                &state,
                &alice,
                1,
                watermark,
                EventVisibility {
                    private_execution: true,
                    team_dashboard: true,
                    team_approver: false,
                },
            ),
        )
        .await
        .expect("bounded replay must not loop on the post-watermark actor event")
        .unwrap();
        assert!(events.is_empty());
    }

    #[test]
    fn live_events_never_move_backwards_from_an_ahead_cursor() {
        let replay_through = 40;
        let requested_after = 50;
        assert!(!live_event_follows_requested_cursor(
            41,
            replay_through,
            requested_after
        ));
        assert!(!live_event_follows_requested_cursor(
            50,
            replay_through,
            requested_after
        ));
        assert!(live_event_follows_requested_cursor(
            51,
            replay_through,
            requested_after
        ));
    }

