    #[tokio::test]
    async fn runtime_scopes_close_turns_with_their_owning_session() {
        let scopes = RuntimeScopes::default();
        let first = CancellationToken::new();
        let second = CancellationToken::new();
        scopes
            .open_turn(Id("session-a".into()), Id("turn-a".into()), first.clone())
            .await
            .unwrap();
        scopes
            .open_turn(Id("session-b".into()), Id("turn-b".into()), second.clone())
            .await
            .unwrap();
        let (terminal_tx, terminal_rx) = std_mpsc::channel();
        scopes
            .register_background_terminal(
                Id("session-a".into()),
                Id("terminal-a".into()),
                BackgroundTerminalHandle {
                    commands: terminal_tx,
                },
            )
            .await
            .unwrap();
        assert!(
            scopes
                .open_turn(
                    Id("session-b".into()),
                    Id("turn-a".into()),
                    CancellationToken::new(),
                )
                .await
                .is_err()
        );

        scopes.close_session(&Id("session-a".into())).await;

        assert!(first.is_cancelled());
        assert!(!second.is_cancelled());
        assert!(!scopes.contains_turn(&Id("turn-a".into())).await);
        assert!(scopes.contains_turn(&Id("turn-b".into())).await);
        assert!(matches!(
            terminal_rx.recv_timeout(Duration::from_secs(1)),
            Ok(BackgroundTerminalCommand::Stop)
        ));
        assert!(
            scopes
                .background_terminal(&Id("terminal-a".into()))
                .await
                .is_none()
        );
        assert!(
            scopes
                .open_turn(
                    Id("session-a".into()),
                    Id("turn-after-close".into()),
                    CancellationToken::new(),
                )
                .await
                .is_err()
        );
        let (closed_terminal_tx, _closed_terminal_rx) = std_mpsc::channel();
        assert!(
            scopes
                .register_background_terminal(
                    Id("session-a".into()),
                    Id("terminal-after-close".into()),
                    BackgroundTerminalHandle {
                        commands: closed_terminal_tx,
                    },
                )
                .await
                .is_err()
        );
        scopes.reopen_session(&Id("session-a".into())).await;
        scopes
            .open_turn(
                Id("session-a".into()),
                Id("turn-after-restore".into()),
                CancellationToken::new(),
            )
            .await
            .unwrap();
    }

    #[tokio::test]
    async fn runtime_scopes_bound_the_handoff_between_agent_runs() {
        let scopes = RuntimeScopes::default();
        let turn_id = Id("turn-handoff".into());
        scopes
            .open_turn(
                Id("session-handoff".into()),
                turn_id.clone(),
                CancellationToken::new(),
            )
            .await
            .unwrap();

        let waiting_scopes = scopes.clone();
        let waiting_turn_id = turn_id.clone();
        let handoff = tokio::spawn(async move {
            waiting_scopes
                .wait_for_turn_closed(&waiting_turn_id, Duration::from_secs(1))
                .await
        });
        tokio::task::yield_now().await;
        assert!(!handoff.is_finished());

        scopes.close_turn(&turn_id).await;
        tokio::time::timeout(Duration::from_secs(1), handoff)
            .await
            .unwrap()
            .unwrap()
            .unwrap();
    }

