    #[tokio::test]
    async fn approval_resumes_checkpointed_agent_turn() {
        let workspace = tempfile::tempdir().unwrap();
        let workspace_uri = url::Url::from_directory_path(workspace.path())
            .unwrap()
            .to_string();
        let provider = SequenceProvider {
            responses: StdMutex::new(VecDeque::from([
                vec![
                    s_code_model_gateway::ModelEvent::ToolCallDelta {
                        index: 0,
                        id: Some("model_call_1".into()),
                        name: Some("apply_patch".into()),
                        arguments_delta:
                            r#"{"path":"created.txt","expected_sha256":null,"content":"approved"}"#
                                .into(),
                        provider_metadata: None,
                    },
                    s_code_model_gateway::ModelEvent::Completed {
                        finish_reason: Some("tool_calls".into()),
                    },
                ],
                vec![
                    s_code_model_gateway::ModelEvent::TextDelta {
                        text: "write complete".into(),
                    },
                    s_code_model_gateway::ModelEvent::Completed {
                        finish_reason: Some("stop".into()),
                    },
                ],
            ])),
        };
        let store = Store::in_memory().await.unwrap();
        let service =
            app(AppState::new("secret", store.clone(), 0).with_model_provider(Arc::new(provider)));
        let scope = Scope {
            organization_id: Id("org".into()),
            team_id: Id("team".into()),
            actor_id: Id("user".into()),
            goal_id: None,
            task_id: None,
        };
        let session = store
            .create_session(CreateSession {
                scope: scope.clone(),
                workspace_uri,
                title: "approval".into(),
                model: "mock".into(),
            })
            .await
            .unwrap();
        let start = Request::builder()
            .method("POST")
            .uri(format!("/v1/sessions/{}/turns", session.id.0))
            .header("authorization", "Bearer secret")
            .header("content-type", "application/json")
            .body(Body::from(
                serde_json::to_string(&CreateTurn {
                    scope: scope.clone(),
                    content: serde_json::json!("create file"),
                    attachment_ids: vec![],
                    generate_title: true,
                })
                .unwrap(),
            ))
            .unwrap();
        let response = service.clone().oneshot(start).await.unwrap();
        let turn: Turn =
            serde_json::from_slice(&to_bytes(response.into_body(), 64 * 1024).await.unwrap())
                .unwrap();
        let mut waiting = turn;
        for _ in 0..50 {
            waiting = store.get_turn(&scope, &waiting.id).await.unwrap();
            if waiting.status == TurnStatus::AwaitingApproval {
                break;
            }
            tokio::time::sleep(std::time::Duration::from_millis(10)).await;
        }
        assert_eq!(waiting.status, TurnStatus::AwaitingApproval);
        // The turn row and replayable event are separate durable writes. Seeing the
        // state transition does not imply the immediately following event append has
        // completed, so assert eventual external visibility instead of racing that
        // sub-operation boundary.
        let mut approval_events = Vec::new();
        for _ in 0..50 {
            approval_events = store.list_events(&scope.team_id, 0, 100).await.unwrap();
            if approval_events
                .iter()
                .any(|event| event.kind == "approval.required")
            {
                break;
            }
            tokio::time::sleep(std::time::Duration::from_millis(10)).await;
        }
        let approval_event = approval_events
            .iter()
            .find(|event| event.kind == "approval.required")
            .expect("Agent approval must become visible to every client");
        assert_eq!(approval_event.payload["tool"], "apply_patch");
        assert!(approval_event.payload["approval_id"].as_str().is_some());
        assert_eq!(
            approval_event.payload["approval_request"]["summary"],
            "Edit workspace file · created.txt"
        );
        assert_eq!(
            approval_event.payload["approval_request"]["target"],
            "created.txt"
        );
        assert_eq!(
            approval_event.payload["approval_request"]["allowed_scopes"],
            serde_json::json!(["once"])
        );
        let durable = store
            .create_durable_task(CreateDurableTask {
                scope: scope.clone(),
                kind: "agent.turn".into(),
                payload: serde_json::json!({"session_id":session.id,"content":"create file"}),
                idempotency_key: "approval-reconcile".into(),
                max_attempts: 2,
                max_runtime_seconds: 60,
                max_cost_micros: 1_000,
                max_runner_cost_micros: 0,
            })
            .await
            .unwrap();
        let leased = store
            .lease_durable_task("approval-worker", 30)
            .await
            .unwrap()
            .unwrap();
        let lease_token = leased.lease_token.unwrap();
        store
            .checkpoint_durable_task(
                &durable.id,
                &lease_token,
                &serde_json::json!({"turn_id":waiting.id,"phase":"awaiting_approval"}),
                0,
            )
            .await
            .unwrap();
        store
            .set_durable_task_status(&scope, &durable.id, DurableTaskStatus::Paused)
            .await
            .unwrap();
        let approval_id =
            waiting.checkpoint.as_ref().unwrap()["result"]["status"]["detail"]["approval"]["id"]
                .as_str()
                .unwrap();
        let approve = Request::builder()
            .method("POST")
            .uri(format!("/v1/approvals/{approval_id}"))
            .header("authorization", "Bearer secret")
            .header("content-type", "application/json")
            .body(Body::from(
                serde_json::to_string(&ResolveApproval {
                    scope: scope.clone(),
                    approved: true,
                    approval_scope: s_code_protocol::ApprovalScope::Once,
                })
                .unwrap(),
            ))
            .unwrap();
        let response = service.oneshot(approve).await.unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        let mut completed = waiting;
        for _ in 0..50 {
            completed = store.get_turn(&scope, &completed.id).await.unwrap();
            if completed.status == TurnStatus::Completed {
                break;
            }
            tokio::time::sleep(std::time::Duration::from_millis(10)).await;
        }
        assert_eq!(completed.status, TurnStatus::Completed);
        let mut reconciled = store.get_durable_task(&scope, &durable.id).await.unwrap();
        for _ in 0..50 {
            reconciled = store.get_durable_task(&scope, &durable.id).await.unwrap();
            if reconciled.status == DurableTaskStatus::Succeeded {
                break;
            }
            tokio::time::sleep(std::time::Duration::from_millis(10)).await;
        }
        assert_eq!(reconciled.status, DurableTaskStatus::Succeeded);
        assert_eq!(
            std::fs::read_to_string(workspace.path().join("created.txt")).unwrap(),
            "approved"
        );
    }

    #[tokio::test]
    async fn ide_context_is_injected_with_provenance_and_budgeting() {
        let workspace = tempfile::tempdir().unwrap();
        let workspace_uri = url::Url::from_directory_path(workspace.path())
            .unwrap()
            .to_string();
        let scope = Scope {
            organization_id: Id("org".into()),
            team_id: Id("team".into()),
            actor_id: Id("user".into()),
            goal_id: None,
            task_id: None,
        };
        let store = Store::in_memory().await.unwrap();
        let session = store
            .create_session(CreateSession {
                scope: scope.clone(),
                workspace_uri: workspace_uri.clone(),
                title: "IDE".into(),
                model: "mock".into(),
            })
            .await
            .unwrap();
        let captured = Arc::new(StdMutex::new(None));
        let service = app(
            AppState::new("secret", store.clone(), 0).with_model_provider(Arc::new(
                CapturingProvider {
                    request: captured.clone(),
                },
            )),
        );
        store
            .create_team_knowledge(CreateTeamKnowledgeItem {
                scope: scope.clone(),
                source_uri: "knowledge://runbook".into(),
                title: "Runbook".into(),
                content: "Use the safe rollout.".into(),
                version: "3".into(),
                trust_level: "reviewed".into(),
                permission: "team".into(),
                valid_until: None,
            })
            .await
            .unwrap();
        let context = UpdateEditorContext {
            scope: scope.clone(),
            protocol_version: s_code_protocol::IDE_PROTOCOL_VERSION.into(),
            client_instance_id: Id("vscode_1".into()),
            workspace_uri,
            active_document: Some(s_code_protocol::EditorDocument {
                uri: "file:///workspace/src/lib.rs".into(),
                language_id: "rust".into(),
                version: 2,
                text: Some("fn selected() {}".into()),
            }),
            selection: Some(s_code_protocol::EditorSelection {
                range: s_code_protocol::EditorRange {
                    start: s_code_protocol::EditorPosition {
                        line: 0,
                        character: 0,
                    },
                    end: s_code_protocol::EditorPosition {
                        line: 0,
                        character: 2,
                    },
                },
                text: "fn".into(),
            }),
            diagnostics: vec![],
        };
        let update = Request::builder()
            .method("POST")
            .uri(format!("/v1/sessions/{}/editor-context", session.id.0))
            .header("authorization", "Bearer secret")
            .header("content-type", "application/json")
            .body(Body::from(serde_json::to_string(&context).unwrap()))
            .unwrap();
        assert_eq!(
            service.clone().oneshot(update).await.unwrap().status(),
            StatusCode::OK
        );
        let start = Request::builder()
            .method("POST")
            .uri(format!("/v1/sessions/{}/turns", session.id.0))
            .header("authorization", "Bearer secret")
            .header("content-type", "application/json")
            .body(Body::from(
                serde_json::to_string(&CreateTurn {
                    scope,
                    content: serde_json::json!("explain selection"),
                    attachment_ids: vec![],
                    generate_title: true,
                })
                .unwrap(),
            ))
            .unwrap();
        assert_eq!(
            service.oneshot(start).await.unwrap().status(),
            StatusCode::ACCEPTED
        );
        for _ in 0..50 {
            if captured.lock().unwrap().is_some() {
                break;
            }
            tokio::time::sleep(std::time::Duration::from_millis(10)).await;
        }
        let request = captured.lock().unwrap().clone().unwrap();
        let system = request
            .messages
            .iter()
            .find(|message| message.role == "system" && message.content.get("context").is_some())
            .unwrap();
        let encoded = system.content.to_string();
        assert!(encoded.contains("ide:selection"));
        assert!(encoded.contains("editor-untrusted"));
        assert!(encoded.contains("team-knowledge:"));
        assert!(encoded.contains("knowledge://runbook"));
        assert!(encoded.contains("cite its exact source URI"));
    }

    #[tokio::test]
    async fn team_approval_and_audit_views_are_scoped_content_free_projections() {
        let directory = tempfile::tempdir().unwrap();
        let scope = Scope {
            organization_id: Id("org".into()),
            team_id: Id("team".into()),
            actor_id: Id("user".into()),
            goal_id: None,
            task_id: None,
        };
        let store = Store::in_memory().await.unwrap();
        let session = store
            .create_session(CreateSession {
                scope: scope.clone(),
                workspace_uri: url::Url::from_directory_path(directory.path())
                    .unwrap()
                    .to_string(),
                title: "Approval source".into(),
                model: "model".into(),
            })
            .await
            .unwrap();
        let service = app(AppState::new("secret", store, 0));
        let submit = service
            .clone()
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri(format!("/v1/sessions/{}/tools", session.id.0))
                    .header(header::AUTHORIZATION, "Bearer secret")
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(
                        serde_json::to_vec(&SubmitToolCall {
                            scope: scope.clone(),
                            tool: "run_command".into(),
                            arguments: serde_json::json!({
                                "program": "/bin/echo",
                                "args": ["--api-key", "private-value"],
                            }),
                        })
                        .unwrap(),
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(submit.status(), StatusCode::CREATED);
        let pending: ToolCallOutcome =
            serde_json::from_slice(&to_bytes(submit.into_body(), 64 * 1024).await.unwrap())
                .unwrap();
        let pending_turn_id = match &pending {
            ToolCallOutcome::AwaitingApproval { tool_call, .. } => {
                tool_call.request.turn_id.clone()
            }
            other => panic!("run command must await approval: {other:?}"),
        };

        let approvals = service
            .clone()
            .oneshot(
                Request::builder()
                    .uri("/v1/teams/team/approvals?organization_id=org&actor_id=user&limit=20")
                    .header(header::AUTHORIZATION, "Bearer secret")
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(approvals.status(), StatusCode::OK);
        let approval_bytes = to_bytes(approvals.into_body(), 64 * 1024).await.unwrap();
        let approval_rows: Vec<ApprovalRequest> = serde_json::from_slice(&approval_bytes).unwrap();
        assert_eq!(approval_rows.len(), 1);
        assert!(approval_rows[0].summary.contains("/bin/echo"));
        assert!(approval_rows[0].summary.contains("•••"));
        assert!(!String::from_utf8_lossy(&approval_bytes).contains("private-value"));

        let audit = service
            .clone()
            .oneshot(
                Request::builder()
                    .uri("/v1/teams/team/audit?organization_id=org&actor_id=user&limit=20")
                    .header(header::AUTHORIZATION, "Bearer secret")
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(audit.status(), StatusCode::OK);
        let audit_bytes = to_bytes(audit.into_body(), 64 * 1024).await.unwrap();
        let audit_page: AuditEventPage = serde_json::from_slice(&audit_bytes).unwrap();
        assert!(audit_page.events.iter().any(|event| {
            event.kind == "approval.required"
                && event.session_id.as_ref() == Some(&session.id)
                && event.turn_id.as_ref() == Some(&pending_turn_id)
        }));
        let serialized = String::from_utf8_lossy(&audit_bytes);
        assert!(!serialized.contains("payload"));
        assert!(!serialized.contains("private-value"));
        let filtered = service
            .clone()
            .oneshot(
                Request::builder()
                    .uri(format!(
                        "/v1/teams/team/audit?organization_id=org&actor_id=user&kind=approval.required&session_id={}&limit=20",
                        session.id.0
                    ))
                    .header(header::AUTHORIZATION, "Bearer secret")
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        let filtered: AuditEventPage =
            serde_json::from_slice(&to_bytes(filtered.into_body(), 64 * 1024).await.unwrap())
                .unwrap();
        assert_eq!(filtered.events.len(), 1);
        assert_eq!(filtered.events[0].kind, "approval.required");
        let exported = service
            .clone()
            .oneshot(
                Request::builder()
                    .uri("/v1/teams/team/audit/export?organization_id=org&actor_id=user&kind=approval.required&limit=100")
                    .header(header::AUTHORIZATION, "Bearer secret")
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(exported.status(), StatusCode::OK);
        assert_eq!(
            exported.headers()[header::CONTENT_TYPE],
            "text/csv; charset=utf-8"
        );
        let csv = String::from_utf8(
            to_bytes(exported.into_body(), 64 * 1024)
                .await
                .unwrap()
                .to_vec(),
        )
        .unwrap();
        assert!(csv.contains("\"approval.required\""));
        assert!(csv.contains(&session.id.0));
        assert!(!csv.contains("private-value"));

        let route = service
            .oneshot(
                Request::builder()
                    .uri("/team/outcomes")
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(route.status(), StatusCode::OK);
    }

