    #[tokio::test]
    async fn community_mcp_oauth_uses_discovery_pkce_one_time_state_and_revocation() {
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let provider = format!("http://{}", listener.local_addr().unwrap());
        let token_requests = Arc::new(AtomicUsize::new(0));
        let revocations = Arc::new(AtomicUsize::new(0));
        let provider_for_resource = provider.clone();
        let provider_for_metadata = provider.clone();
        let token_requests_for_route = token_requests.clone();
        let revocations_for_route = revocations.clone();
        let provider_service = Router::new()
            .route("/mcp", get(|| async { StatusCode::UNAUTHORIZED }))
            .route(
                "/.well-known/oauth-protected-resource/mcp",
                get(move || {
                    let provider = provider_for_resource.clone();
                    async move {
                        Json(serde_json::json!({
                            "authorization_servers": [provider],
                            "scopes_supported": ["mcp:tools", "mcp:resources"]
                        }))
                    }
                }),
            )
            .route(
                "/.well-known/oauth-authorization-server",
                get(move || {
                    let provider = provider_for_metadata.clone();
                    async move {
                        Json(serde_json::json!({
                            "issuer": provider,
                            "authorization_endpoint": format!("{provider}/authorize"),
                            "token_endpoint": format!("{provider}/token"),
                            "registration_endpoint": format!("{provider}/register"),
                            "revocation_endpoint": format!("{provider}/revoke"),
                            "scopes_supported": ["mcp:tools", "mcp:resources"],
                            "code_challenge_methods_supported": ["S256"]
                        }))
                    }
                }),
            )
            .route(
                "/register",
                post(|| async {
                    Json(serde_json::json!({
                        "client_id": "s-code-dynamic-public-client"
                    }))
                }),
            )
            .route(
                "/token",
                post(move || {
                    let requests = token_requests_for_route.clone();
                    async move {
                        requests.fetch_add(1, AtomicOrdering::SeqCst);
                        Json(serde_json::json!({
                            "access_token": "provider-access-secret",
                            "token_type": "Bearer",
                            "refresh_token": "provider-refresh-secret",
                            "expires_in": 3600,
                            "scope": "mcp:tools"
                        }))
                    }
                }),
            )
            .route(
                "/revoke",
                post(move || {
                    let revocations = revocations_for_route.clone();
                    async move {
                        revocations.fetch_add(1, AtomicOrdering::SeqCst);
                        StatusCode::OK
                    }
                }),
            );
        let provider_task = tokio::spawn(async move {
            axum::serve(listener, provider_service).await.unwrap();
        });

        let scope = Scope {
            organization_id: Id("org".into()),
            team_id: Id("team".into()),
            actor_id: Id("user".into()),
            goal_id: None,
            task_id: None,
        };
        let server = McpHttpServerSpec {
            id: "oauth-tools".into(),
            endpoint: format!("{provider}/mcp"),
            header_handles: BTreeMap::new(),
            oauth: Some(McpOAuthSpec {
                client_id: None,
                scopes: vec!["mcp:tools".into()],
            }),
            timeout_ms: 30_000,
        };
        let store = Store::in_memory().await.unwrap();
        let service = app(AppState::new("secret", store.clone(), 0));
        let preview_response = service
            .clone()
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri("/v1/extensions/mcp-http/preview")
                    .header(header::AUTHORIZATION, "Bearer secret")
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(
                        serde_json::to_vec(&PreviewMcpHttpServerInstall {
                            scope: scope.clone(),
                            server: server.clone(),
                        })
                        .unwrap(),
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(preview_response.status(), StatusCode::OK);
        let install_preview: ExtensionInstallPreview = serde_json::from_slice(
            &to_bytes(preview_response.into_body(), 64 * 1024)
                .await
                .unwrap(),
        )
        .unwrap();
        assert!(install_preview.descriptor.oauth_supported);
        assert!(
            install_preview
                .descriptor
                .permissions
                .iter()
                .any(|permission| permission.value.contains("OAuth protected-resource"))
        );
        let installed = service
            .clone()
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri("/v1/extensions/mcp-http/install")
                    .header(header::AUTHORIZATION, "Bearer secret")
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(
                        serde_json::to_vec(&InstallMcpHttpServer {
                            scope: scope.clone(),
                            server,
                            confirmation: ExtensionConfirmation {
                                confirmed: true,
                                permissions_sha256: install_preview.permissions_sha256,
                            },
                        })
                        .unwrap(),
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(installed.status(), StatusCode::CREATED);

        let discovery_response = service
            .clone()
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri("/v1/extensions/mcp-http/oauth-tools/oauth/preview")
                    .header(header::AUTHORIZATION, "Bearer secret")
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(
                        serde_json::to_vec(&PreviewMcpOAuth {
                            scope: scope.clone(),
                        })
                        .unwrap(),
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(discovery_response.status(), StatusCode::OK);
        let discovery: McpOAuthDiscovery = serde_json::from_slice(
            &to_bytes(discovery_response.into_body(), 64 * 1024)
                .await
                .unwrap(),
        )
        .unwrap();
        assert_eq!(discovery.scopes, ["mcp:tools"]);

        let launch_response = service
            .clone()
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri("/v1/extensions/mcp-http/oauth-tools/oauth")
                    .header(header::HOST, "127.0.0.1:18788")
                    .header(header::AUTHORIZATION, "Bearer secret")
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(
                        serde_json::to_vec(&StartMcpOAuth {
                            scope: scope.clone(),
                            confirmation: ExtensionConfirmation {
                                confirmed: true,
                                permissions_sha256: discovery.permissions_sha256,
                            },
                        })
                        .unwrap(),
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(launch_response.status(), StatusCode::OK);
        let launch: McpOAuthLaunch = serde_json::from_slice(
            &to_bytes(launch_response.into_body(), 64 * 1024)
                .await
                .unwrap(),
        )
        .unwrap();
        let login_url = url::Url::parse(&launch.authorization_url).unwrap();
        let parameters = login_url
            .query_pairs()
            .into_owned()
            .collect::<BTreeMap<_, _>>();
        assert_eq!(
            parameters.get("code_challenge_method").map(String::as_str),
            Some("S256")
        );
        assert!(
            parameters
                .get("code_challenge")
                .is_some_and(|value| value.len() == 43)
        );
        assert!(!launch.authorization_url.contains("provider-access-secret"));
        let oauth_state = parameters.get("state").unwrap();

        let callback = service
            .clone()
            .oneshot(
                Request::builder()
                    .uri(format!(
                        "/v1/mcp/oauth/callback?code=provider-code&state={oauth_state}"
                    ))
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(callback.status(), StatusCode::OK);
        assert_eq!(token_requests.load(AtomicOrdering::SeqCst), 1);
        assert_eq!(
            store
                .get_mcp_oauth_credential(&scope, "oauth-tools")
                .await
                .unwrap()
                .access_token,
            "provider-access-secret"
        );

        let replay = service
            .clone()
            .oneshot(
                Request::builder()
                    .uri(format!(
                        "/v1/mcp/oauth/callback?code=replay&state={oauth_state}"
                    ))
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(replay.status(), StatusCode::BAD_REQUEST);
        assert_eq!(token_requests.load(AtomicOrdering::SeqCst), 1);

        let status = service
            .clone()
            .oneshot(
                Request::builder()
                    .uri("/v1/extensions/mcp-http/oauth-tools/oauth?organization_id=org&team_id=team&actor_id=user")
                    .header(header::AUTHORIZATION, "Bearer secret")
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        let status: McpOAuthStatus =
            serde_json::from_slice(&to_bytes(status.into_body(), 64 * 1024).await.unwrap())
                .unwrap();
        assert!(status.authenticated);
        assert_eq!(status.scopes, ["mcp:tools"]);

        let logout = service
            .oneshot(
                Request::builder()
                    .method("DELETE")
                    .uri("/v1/extensions/mcp-http/oauth-tools/oauth")
                    .header(header::AUTHORIZATION, "Bearer secret")
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(
                        serde_json::to_vec(&LogoutMcpOAuth { scope }).unwrap(),
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(logout.status(), StatusCode::OK);
        assert_eq!(revocations.load(AtomicOrdering::SeqCst), 1);
        assert!(
            store
                .get_mcp_oauth_credential(
                    &Scope {
                        organization_id: Id("org".into()),
                        team_id: Id("team".into()),
                        actor_id: Id("user".into()),
                        goal_id: None,
                        task_id: None,
                    },
                    "oauth-tools",
                )
                .await
                .is_err()
        );
        provider_task.abort();
    }

    #[tokio::test]
    async fn mcp_elicitation_is_encrypted_reviewable_declineable_and_schema_validated() {
        let scope = Scope {
            organization_id: Id("org".into()),
            team_id: Id("team".into()),
            actor_id: Id("user".into()),
            goal_id: None,
            task_id: None,
        };
        let store = Store::connect_encrypted("sqlite::memory:", "elicitation-key", &[6_u8; 32])
            .await
            .unwrap();
        let session = store
            .create_session(CreateSession {
                scope: scope.clone(),
                workspace_uri: "file:///workspace".into(),
                title: "MCP elicitation".into(),
                model: "fixture".into(),
            })
            .await
            .unwrap();
        let turn = store.create_turn(&scope, &session.id).await.unwrap();
        let state = AppState::new("secret", store.clone(), 0);
        let handler = DaemonMcpElicitationHandler {
            events: state.event_publisher(),
            scope: scope.clone(),
            session_id: session.id.clone(),
            turn_id: turn.id.clone(),
            tool_call_id: Id("tool-call".into()),
        };
        let elicitation = tokio::spawn(async move {
            handler
                .elicit(McpElicitationRequest {
                    request_id: serde_json::json!("request-1"),
                    server_id: "fixture".into(),
                    message: "Provide a display name.".into(),
                    requested_schema: serde_json::json!({
                        "type": "object",
                        "properties": {"display_name": {"type": "string"}},
                        "required": ["display_name"]
                    }),
                })
                .await
        });
        let pending = loop {
            let pending = store
                .list_pending_session_question_requests(&scope, &session.id)
                .await
                .unwrap();
            if let Some(pending) = pending.into_iter().next() {
                break pending;
            }
            tokio::time::sleep(std::time::Duration::from_millis(10)).await;
        };
        store
            .resolve_question_request(
                &scope,
                &pending.id,
                &[
                    QuestionAnswer {
                        question_id: "mcp_content".into(),
                        answer: r#"{"display_name":"Reviewed"}"#.into(),
                    },
                    QuestionAnswer {
                        question_id: "mcp_action".into(),
                        answer: "Accept".into(),
                    },
                ],
            )
            .await
            .unwrap();
        assert_eq!(
            elicitation.await.unwrap().unwrap(),
            McpElicitationResponse::Accept {
                content: serde_json::json!({"display_name": "Reviewed"})
            }
        );
        assert!(
            validate_mcp_elicitation_schema(&serde_json::json!({
                "type": "object",
                "properties": {"api_token": {"type": "string"}}
            }))
            .is_err()
        );
        assert!(
            validate_mcp_elicitation_content(
                &serde_json::json!({
                    "type": "object",
                    "properties": {"count": {"type": "integer"}},
                    "required": ["count"]
                }),
                &serde_json::json!({"count": "not-an-integer"})
            )
            .is_err()
        );
    }

    #[cfg(unix)]
    #[test]
    fn local_extension_sources_reject_symlinked_and_swapped_parents() {
        use std::os::unix::fs::symlink;

        let selected = tempfile::tempdir().unwrap();
        let outside = tempfile::tempdir().unwrap();
        std::fs::write(
            outside.path().join("marketplace.json"),
            r#"{"name":"local","plugins":[]}"#,
        )
        .unwrap();
        symlink(outside.path(), selected.path().join(".codex")).unwrap();
        let source = MarketplaceSource {
            name: "local".into(),
            source_uri: url::Url::from_file_path(selected.path())
                .unwrap()
                .to_string(),
            source_kind: MarketplaceSourceKind::Local,
        };
        assert!(prepare_marketplace(&source).is_err());

        let selected_parent = tempfile::tempdir().unwrap();
        symlink(outside.path(), selected_parent.path().join("parent-link")).unwrap();
        std::fs::create_dir(outside.path().join("source")).unwrap();
        std::fs::write(
            outside.path().join("source/marketplace.json"),
            r#"{"name":"local","plugins":[]}"#,
        )
        .unwrap();
        let linked_marketplace = prepare_marketplace(&MarketplaceSource {
            name: "local".into(),
            source_uri: url::Url::from_file_path(selected_parent.path().join("parent-link/source"))
                .unwrap()
                .to_string(),
            source_kind: MarketplaceSourceKind::Local,
        })
        .unwrap();
        assert_eq!(
            linked_marketplace.source.source_uri,
            url::Url::from_file_path(outside.path().join("source").canonicalize().unwrap())
                .unwrap()
                .to_string()
        );

        std::fs::write(outside.path().join("source/SKILL.md"), "explicit target\n").unwrap();
        let selected_skill = selected_parent.path().join("parent-link/source/SKILL.md");
        let (normalized, instructions, _) = read_skill_instructions(&SkillSpec {
            id: "linked-skill".into(),
            name: "Linked Skill".into(),
            description: "Explicitly bind the resolved local source.".into(),
            source_uri: url::Url::from_file_path(&selected_skill)
                .unwrap()
                .to_string(),
            activation_terms: Vec::new(),
            mcp_dependencies: Vec::new(),
            auto_match: false,
        })
        .unwrap();
        assert_eq!(instructions, "explicit target\n");
        assert_eq!(
            normalized.source_uri,
            url::Url::from_file_path(
                outside
                    .path()
                    .join("source/SKILL.md")
                    .canonicalize()
                    .unwrap(),
            )
            .unwrap()
            .to_string()
        );

        let package_parent = tempfile::tempdir().unwrap();
        let marketplace_root = package_parent.path().join("marketplace");
        let outside_root = package_parent.path().join("sibling-outside-root");
        std::fs::create_dir_all(&marketplace_root).unwrap();
        std::fs::create_dir_all(&outside_root).unwrap();
        std::fs::write(outside_root.join("SKILL.md"), "must remain outside\n").unwrap();
        std::fs::write(
            marketplace_root.join("entry.json"),
            r#"{"name":"escape","version":"1.0.0","skills":"sibling-outside-root/SKILL.md"}"#,
        )
        .unwrap();
        std::fs::write(
            marketplace_root.join("marketplace.json"),
            r#"{"name":"bounded","plugins":[{"name":"escape","source":"entry.json"}]}"#,
        )
        .unwrap();
        let unsafe_marketplace = prepare_marketplace(&MarketplaceSource {
            name: "bounded".into(),
            source_uri: url::Url::from_directory_path(&marketplace_root)
                .unwrap()
                .to_string(),
            source_kind: MarketplaceSourceKind::Local,
        })
        .unwrap();
        assert!(prepare_plugin_bundle(&unsafe_marketplace, "escape").is_err());

        let legal_package = marketplace_root.join("legal");
        std::fs::create_dir_all(legal_package.join(".codex-plugin")).unwrap();
        std::fs::write(
            legal_package.join(".codex-plugin/plugin.json"),
            r#"{"name":"legal","version":"1.0.0"}"#,
        )
        .unwrap();
        std::fs::write(
            marketplace_root.join("marketplace.json"),
            r#"{"name":"bounded","plugins":[{"name":"legal","source":"legal/.codex-plugin/plugin.json"}]}"#,
        )
        .unwrap();
        let legal_marketplace = prepare_marketplace(&MarketplaceSource {
            name: "bounded".into(),
            source_uri: url::Url::from_directory_path(&marketplace_root)
                .unwrap()
                .to_string(),
            source_kind: MarketplaceSourceKind::Local,
        })
        .unwrap();
        let legal_bundle = prepare_plugin_bundle(&legal_marketplace, "legal").unwrap();
        assert_eq!(legal_bundle.name, "legal");

        let selected = tempfile::tempdir().unwrap();
        let selected_path = selected.path().join("source");
        let moved_path = selected.path().join("source-moved");
        let outside = tempfile::tempdir().unwrap();
        std::fs::create_dir(&selected_path).unwrap();
        std::fs::write(selected_path.join("SKILL.md"), "trusted\n").unwrap();
        std::fs::write(outside.path().join("SKILL.md"), "outside\n").unwrap();
        let authorized_root = selected_path.canonicalize().unwrap();
        std::fs::rename(&selected_path, &moved_path).unwrap();
        symlink(outside.path(), &selected_path).unwrap();
        assert!(
            read_bounded_regular_file(
                &authorized_root,
                &authorized_root.join("SKILL.md"),
                64 * 1024,
            )
            .is_err()
        );
    }

    #[cfg(unix)]
    #[tokio::test]
    async fn marketplace_upgrade_persists_the_confirmed_canonical_source() {
        use std::os::unix::fs::symlink;

        let scope = Scope {
            organization_id: Id("org".into()),
            team_id: Id("team".into()),
            actor_id: Id("user".into()),
            goal_id: None,
            task_id: None,
        };
        let selected = tempfile::tempdir().unwrap();
        let actual = tempfile::tempdir().unwrap();
        std::fs::create_dir(actual.path().join("source")).unwrap();
        std::fs::write(
            actual.path().join("source/marketplace.json"),
            r#"{"name":"local","plugins":[]}"#,
        )
        .unwrap();
        symlink(actual.path(), selected.path().join("parent-link")).unwrap();
        let selected_source = MarketplaceSource {
            name: "local".into(),
            source_uri: url::Url::from_file_path(selected.path().join("parent-link/source"))
                .unwrap()
                .to_string(),
            source_kind: MarketplaceSourceKind::Local,
        };
        let prepared = prepare_marketplace(&selected_source).unwrap();
        let canonical_source = prepared.source.clone();
        assert_ne!(selected_source.source_uri, canonical_source.source_uri);

        let store = Store::connect_encrypted("sqlite::memory:", "marketplace-key", &[9_u8; 32])
            .await
            .unwrap();
        store
            .add_marketplace(&scope, &selected_source, &prepared.manifest_sha256)
            .await
            .unwrap();
        let service = app(AppState::new("secret", store.clone(), 0));
        let preview = service
            .clone()
            .oneshot(
                Request::builder()
                    .uri("/v1/marketplaces/local/preview-upgrade?organization_id=org&team_id=team&actor_id=user")
                    .method("POST")
                    .header(header::AUTHORIZATION, "Bearer secret")
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(preview.status(), StatusCode::OK);
        let preview: ExtensionInstallPreview =
            serde_json::from_slice(&to_bytes(preview.into_body(), 64 * 1024).await.unwrap())
                .unwrap();
        assert_eq!(preview.descriptor.source_uri, canonical_source.source_uri);

        let upgraded = service
            .oneshot(
                Request::builder()
                    .uri("/v1/marketplaces/local")
                    .method("POST")
                    .header(header::AUTHORIZATION, "Bearer secret")
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(
                        serde_json::to_vec(&UpgradeMarketplace {
                            scope: scope.clone(),
                            confirmation: s_code_protocol::ExtensionConfirmation {
                                confirmed: true,
                                permissions_sha256: preview.permissions_sha256,
                            },
                        })
                        .unwrap(),
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(upgraded.status(), StatusCode::OK);
        let upgraded: MarketplaceInstallation =
            serde_json::from_slice(&to_bytes(upgraded.into_body(), 64 * 1024).await.unwrap())
                .unwrap();
        assert_eq!(upgraded.source, canonical_source);
        assert_eq!(upgraded.revision, 2);
        assert_eq!(
            store.get_marketplace(&scope, "local").await.unwrap(),
            upgraded
        );
    }

